//
// Spec 020 T7: SelectionController — extracted from app.ts. Owns the
// selected-entity state (selectedEntity + selectedUid) and the click
// routing that follows/moves the camera to the picked entity. The App
// hands it the SceneManager + panels + EntityManager and wires the
// list/scene/control-panel click callbacks onto select().
//
// Behaviour is byte-equivalent to the pre-refactor App: selecting from
// the list or a 3D click resolves the entity's 3D position via the
// EntityManager multi-entity map and follows the camera there.
import { SceneManager } from '../rendering/scene';
import { StateManager } from './state-manager';
import { EntityManager } from './entity-manager';
import { EntityInfoPanel, SelectedEntity } from '../ui/entity-info-panel';
import { EntityListPanel } from '../ui/entity-list-panel';
import { EntityType } from './entity-kind-registry';

export class SelectionController {
  selectedEntity: SelectedEntity = null;
  selectedUid: string | null = null;

  constructor(
    private sceneManager: SceneManager,
    private stateManager: StateManager,
    private entityManager: EntityManager,
    private entityInfoPanel: EntityInfoPanel,
    private entityListPanel: EntityListPanel,
  ) {}

  /** Handle an entity pick (from list, 3D click, or control panel). */
  select(entityType: EntityType, entityId?: string): void {
    this.selectedEntity = entityType;
    this.selectedUid = entityId ?? null;
    this.entityInfoPanel.select(entityType);
    this.entityListPanel.highlight(entityType);
    const state = this.stateManager.getState();
    const pos = this.entityManager.positionForEntity(entityId, state);
    this.sceneManager.follow(pos);
    this.sceneManager.moveCameraTo(pos);
  }

  /** Follow-target refresh on every state tick (call from App). */
  refreshFollow(): void {
    if (this.sceneManager.isFollowingMode && this.selectedEntity) {
      const state = this.stateManager.getState();
      const pos = this.entityManager.positionForEntity(
        this.selectedUid ?? undefined, state);
      this.sceneManager.follow(pos);
    }
  }

  /** Drop the selection if the selected uid is no longer present. */
  reconcileWithState(): void {
    const state = this.stateManager.getState();
    if (this.selectedUid && state.entities && !state.entities[this.selectedUid]) {
      this.selectedUid = null;
    }
  }
}
