import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';

export interface SceneConfig {
  container: HTMLElement;
  antialias?: boolean;
  backgroundColor?: number;
}

/**
 * Performance defaults for the 019 scene.
 *
 * These are exported as named constants + a pure helper so they can be
 * unit-tested without instantiating a WebGLRenderer (which can't run
 * under vitest's node environment). SceneManager reads them at construct
 * time so changing them here changes the live scene.
 */
export const PIXEL_RATIO_CAP = 1.5;
export const SHADOWS_ENABLED_BY_DEFAULT = false;

/** Clamp the device pixel ratio to PIXEL_RATIO_CAP. Pure + testable. */
export function capPixelRatio(devicePixelRatio: number): number {
  const dpr = Number.isFinite(devicePixelRatio) && devicePixelRatio > 0
    ? devicePixelRatio : 1;
  return Math.min(dpr, PIXEL_RATIO_CAP);
}

export interface PerformanceReport {
  fps: number;
  frameTime: number;
}

export type PerformanceCallback = (report: PerformanceReport) => void;

export interface SelectableObject {
  object: THREE.Object3D;
  entityType: 'uav' | 'target' | 'gimbal';
  // Spec 017: optional entity unique_id for multi-entity selection. When
  // present, onEntityClick fires with this string so the app can route
  // selection to the right renderer in the multi-entity map.
  entityId?: string;
}

export type EntityClickCallback = (entityType: 'uav' | 'target' | 'gimbal', entityId?: string) => void;

export class SceneManager {
  private scene: THREE.Scene;
  private camera: THREE.PerspectiveCamera;
  private renderer: THREE.WebGLRenderer;
  private controls: OrbitControls;
  private animationId: number | null = null;
  private updateCallbacks: Array<(delta: number) => void> = [];
  private perfCallback: PerformanceCallback | null = null;
  private frameCount = 0;
  private perfElapsed = 0;

  private raycaster = new THREE.Raycaster();
  private mouse = new THREE.Vector2();
  private selectables: SelectableObject[] = [];
  private onClickCallback: EntityClickCallback | null = null;
  private gridHelper!: THREE.GridHelper;

  private followTarget: THREE.Vector3 | null = null;
  private isFollowing = false;

  // Keyboard pan state (WASD / arrow keys). Polled each frame.
  private keysDown: Set<string> = new Set();
  private keyPanSpeed = 80; // units per second at default zoom

  constructor(config: SceneConfig) {
    // Create scene
    this.scene = new THREE.Scene();
    this.scene.background = new THREE.Color(config.backgroundColor || 0x1a1a2e);

    // Create camera
    this.camera = new THREE.PerspectiveCamera(
      60,
      config.container.clientWidth / config.container.clientHeight,
      0.1,
      10000
    );
    this.camera.position.set(0, 600, 400);  // Spec 024: 抬高初始视角,避免落在地形下方

    // Create renderer
    this.renderer = new THREE.WebGLRenderer({
      antialias: config.antialias !== false,
      powerPreference: 'high-performance',
    });
    this.renderer.setSize(config.container.clientWidth, config.container.clientHeight);
    // Cap the pixel ratio: on high-DPI displays devicePixelRatio is often
    // 2-3, which makes the GPU shade 4-9x the pixels for negligible visual
    // gain and tanks the frame rate on the 019 40-entity scene. 1.5 keeps
    // things crisp without the 4x pixel blow-up.
    this.renderer.setPixelRatio(capPixelRatio(window.devicePixelRatio));
    config.container.appendChild(this.renderer.domElement);

    // Create controls
    this.controls = new OrbitControls(this.camera, this.renderer.domElement);
    this.controls.enableDamping = true;
    this.controls.dampingFactor = 0.05;
    this.controls.screenSpacePanning = true;
    // Explicitly enable pan (left-drag rotates; right-drag or middle-drag
    // pans). OrbitControls defaults enablePan=true, but we set it
    // explicitly for clarity + so the keyboard pan below coexists.
    this.controls.enablePan = true;
    this.controls.enableRotate = true;
    this.controls.enableZoom = true;
    this.controls.minDistance = 10;
    this.controls.maxDistance = 5000;
    // Allow looking slightly below the horizon so panning feels natural
    // when the camera is near the ground (original π/2 locked the view
    // to above-horizon only, which made right-drag pan feel broken).
    this.controls.maxPolarAngle = Math.PI * 0.85;

    // Keyboard movement (WASD + arrow keys) for fly-style camera
    // translation. The keys are polled each frame in start()'s animation
    // loop; movement is applied along the camera's forward/right basis
    // in the horizontal plane (y kept constant) so it behaves like a
    // ground-level survey view.
    this.setupKeyboardControls();

    // Add lights
    this.addLights();

    // Add ground grid
    this.addGroundGrid();

    // Handle window resize
    window.addEventListener('resize', () => this.onWindowResize(config.container));

    // Setup click handler for entity selection
    this.renderer.domElement.addEventListener('click', (event: MouseEvent) => this.onClick(event));
  }

  /**
   * Toggle real-time shadow mapping. Disabled by default because on the
   * 019 scene (10 UAV + 30 vehicle + terrain mesh) the per-frame
   * 1024x1024 PCF shadow pass over a 6000x6000 frustum was the single
   * biggest frame-time contributor, dropping the rate to 5-20 FPS.
   * Operators who want shadows for a still/slow scene can re-enable them.
   */
  setShadowsEnabled(enabled: boolean): void {
    this.renderer.shadowMap.enabled = enabled;
    this.renderer.shadowMap.needsUpdate = true;
    this.scene.traverse((obj) => {
      const mesh = obj as THREE.Mesh;
      if (mesh.isMesh) {
        mesh.castShadow = enabled;
        mesh.receiveShadow = enabled;
      }
    });
  }

  private addLights(): void {
    // Ambient light (soft fill)
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.45);
    this.scene.add(ambientLight);

    // Hemisphere light for natural sky/ground coloring. Slightly bumped
    // from 0.45 to compensate for the disabled directional shadow pass.
    const hemiLight = new THREE.HemisphereLight(0xb0c4de, 0x6b5a3a, 0.65);
    this.scene.add(hemiLight);

    // Directional light for terrain shading. Shadows are OFF by default
    // (see setShadowsEnabled); the light still provides directional
    // shading so the scene isn't flat.
    const directionalLight = new THREE.DirectionalLight(0xffffff, 0.75);
    directionalLight.position.set(100, 200, 100);
    directionalLight.castShadow = false;
    this.scene.add(directionalLight);

    // Configure the shadow pipeline but leave it disabled. Only flipped
    // on by setShadowsEnabled(true) when explicitly requested.
    directionalLight.shadow.mapSize.set(1024, 1024);
    directionalLight.shadow.camera.left = -3000;
    directionalLight.shadow.camera.right = 3000;
    directionalLight.shadow.camera.top = 3000;
    directionalLight.shadow.camera.bottom = -3000;
    directionalLight.shadow.camera.near = 0.1;
    directionalLight.shadow.camera.far = 5000;
    this.renderer.shadowMap.enabled = SHADOWS_ENABLED_BY_DEFAULT;
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  }

  private addGroundGrid(): void {
    // Fewer grid divisions (50 vs 100) — halves the grid line count for a
    // small visual cost and a measurable draw-time saving.
    this.gridHelper = new THREE.GridHelper(2000, 50, 0x38bdf8, 0x1d4a63);
    this.gridHelper.position.y = -0.1;
    this.scene.add(this.gridHelper);
  }

  /**
   * Show or hide the ground grid.
   */
  setGridVisible(visible: boolean): void {
    this.gridHelper.visible = visible;
  }

  /**
   * Keyboard controls for camera translation. We track pressed keys in a
   * Set and poll each frame in the animation loop (better than
   * keydown-driven jumps — gives smooth continuous movement). Only
   * reacts when the canvas/container has focus OR no input element is
   * focused (so typing in a text field doesn't move the camera).
   */
  private setupKeyboardControls(): void {
    window.addEventListener('keydown', (e: KeyboardEvent) => {
      // Don't intercept when the user is typing in an input/textarea.
      const tag = (e.target as HTMLElement)?.tagName;
      if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return;
      const k = e.key.toLowerCase();
      if (['w', 'a', 's', 'd', 'q', 'e',
           'arrowup', 'arrowdown', 'arrowleft', 'arrowright'].includes(k)) {
        this.keysDown.add(k);
        e.preventDefault();
      }
    });
    window.addEventListener('keyup', (e: KeyboardEvent) => {
      this.keysDown.delete(e.key.toLowerCase());
    });
    // Clear keys if the window loses focus (avoid stuck-movement).
    window.addEventListener('blur', () => this.keysDown.clear());
  }

  /**
   * Apply one frame of keyboard-driven camera translation. Called from
   * the animation loop. Moves both the camera AND the orbit target so
   * the view pans as a whole (otherwise the camera would orbit while
   * translating). Movement is along the camera's horizontal basis
   * (forward/right projected onto the XZ plane) + Q/E for vertical.
   */
  private applyKeyboardPan(delta: number): void {
    if (this.keysDown.size === 0) return;
    // If following an entity, keyboard pan takes over (cancels follow).
    if (this.isFollowing) {
      this.isFollowing = false;
      this.followTarget = null;
    }

    // Forward direction projected to horizontal plane (drop Y).
    const forward = new THREE.Vector3();
    this.camera.getWorldDirection(forward);
    forward.y = 0;
    if (forward.lengthSq() < 1e-6) {
      forward.set(0, 0, -1);
    }
    forward.normalize();
    const right = new THREE.Vector3();
    right.crossVectors(forward, new THREE.Vector3(0, 1, 0)).normalize();

    // Speed scales with current distance-to-target so zoomed-out views
    // pan faster (feels consistent with on-screen displacement).
    const dist = this.camera.position.distanceTo(this.controls.target);
    const speed = this.keyPanSpeed * (dist / 200) * delta;

    const move = new THREE.Vector3();
    if (this.keysDown.has('w') || this.keysDown.has('arrowup'))    move.add(forward.clone().multiplyScalar(speed));
    if (this.keysDown.has('s') || this.keysDown.has('arrowdown'))  move.add(forward.clone().multiplyScalar(-speed));
    if (this.keysDown.has('d') || this.keysDown.has('arrowright')) move.add(right.clone().multiplyScalar(speed));
    if (this.keysDown.has('a') || this.keysDown.has('arrowleft'))  move.add(right.clone().multiplyScalar(-speed));
    if (this.keysDown.has('e')) move.y += speed;  // ascend
    if (this.keysDown.has('q')) move.y -= speed;  // descend

    if (move.lengthSq() > 0) {
      this.camera.position.add(move);
      this.controls.target.add(move);
    }
  }

  add(object: THREE.Object3D): void {
    this.scene.add(object);
  }

  remove(object: THREE.Object3D): void {
    this.scene.remove(object);
  }

  registerSelectable(obj: SelectableObject): void {
    this.selectables.push(obj);
  }

  onEntityClick(callback: EntityClickCallback): void {
    this.onClickCallback = callback;
  }

  follow(position: THREE.Vector3): void {
    this.followTarget = position;
    this.isFollowing = true;
    this.controls.target.copy(position);
  }

  unfollow(): void {
    this.isFollowing = false;
    this.followTarget = null;
  }

  moveCameraTo(position: THREE.Vector3): void {
    this.controls.target.copy(position);
    this.camera.position.set(position.x + 80, position.y + 250, position.z + 120);  // Spec 024: y offset 60→250,确保相机在地面以上
    this.controls.update();
  }

  get isFollowingMode(): boolean {
    return this.isFollowing;
  }

  private onClick(event: MouseEvent): void {
    const rect = this.renderer.domElement.getBoundingClientRect();
    this.mouse.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
    this.mouse.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;

    this.raycaster.setFromCamera(this.mouse, this.camera);

    const targets = this.selectables.map(s => s.object);
    const intersects = this.raycaster.intersectObjects(targets, true);

    if (intersects.length > 0) {
      const hit = intersects[0];
      if (!hit) return;
      const hitObject = hit.object;
      const selectable = this.selectables.find(s =>
        s.object === hitObject || s.object.getObjectById(hitObject.id) !== null
      );
      if (selectable) {
        this.onClickCallback?.(selectable.entityType, selectable.entityId);
      }
    }
  }

  onUpdate(callback: (delta: number) => void): void {
    this.updateCallbacks.push(callback);
  }

  onPerformanceReport(callback: PerformanceCallback): void {
    this.perfCallback = callback;
  }

  start(): void {
    const animate = () => {
      this.animationId = requestAnimationFrame(animate);

      const delta = this.clock.getDelta();

      // Performance monitoring
      this.frameCount++;
      this.perfElapsed += delta;
      if (this.perfElapsed >= 1.0) {
        const fps = Math.round(this.frameCount / this.perfElapsed);
        const frameTime = Math.round((this.perfElapsed / this.frameCount) * 1000 * 10) / 10;
        this.perfCallback?.({ fps, frameTime });
        this.frameCount = 0;
        this.perfElapsed = 0;
      }

      // Call update callbacks
      for (const callback of this.updateCallbacks) {
        callback(delta);
      }

      // Camera follow mode
      if (this.isFollowing && this.followTarget) {
        this.controls.target.lerp(this.followTarget, 0.05);
      }

      // Keyboard pan (WASD / arrows / Q-E). Applied after follow so that
      // pressing a movement key cancels follow and takes over.
      this.applyKeyboardPan(delta);

      // Update controls
      this.controls.update();

      // Render scene
      this.renderer.render(this.scene, this.camera);
    };

    animate();
  }

  stop(): void {
    if (this.animationId !== null) {
      cancelAnimationFrame(this.animationId);
      this.animationId = null;
    }
  }

  private clock = new THREE.Clock();

  private onWindowResize(container: HTMLElement): void {
    this.camera.aspect = container.clientWidth / container.clientHeight;
    this.camera.updateProjectionMatrix();
    this.renderer.setSize(container.clientWidth, container.clientHeight);
  }

  getScene(): THREE.Scene {
    return this.scene;
  }

  getCamera(): THREE.PerspectiveCamera {
    return this.camera;
  }

  getRenderer(): THREE.WebGLRenderer {
    return this.renderer;
  }
}