//
// Spec 020 T7: parameterised zone overlay. KillZoneOverlay (red air-defense)
// and JamZoneOverlay (purple comm-jam) are thin typed wrappers differing only
// in colour/alpha. ZoneOverlay folds both into one class driven by a config.
//
// 023: regions render as volumetric 3D grid prisms — a faint bottom fill mesh,
// a dense triangular wireframe wrapping the sides (every altitude slice + each
// vertical quad triangulated, echoing the terrain's fine triangle mesh), and a
// floating Chinese text label above the volume. The bottom fill Mesh is kept so
// the Spec 019 US6 contract tests (one Mesh per polygon) keep passing.
import * as THREE from 'three';

import { wgs84ToEnu } from '../core/wgs84-projection';

export interface ZonePolygon {
  /** [(lat, lon), ...] — at least 3 vertices for a filled mesh. */
  polygon: Array<[number, number]>;
  alt_min: number;
  alt_max: number;
}

export interface ZoneOverlayConfig {
  /** Edge / fill colour (hex). */
  color: number;
  /** Fill opacity 0..1 (the bottom face uses alpha*0.5). */
  alpha: number;
  /** Kept for config compat; the prism wireframe always draws edges. */
  showBoundary?: boolean;
  /** Group name (debug visibility in the scene graph). */
  name?: string;
  /** Default ceiling (metres) when a zone omits alt_max. */
  defaultAltMax?: number;
  /** Floating Chinese label shown above the volume (023). */
  label?: string;
}

export class ZoneOverlay {
  private group: THREE.Group;
  private children: THREE.Object3D[] = [];
  private readonly config: ZoneOverlayConfig;

  constructor(parent: THREE.Scene, config: ZoneOverlayConfig) {
    this.config = config;
    this.group = new THREE.Group();
    this.group.name = config.name ?? 'ZoneOverlay';
    parent.add(this.group);
  }

  /**
   * Rebuild the region visuals. Each valid (>= 3 vertices) polygon becomes:
   *  (1) a faint bottom fill Mesh (fan triangulation at alt_min) — kept for
   *      the contract tests;
   *  (2) a dense triangular side wireframe: the altitude range is sliced into
   *      many levels and every side quad is triangulated, then WireframeGeometry
   *      exposes all edges (horizontal rings + verticals + diagonals) for a
   *      fine triangle-mesh look like the terrain;
   *  (3) a floating text label sprite above the volume centre.
   */
  update(zones: ZonePolygon[], referenceLat: number, referenceLon: number): void {
    for (const o of this.children) {
      this.group.remove(o);
      this.disposeObject(o);
    }
    this.children = [];

    const color = this.config.color;
    const fillMat = new THREE.MeshBasicMaterial({
      color,
      transparent: true,
      opacity: this.config.alpha * 0.5,
      side: THREE.DoubleSide,
      depthWrite: false,
    });
    const wireMat = new THREE.LineBasicMaterial({
      color, transparent: true, opacity: 0.32, depthWrite: false,
    });
    const defaultAltMax = this.config.defaultAltMax ?? 2500;

    for (const z of zones) {
      if (!z.polygon || z.polygon.length < 3) continue;
      const n = z.polygon.length;
      const yMin = z.alt_min ?? 0;
      const yMax = z.alt_max ?? defaultAltMax;
      const poly = z.polygon;

      // Project every polygon vertex at a given altitude → [x, y, z].
      const proj = (lat: number, lon: number, y: number): [number, number, number] => {
        const [e, north] = wgs84ToEnu(lat, lon, referenceLat, referenceLon);
        return [e, y, -north];
      };

      // (1) Bottom fill mesh (fan) — preserved for the contract tests.
      const bot: number[] = [];
      for (const [lat, lon] of poly) {
        const p = proj(lat, lon, yMin);
        bot.push(p[0], p[1], p[2]);
      }
      const fillIdx: number[] = [];
      for (let i = 1; i < n - 1; i++) fillIdx.push(0, i, i + 1);
      const fillGeom = new THREE.BufferGeometry();
      fillGeom.setAttribute('position', new THREE.Float32BufferAttribute(bot, 3));
      fillGeom.setIndex(fillIdx);
      fillGeom.computeVertexNormals();
      const mesh = new THREE.Mesh(fillGeom, fillMat);
      this.group.add(mesh);
      this.children.push(mesh);

      // (2) Dense triangular side wireframe.
      // Slice the altitude range every ~250 m (clamped 4..12 intervals) and
      // triangulate each side quad between adjacent levels → fine triangle mesh.
      const steps = Math.max(4, Math.min(12, Math.round((yMax - yMin) / 250)));
      const levels = steps + 1;
      const sidePos: number[] = [];
      for (let li = 0; li < levels; li++) {
        const y = yMin + (yMax - yMin) * (li / steps);
        for (let vi = 0; vi < n; vi++) {
          const [lat, lon] = poly[vi]!;
          const p = proj(lat, lon, y);
          sidePos.push(p[0], p[1], p[2]);
        }
      }
      const sideIdx: number[] = [];
      for (let li = 0; li < steps; li++) {
        for (let vi = 0; vi < n; vi++) {
          const a = li * n + vi;
          const b = li * n + (vi + 1) % n;
          const c = (li + 1) * n + vi;
          const d = (li + 1) * n + (vi + 1) % n;
          sideIdx.push(a, c, b, b, c, d); // 两个三角形 / 侧面格
        }
      }
      const sideGeom = new THREE.BufferGeometry();
      sideGeom.setAttribute('position', new THREE.Float32BufferAttribute(sidePos, 3));
      sideGeom.setIndex(sideIdx);
      const wireGeom = new THREE.WireframeGeometry(sideGeom);
      sideGeom.dispose();
      const wire = new THREE.LineSegments(wireGeom, wireMat);
      this.group.add(wire);
      this.children.push(wire);

      // (3) Floating Chinese label above the volume centre.
      if (this.config.label) {
        const sprite = makeZoneLabel(this.config.label, color);
        if (sprite) {
          let cE = 0, cN = 0;
          for (const [lat, lon] of poly) {
            const [e, north] = wgs84ToEnu(lat, lon, referenceLat, referenceLon);
            cE += e; cN += north;
          }
          cE /= n; cN /= n;
          sprite.position.set(cE, yMax + 80, -cN);
          this.group.add(sprite);
          this.children.push(sprite);
        }
      }
    }
  }

  dispose(): void {
    for (const o of this.children) {
      this.group.remove(o);
      this.disposeObject(o);
    }
    this.children = [];
    this.group.parent?.remove(this.group);
  }

  private disposeObject(o: THREE.Object3D): void {
    const m = o as THREE.Mesh;
    if (m.geometry) m.geometry.dispose();
    const sprite = o as THREE.Sprite;
    if (sprite.material) {
      const mat = sprite.material as THREE.SpriteMaterial;
      mat.map?.dispose();
      mat.dispose();
    }
  }
}

/**
 * Build a canvas-texture sprite showing the zone label text in the zone colour,
 * with a translucent dark rounded background + coloured outline. Returns null
 * in non-DOM environments (e.g. vitest node) so update() stays test-safe.
 */
function makeZoneLabel(text: string, color: number): THREE.Sprite | null {
  if (typeof document === 'undefined') return null;
  const canvas = document.createElement('canvas');
  canvas.width = 256;
  canvas.height = 64;
  const ctx = canvas.getContext('2d');
  if (!ctx) return null;
  const css = '#' + color.toString(16).padStart(6, '0');

  // 圆角深色底 + 彩色描边
  const r = 12;
  ctx.fillStyle = 'rgba(7, 10, 18, 0.82)';
  ctx.strokeStyle = css;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(r, 2);
  ctx.arcTo(canvas.width - 2, 2, canvas.width - 2, canvas.height - 2, r);
  ctx.arcTo(canvas.width - 2, canvas.height - 2, 2, canvas.height - 2, r);
  ctx.arcTo(2, canvas.height - 2, 2, 2, r);
  ctx.arcTo(2, 2, canvas.width - 2, 2, r);
  ctx.closePath();
  ctx.fill();
  ctx.stroke();

  // 中文标签
  ctx.fillStyle = css;
  ctx.font = 'bold 30px "Microsoft YaHei UI", "Microsoft YaHei", "PingFang SC", sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(text, canvas.width / 2, canvas.height / 2 + 1);

  const texture = new THREE.CanvasTexture(canvas);
  texture.minFilter = THREE.LinearFilter;
  const material = new THREE.SpriteMaterial({ map: texture, transparent: true, depthTest: false });
  const sprite = new THREE.Sprite(material);
  sprite.scale.set(160, 40, 1);
  return sprite;
}
