//
// Spec 017 (FR-018, SHOULD): communication link visualization.
//
// Draws a transient cyan line between two UAVs whenever a comm message
// is observed in one peer's inbox. Lines fade out over ~0.5s (30 frames
// at 60Hz) so the user perceives message flow without screen clutter.
//
// This renderer is fed by the multi-entity state: for each UAV with a
// non-empty comm.inbox, we look up the sender's position and draw a
// line sender -> receiver. Each line is tracked by a composite key
// (sender:receiver:recv_time) and removed once its age exceeds the
// fade window.

import * as THREE from 'three';
import { WGS84Projection, EntityState } from '../core/wgs84-projection';

const LINK_COLOR = 0x00bcd4;     // cyan
const LINK_LIFETIME_FRAMES = 30; // ~0.5s at 60Hz
const MAX_LINKS = 64;            // cap to avoid runaway geometry

interface ActiveLink {
  line: THREE.Line;
  remainingFrames: number;
  key: string;
}

export class CommLinkRenderer {
  private group: THREE.Group;
  private projection: WGS84Projection;
  private active: Map<string, ActiveLink> = new Map();
  private material: THREE.LineBasicMaterial;

  constructor(projection: WGS84Projection) {
    this.projection = projection;
    this.group = new THREE.Group();
    this.material = new THREE.LineBasicMaterial({
      color: LINK_COLOR,
      transparent: true,
      opacity: 0.8,
    });
  }

  getModel(): THREE.Group {
    return this.group;
  }

  setVisible(visible: boolean): void {
    this.group.visible = visible;
  }

  /**
   * Drive the link visualization from the multi-entity state.
   * For each UAV with comm.inbox entries, spawn (or refresh) a link
   * from each distinct sender.
   */
  update(entities: Record<string, EntityState>): void {
    for (const [recvUid, entity] of Object.entries(entities)) {
      if (entity.kind !== 'uav' || !entity.comm || !entity.uav) continue;
      const recvPos = this.projection.toVector3(
        entity.uav.latitude, entity.uav.longitude, entity.uav.altitude);
      for (const entry of entity.comm.inbox) {
        if (!entry.sender || entry.sender === recvUid) continue;
        const sender = entities[entry.sender];
        if (!sender || !sender.uav) continue;
        const senderPos = this.projection.toVector3(
          sender.uav.latitude, sender.uav.longitude, sender.uav.altitude);
        const key = `${entry.sender}:${recvUid}`;
        this.spawnOrUpdate(key, senderPos, recvPos);
      }
    }
    this.tickFade();
  }

  private spawnOrUpdate(key: string, from: THREE.Vector3, to: THREE.Vector3): void {
    if (this.active.has(key)) {
      const link = this.active.get(key)!;
      link.remainingFrames = LINK_LIFETIME_FRAMES;
      this.updateLineGeometry(link.line, from, to);
      return;
    }
    if (this.active.size >= MAX_LINKS) return;
    const line = this.createLine(from, to);
    this.group.add(line);
    this.active.set(key, { line, remainingFrames: LINK_LIFETIME_FRAMES, key });
  }

  private createLine(from: THREE.Vector3, to: THREE.Vector3): THREE.Line {
    const geom = new THREE.BufferGeometry().setFromPoints([from, to]);
    return new THREE.Line(geom, this.material);
  }

  private updateLineGeometry(line: THREE.Line, from: THREE.Vector3, to: THREE.Vector3): void {
    const positions = (line.geometry.getAttribute('position') as THREE.BufferAttribute);
    positions.setXYZ(0, from.x, from.y, from.z);
    positions.setXYZ(1, to.x, to.y, to.z);
    positions.needsUpdate = true;
  }

  private tickFade(): void {
    for (const [key, link] of this.active) {
      link.remainingFrames -= 1;
      // Fade opacity linearly.
      const mat = link.line.material as THREE.LineBasicMaterial;
      mat.opacity = Math.max(0, 0.8 * (link.remainingFrames / LINK_LIFETIME_FRAMES));
      if (link.remainingFrames <= 0) {
        this.group.remove(link.line);
        link.line.geometry.dispose();
        this.active.delete(key);
      }
    }
  }

  /** Spec 024: 立即清空所有通信线(关闭仿真重置)。
   *  update({}) 仅触发 fade(30 帧),且 reset 后不再有 sim:state 驱动 tickFade,
   *  残留线不会自然消失 —— 故需显式立即清空。 */
  clear(): void {
    for (const [, link] of this.active) {
      this.group.remove(link.line);
      link.line.geometry.dispose();
    }
    this.active.clear();
  }

  dispose(): void {
    for (const [, link] of this.active) {
      this.group.remove(link.line);
      link.line.geometry.dispose();
    }
    this.active.clear();
    this.material.dispose();
  }
}
