/** 新手引导持久化封装 —— localStorage 读写 + 版本化 key。
 *
 *  key 带版本后缀(hongfeng2026:onboarding-v1): 后续改引导步骤时, 升 v2
 *  即可让所有用户重新看到引导。对外只暴露 isCompleted / markCompleted 两个
 *  方法; 隐私模式下 localStorage 不可用时静默降级(返回 false / 不抛错)。 */
const STORAGE_KEY = 'hongfeng2026:onboarding-v1';

export const OnboardingStorage = {
  /** 是否已完成引导(读过或跳过)。localStorage 不可用时返回 false。 */
  isCompleted(): boolean {
    try {
      return localStorage.getItem(STORAGE_KEY) === '1';
    } catch {
      return false;
    }
  },

  /** 标记引导已完成。localStorage 不可用时静默失败。 */
  markCompleted(): void {
    try {
      localStorage.setItem(STORAGE_KEY, '1');
    } catch {
      /* 隐私模式 / 存储满: 忽略, 下次还会再弹(可接受)。 */
    }
  },
};
