//
// Real target vehicle renderer. The shared geometry + lifecycle lives in
// VehicleModelBase (Spec 020 T7); this subclass only pins the palette +
// label to the red "TARGET" identity. Rendered output is byte-equivalent
// to the pre-refactor VehicleModelRenderer.
import { WGS84Projection } from '../core/wgs84-projection';
import { VehicleModelBase, TARGET_VEHICLE_CONFIG } from './vehicle-model-base';

export class VehicleModelRenderer extends VehicleModelBase {
  constructor(projection: WGS84Projection) {
    super(projection, TARGET_VEHICLE_CONFIG);
  }
}
