//
// Spec 020 T7: KillZoneOverlay is now a thin typed wrapper around the
// parameterised ZoneOverlay (red air-defense, fill + boundary line).
// The implementation moved to zone-overlay.ts; this file keeps the
// historical class name + AirDefenseZone type so existing imports and
// the Spec 019 US6 contract tests keep working unchanged.
import type * as THREE from 'three';
import { ZoneOverlay, ZonePolygon } from './zone-overlay';
import { ZONE_COLORS, ZONE_ALPHA } from './constants';

// Polygon shape published at sim:state.zones.air_defense.
export type AirDefenseZone = ZonePolygon;

export class KillZoneOverlay extends ZoneOverlay {
  constructor(parent: THREE.Scene) {
    super(parent, {
      color: ZONE_COLORS.killZone,
      alpha: ZONE_ALPHA.killZone,
      showBoundary: true,
      name: 'KillZoneOverlay',
      defaultAltMax: 3000,
      label: '防空杀伤区',
    });
  }
}
