import { SimulationState, EntityState, ExtendedDetection } from '../core/wgs84-projection';

export type SelectedEntity = 'uav' | 'target' | 'gimbal' | null;

/** Section keys that start collapsed. Basic telemetry stays expanded. */
const DEFAULT_COLLAPSED: ReadonlySet<string> = new Set(['gimbal', 'detection']);

/** Determine if a detection block should be shown for this entity kind. */
export function shouldShowDetection(kind: string): boolean {
  return kind === 'uav';
}

/** Format detection data into HTML table rows. Exported for testing. */
export function formatDetectionHtml(det: ExtendedDetection): string {
  if (!det.detected) {
    return `<tr><td colspan="2" style="color:#888;font-style:italic;">未发现</td></tr>`;
  }

  let html = '';
  html += `<tr><td>是否发现</td><td style="color:#4caf50;">是</td></tr>`;
  html += `<tr><td>置信度</td><td>${(det.confidence * 100).toFixed(0)}%</td></tr>`;
  // 目标位置坐标已隐藏：detection.target_position 是仿真真值（引擎直接读目标
  // 实体真实坐标），对选手可见的界面不可展示——否则绕过 obs 的隔离/加噪机制。
  if (det.azimuth_error !== undefined && det.azimuth_error !== null) {
    html += `<tr><td>方位误差</td><td>${det.azimuth_error.toFixed(1)}°</td></tr>`;
  }
  if (det.target_type) {
    html += `<tr><td>目标类型</td><td>${det.target_type}</td></tr>`;
  }
  return html;
}

/** Field label + formatted value pair (used by both build + incremental update). */
type Field = [label: string, value: string];

function uavFields(u: { latitude: number; longitude: number; altitude: number; roll: number; pitch: number; yaw: number; velocity: number }): Field[] {
  return [
    ['纬度', `${u.latitude.toFixed(6)}°`],
    ['经度', `${u.longitude.toFixed(6)}°`],
    ['高度', `${u.altitude.toFixed(1)} m`],
    ['横滚', `${u.roll.toFixed(1)}°`],
    ['俯仰', `${u.pitch.toFixed(1)}°`],
    ['航向', `${u.yaw.toFixed(1)}°`],
    ['速度', `${u.velocity.toFixed(1)} m/s`],
  ];
}

function gimbalFields(g: { pan_angle: number; tilt_angle: number; track_enabled: boolean; fov: number }): Field[] {
  return [
    ['方位', `${g.pan_angle.toFixed(1)}°`],
    ['俯仰角', `${g.tilt_angle.toFixed(1)}°`],
    ['跟踪', g.track_enabled ? '启用' : '禁用'],
    // Competition rule caps the camera FOV at 50°; the "/50" suffix surfaces
    // the cap in the UI. Label stays "视场" so the data-field selector used by
    // live in-place updates (updateField) keeps matching.
    ['视场', `${g.fov.toFixed(1)}° /50°`],
  ];
}

function vehicleFields(v: { latitude: number; longitude: number; altitude: number; speed: number; heading: number }): Field[] {
  return [
    ['纬度', `${v.latitude.toFixed(6)}°`],
    ['经度', `${v.longitude.toFixed(6)}°`],
    ['高度', `${v.altitude.toFixed(1)} m`],
    ['速度', `${v.speed.toFixed(1)} m/s`],
    ['航向', `${v.heading.toFixed(1)}°`],
  ];
}

/** A table row whose value cell carries a stable data-field for live updates. */
function fieldRows(fields: Field[]): string {
  return fields.map(([label, value]) =>
    `<tr><td>${label}</td><td data-field="${label}">${value}</td></tr>`).join('');
}

/** Wrap a section title + inner HTML in a collapsible .info-section block. */
function section(key: string, title: string, innerHtml: string): string {
  return (
    `<div class="info-section" data-section="${key}">` +
    `<button type="button" class="info-section__head" aria-expanded="true">` +
    `<span class="info-section__chevron" aria-hidden="true">▾</span>${title}` +
    `</button>` +
    `<div class="info-section__body" data-body>${innerHtml}</div>` +
    `</div>`
  );
}

export class EntityInfoPanel {
  private container: HTMLElement;
  /** Per-section collapse memory — survives #info-content innerHTML rebuilds. */
  private collapsedSections = new Set<string>(DEFAULT_COLLAPSED);
  /** Signature of the currently-rendered structure (uid + section set).
   *  When it is unchanged we update values in place instead of rebuilding the
   *  DOM — otherwise the per-frame rebuild tears down section headers mid-click
   *  and the toggle never fires (Spec 023). */
  private renderedSignature: string | null = null;

  constructor(containerId: string) {
    const container = document.getElementById(containerId);
    if (!container) throw new Error(`Container #${containerId} not found`);
    this.container = container;
    this.render();
    this.bindSectionToggle();
  }

  private render(): void {
    // Panel structure (header h3 with #info-entity-name/#info-entity-uid +
    // #info-content body) is provided by index.html. Nothing to build here —
    // retained so the constructor contract stays stable.
  }

  /**
   * Delegate the collapse toggle on the persistent container (not #info-content,
   * which is rebuilt on structural change) so the user's collapse state survives.
   */
  private bindSectionToggle(): void {
    this.container.addEventListener('click', (e) => {
      const head = (e.target as HTMLElement).closest('.info-section__head') as HTMLElement | null;
      if (!head) return;
      const sec = head.closest('.info-section') as HTMLElement | null;
      const key = sec?.dataset.section;
      if (!key || !sec) return;
      if (this.collapsedSections.has(key)) this.collapsedSections.delete(key);
      else this.collapsedSections.add(key);
      this.applySectionState(sec, key);
    });
  }

  /** Apply the remembered collapse state to one section element. */
  private applySectionState(sec: HTMLElement, key: string): void {
    const collapsed = this.collapsedSections.has(key);
    sec.classList.toggle('is-collapsed', collapsed);
    const head = sec.querySelector('.info-section__head');
    head?.setAttribute('aria-expanded', String(!collapsed));
  }

  /** Apply remembered collapse states to all sections after a content rebuild. */
  private applyAllSectionStates(): void {
    this.container.querySelectorAll<HTMLElement>('.info-section').forEach((sec) => {
      const key = sec.dataset.section;
      if (key) this.applySectionState(sec, key);
    });
  }

  /** Structural signature: uid + which sections are present. Numerical values
   *  are intentionally excluded so live telemetry never triggers a rebuild. */
  private signature(entity: EntityState, uid: string): string {
    const parts = [uid];
    if (entity.uav) {
      parts.push('uav');
      if (entity.gimbal) parts.push('gimbal');
      if (entity.detection) parts.push('detection');
    } else if (entity.vehicle) {
      parts.push('vehicle');
    }
    return parts.join(':');
  }

  /** Full rebuild HTML (only when structure changes). */
  private buildBodyHtml(entity: EntityState): string {
    let html = '';
    if (entity.uav) {
      html += section('basic', '遥测',
        `<table class="info-table">${fieldRows(uavFields(entity.uav))}</table>`);
      if (entity.gimbal) {
        html += section('gimbal', '云台',
          `<table class="info-table">${fieldRows(gimbalFields(entity.gimbal))}</table>`);
      }
      if (entity.detection) {
        html += section('detection', '探测',
          `<table class="info-table">${formatDetectionHtml(entity.detection)}</table>`);
      }
    } else if (entity.vehicle) {
      html += section('basic', '遥测',
        `<table class="info-table">${fieldRows(vehicleFields(entity.vehicle))}</table>`);
    }
    return html;
  }

  /** In-place value update — keeps section header/body nodes alive so an
   *  in-flight click is not orphaned by a DOM rebuild. */
  private updateValues(entity: EntityState): void {
    const set = (field: string, value: string) => {
      const el = this.container.querySelector(`td[data-field="${field}"]`);
      if (el) el.textContent = value;
    };
    if (entity.uav) {
      for (const [f, v] of uavFields(entity.uav)) set(f, v);
      if (entity.gimbal) {
        for (const [f, v] of gimbalFields(entity.gimbal)) set(f, v);
      }
    } else if (entity.vehicle) {
      for (const [f, v] of vehicleFields(entity.vehicle)) set(f, v);
    }
    // Detection has no stable per-field ids (formatDetectionHtml is a tested
    // pure function); refresh its body only — the section header stays put so
    // toggling detection is never interrupted either.
    if (entity.detection) {
      const body = this.container.querySelector('.info-section[data-section="detection"] [data-body]');
      if (body) body.innerHTML = `<table class="info-table">${formatDetectionHtml(entity.detection)}</table>`;
    }
  }

  /**
   * Spec 020 T6: selection is uid-driven (this.selectedEntity in App holds
   * the uid). This entry point is retained for the click-routing contract
   * but no longer stores a separate legacy slot.
   */
  select(_entity: SelectedEntity): void {
    // no-op: selection state lives in App.selectedUid
  }

  /** Set the selected uid directly (from Entity Control or entity list). */
  selectByUid(_uid: string | null): void {
    // no-op: selection state lives in App.selectedUid
  }

  update(state: SimulationState, selectedUid?: string | null): void {
    const uid = selectedUid ?? null;
    const nameEl = document.getElementById('info-entity-name');
    const contentEl = document.getElementById('info-content');
    const uidEl = document.getElementById('info-entity-uid');
    if (!nameEl || !contentEl) return;

    // Spec 018 (T032): the multi-entity map is the sole data source.
    let entity: EntityState | undefined;
    if (uid && state.entities) {
      entity = state.entities[uid];
    }

    if (entity && uid) {
      if (uidEl) uidEl.textContent = entity.uid ? `[${entity.uid}]` : '';
      nameEl.textContent = `(${entity.kind})`;

      const sig = this.signature(entity, uid);
      if (sig !== this.renderedSignature) {
        // Structural change (entity switch / section added or removed): rebuild.
        contentEl.innerHTML = this.buildBodyHtml(entity);
        this.applyAllSectionStates();
        this.renderedSignature = sig;
      } else {
        // Same structure: update values in place — headers stay clickable.
        this.updateValues(entity);
      }
      return;
    }

    // No selected entity: clear the panel.
    if (uidEl) uidEl.textContent = '';
    nameEl.textContent = '';
    contentEl.innerHTML = '<p class="info-hint">点击 3D 场景中的实体查看其数据</p>';
    this.renderedSignature = null;
  }

  clear(): void {
    const nameEl = document.getElementById('info-entity-name');
    const contentEl = document.getElementById('info-content');
    const uidEl = document.getElementById('info-entity-uid');
    if (nameEl) nameEl.textContent = '';
    if (uidEl) uidEl.textContent = '';
    if (contentEl) contentEl.innerHTML = '<p class="info-hint">点击实体查看其数据</p>';
    this.renderedSignature = null;
  }
}
