import * as THREE from 'three';
import { WGS84Projection } from '../core/wgs84-projection';
import { TRAIL_COLORS } from './constants';

/**
 * Trajectory trail renderer with a pre-allocated ring buffer.
 *
 * Each trail owns ONE THREE.BufferGeometry whose position attribute is a
 * fixed Float32Array. New points are appended and the draw range is
 * bumped; the buffer is reused for the trail's lifetime. This replaces
 * the previous per-update ``geometry.dispose() +
 * new BufferGeometry().setFromPoints()`` pattern which (across 10 UAV +
 * 30 vehicle trails) was a major frame-time contributor.
 *
 * One TrajectoryTrail = one coloured polyline for ONE entity. The kind
 * (uav / target / decoy) sets the default colour.
 */
export type TrailKind = 'uav' | 'target' | 'decoy';

export interface TrailConfig {
  maxPoints: number;
  color: number;
  lineWidth: number;
}

const DEFAULT_COLORS: Record<TrailKind, number> = {
  uav: TRAIL_COLORS.uav,     // blue
  target: TRAIL_COLORS.target,  // red
  decoy: TRAIL_COLORS.decoy,   // orange
};

export class TrajectoryTrail {
  private line: THREE.Line;
  private points: THREE.Vector3[] = [];
  private projection: WGS84Projection;
  private config: TrailConfig;
  private lastUpdate: number = 0;
  private readonly kind: TrailKind;
  private positions: Float32Array;
  private positionAttr: THREE.BufferAttribute;

  constructor(projection: WGS84Projection,
              kind: TrailKind = 'uav',
              config?: Partial<TrailConfig>) {
    this.projection = projection;
    this.kind = kind;
    this.config = {
      maxPoints: 1000,
      color: DEFAULT_COLORS[kind],
      lineWidth: 2,
      ...config,
    };

    this.positions = new Float32Array(this.config.maxPoints * 3);
    this.positionAttr = new THREE.BufferAttribute(this.positions, 3);
    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute('position', this.positionAttr);
    geometry.setDrawRange(0, 0);
    const material = new THREE.LineBasicMaterial({
      color: this.config.color,
      linewidth: this.config.lineWidth,
    });
    this.line = new THREE.Line(geometry, material);
  }

  /**
   * Append a (lat, lon, alt) sample to the trail. Throttled to one point
   * per ``updateIntervalMs``; near-duplicate points are dropped.
   */
  updatePosition(latitude: number, longitude: number,
                 altitude: number, updateIntervalMs = 100): void {
    const now = Date.now();
    if (now - this.lastUpdate < updateIntervalMs) return;
    this.lastUpdate = now;

    const p = this.projection.toVector3(latitude, longitude, altitude);
    const last = this.points[this.points.length - 1];
    if (last && last.distanceToSquared(p) < 1e-4) return;

    this.points.push(p);
    if (this.points.length > this.config.maxPoints) {
      this.points.shift();
    }

    const n = this.points.length;
    for (let i = 0; i < n; i++) {
      const v = this.points[i]!;
      this.positions[i * 3] = v.x;
      this.positions[i * 3 + 1] = v.y;
      this.positions[i * 3 + 2] = v.z;
    }
    this.line.geometry.setDrawRange(0, n);
    this.positionAttr.needsUpdate = true;
    this.line.geometry.computeBoundingSphere();
  }

  clear(): void {
    this.points = [];
    this.line.geometry.setDrawRange(0, 0);
    this.positionAttr.needsUpdate = true;
  }

  setVisible(visible: boolean): void {
    this.line.visible = visible;
  }

  /** The single polyline object to add to the scene. */
  getLine(): THREE.Line {
    return this.line;
  }

  getKind(): TrailKind {
    return this.kind;
  }

  getPointCount(): number {
    return this.points.length;
  }
}
