import { SimEvent, Team } from './wgs84-projection';

export type EventSubscriber = (events: SimEvent[]) => void;

const DEFAULT_CAPACITY = 500;
const DEDUP_INTERVAL_MS = 200;

/** Normalize a team value per the contract rules:
 *  - undefined/null → 'white'
 *  - unknown string  → 'white' (with console.warn)
 */
export function normalizeTeam(raw?: Team | null): Team {
  if (!raw) return 'white';
  if (raw === 'red' || raw === 'blue' || raw === 'white') return raw;
  console.warn(`Unknown team value: ${raw}, falling back to white`);
  return 'white';
}

/**
 * EventManager — maintains a ring buffer of SimEvent messages, deduplicates
 * rapid identical events, and distributes them to subscribers.
 *
 * Mirrors the observer pattern used by StateManager.
 */
export class EventManager {
  private buffer: SimEvent[] = [];
  private capacity: number;
  private dedupInterval: number;
  private dedupKeys: Map<string, number> = new Map(); // key → last push timestamp
  private subscribers: EventSubscriber[] = [];

  constructor(options?: { capacity?: number; dedupIntervalMs?: number }) {
    this.capacity = options?.capacity ?? DEFAULT_CAPACITY;
    this.dedupInterval = options?.dedupIntervalMs ?? DEDUP_INTERVAL_MS;
  }

  /** Push a new event. Duplicate events within the dedup window are silently
   *  dropped. Unknown event_type values are accepted (forward-compatible). */
  push(event: SimEvent): void {
    // Normalize team on ingestion.
    if (!event.source.team) {
      event.source.team = 'white';
    } else {
      event.source.team = normalizeTeam(event.source.team);
    }

    // Dedup: same entity_uid + event_type within dedupInterval
    const dedupKey = `${event.entity_uid}:${event.event_type}`;
    const now = Date.now();
    const lastTime = this.dedupKeys.get(dedupKey);
    if (lastTime !== undefined && (now - lastTime) < this.dedupInterval) {
      return; // dedup
    }
    this.dedupKeys.set(dedupKey, now);

    // Add to buffer, trim if over capacity
    this.buffer.push(event);
    while (this.buffer.length > this.capacity) {
      this.buffer.shift();
    }

    this.notifySubscribers();
  }

  /** Current event buffer (newest last). */
  getAll(): SimEvent[] {
    return this.buffer;
  }

  /** Spec 024: 清空事件缓冲(关闭仿真/新会话时调用,重置事件墙)。
   *  通知订阅者 → EventWall 重新渲染为空。 */
  clear(): void {
    this.buffer = [];
    this.dedupKeys.clear();
    this.notifySubscribers();
  }

  /** Subscribe to event updates. Returns unsubscribe function. */
  subscribe(callback: EventSubscriber): () => void {
    this.subscribers.push(callback);
    return () => {
      const idx = this.subscribers.indexOf(callback);
      if (idx > -1) this.subscribers.splice(idx, 1);
    };
  }

  private notifySubscribers(): void {
    const snapshot = this.buffer.slice();
    for (const cb of this.subscribers) {
      try {
        cb(snapshot);
      } catch (err) {
        console.error('Error in EventManager subscriber:', err);
      }
    }
  }
}
