import { StateManager } from './state-manager';
import {
  SimEvent, EventSource, Team,
} from './wgs84-projection';
// Spec 020 T7: normalizeSimState now lives in state-normalizer.ts.
// Re-exported here so the Spec 017/019 contract tests that import it
// from redis-client keep working.
export { normalizeSimState } from './state-normalizer';
import { normalizeSimState } from './state-normalizer';
// Spec 020 T8: schema-driven validation for inbound sim:state frames.
import { validateSimState } from './schema-validator';
// Spec 020 T7: shared channel-name constants.
import { CHANNELS } from '../rendering/constants';

export interface RedisMessage {
  type: 'subscribe' | 'unsubscribe' | 'publish' | 'message' | 'error' | 'session';
  channel?: string;
  channels?: string[];
  message?: string;
  error?: string;
  // Spec 024: bridge broadcastToAll 推送的会话状态(不经 Redis channel)。
  status?: string;
  scenario?: string | null;
  sessionId?: string | null;
}

/** Spec 024: sim:progress 加载进度载荷。 */
export interface LoadProgress {
  phase: string;
  pct: number;
  detail?: string;
}

/**
 * Engine-side load-progress phase names emitted by the C++ SimulationEngine
 * (see src/engine/simulation_engine.cc: kPhaseNames = terrain_bbox/grid/nanfill,
 * plus the trailing `entities` and `ready` frames published at the end of
 * SimulationEngine::initialize). The Python controller later emits its OWN
 * progress on the same channel with a different phase (e.g. `规划车辆路线`) for
 * route planning.
 *
 * The engine reaches pct 1.0 on its `ready` frame — long before the controller
 * finishes planning routes. To keep the frontend progress bar from freezing at
 * 100% during route planning, the engine's pct is scaled ×ENGINE_PROGRESS_SCALE
 * (compressing it to 0–85%) so the controller's route-planning progress (sent
 * as 0.85→0.98) and the final `ready` frame (sent as 1.0) have room on the bar.
 */
const ENGINE_PROGRESS_PHASES = new Set<string>([
  'terrain_bbox',
  'terrain_grid',
  'terrain_nanfill',
  // Fallback phase name emitted by SimulationEngine when CsvLoader passes an
  // out-of-range phase index (simulation_engine.cc: `(phase >= 0 && phase <= 2)
  // ? kPhaseNames[phase] : "terrain"`). Unreachable today but must be scaled
  // so a future out-of-range frame cannot pin the bar above 50%.
  'terrain',
  'entities',
  'ready',
]);

/** Engine load-progress pct is multiplied by this so the controller's
 *  route-planning phase (85–98%) and final ready frame (100%) have room on the
 *  frontend progress bar. */
const ENGINE_PROGRESS_SCALE = 0.85;

/** Spec 024: 会话状态推送载荷。 */
export interface SessionUpdate {
  status: string;
  scenario?: string | null;
  sessionId?: string | null;
  error?: string | null;
}

/** Spec 025: sim:score 实时评分载荷(由 Python CoopTrackingEvaluator.score() 发布)。
 *  字段集兼容三个评分示例的差异化维度(profile_adversarial_swarm_search
 *  含 alive_rate,profile_multi_uav_coop_decoy 含 comm_* 等),统一为可选字段。 */
export interface ScoreSnapshot {
  /** 帧类型: 每 tick 为 "score",仿真结束末帧为 "score_final"。 */
  type: 'score' | 'score_final';
  /** 评分 profile 名(例 "uav_search_track_car" / "multi_uav_coop_decoy"
   *  / "adversarial_swarm_search")。前端可用于面板配色或调试。 */
  profile?: string;
  /** 仿真时间 (s)。 */
  sim_time?: number;
  /** 第几个 tick。 */
  tick?: number;
  /** 累计总分 (0-100)。 */
  total_score?: number;
  /** 是否通过(profile 阈值)。 */
  passed?: boolean;
  /** 维度明细子字典(键随 profile 变化)。 */
  dimension_scores?: Record<string, number>;
  /** 真实目标数。 */
  n_targets?: number;
  /** 已完成目标数。 */
  n_completed?: number;
  /** 存活率(对抗例专用)。 */
  alive_rate?: number;
  /** 是否为最终帧。 */
  final?: boolean;
  /** wall-clock unix 时间戳(s,小数)。 */
  ts?: number;
  /** 持久化 evaluation.json 路径(仅 final 帧携带)。 */
  evaluation_path?: string;
}

export interface RedisClientConfig {
  host: string;
  port: number;
  stateChannel: string;
  commandsChannel: string;
  entityCommandsChannel: string;
  eventsChannel?: string;
  // Entity ID mapping: entity name -> unique_id from config.json
  entityIds?: Record<string, string>;
}


export class RedisClient {
  private ws: WebSocket | null = null;
  private config: RedisClientConfig;
  private stateManager: StateManager;
  private reconnectAttempts = 0;
  private maxReconnectAttempts = 5;
  private reconnectDelay = 1000;
  private isConnected = false;
  private onConnectionChange?: (connected: boolean) => void;
  private onSimEvent?: (event: SimEvent) => void;
  // Spec 024: 加载进度 + 会话状态回调。
  private onProgressCb?: (p: LoadProgress) => void;
  private onSessionCb?: (s: SessionUpdate) => void;
  // Spec 025: sim:score 实时评分回调。
  private onScoreCb?: (snapshot: ScoreSnapshot) => void;

  constructor(config: RedisClientConfig, stateManager: StateManager) {
    this.config = config;
    this.stateManager = stateManager;
  }

  /** Register callback for sim:events messages. */
  onEvent(callback: (event: SimEvent) => void): void {
    this.onSimEvent = callback;
  }

  /** Spec 024 (T018): Register callback for sim:progress load-progress messages. */
  onProgress(callback: (p: LoadProgress) => void): void {
    this.onProgressCb = callback;
  }

  /** Spec 024 (T048): Register callback for session-status pushes (type:'session'). */
  onSession(callback: (s: SessionUpdate) => void): void {
    this.onSessionCb = callback;
  }

  /** Spec 025: Register callback for sim:score live score snapshots. */
  onScore(callback: (snapshot: ScoreSnapshot) => void): void {
    this.onScoreCb = callback;
  }

  connect(): Promise<void> {
    return new Promise((resolve, reject) => {
      const wsUrl = `ws://${this.config.host}:${this.config.port}`;
      this.ws = new WebSocket(wsUrl);

      this.ws.addEventListener('open', () => {
        console.log('Connected to Redis WebSocket bridge');
        this.isConnected = true;
        this.reconnectAttempts = 0;
        this.onConnectionChange?.(true);

        // Subscribe to state channel
        this.subscribe(this.config.stateChannel);

        // Spec 018: subscribe to sim:events channel
        const eventsChannel = this.config.eventsChannel || CHANNELS.events;
        this.subscribe(eventsChannel);

        // Spec 024: subscribe to sim:progress (load progress)
        this.subscribe(CHANNELS.progress);

        // Spec 025: subscribe to sim:score (live score snapshots).
        this.subscribe(CHANNELS.score);

        resolve();
      });

      this.ws.addEventListener('message', (event: MessageEvent) => {
        try {
          const message: RedisMessage = JSON.parse(event.data as string);
          this.handleMessage(message);
        } catch (error) {
          console.error('Failed to parse Redis message:', error);
        }
      });

      this.ws.addEventListener('close', () => {
        console.log('Disconnected from Redis WebSocket bridge');
        this.isConnected = false;
        this.onConnectionChange?.(false);
        this.attemptReconnect();
      });

      this.ws.addEventListener('error', (error: Event) => {
        console.error('WebSocket error:', error);
        reject(error);
      });
    });
  }

  disconnect(): void {
    if (this.ws) {
      this.ws.close();
      this.ws = null;
    }
    this.isConnected = false;
  }

  publish(channel: string, message: object): void {
    if (!this.ws || !this.isConnected) {
      console.warn('Cannot publish: not connected');
      return;
    }

    const payload: RedisMessage = {
      type: 'publish',
      channel,
      message: JSON.stringify(message)
    };

    this.ws.send(JSON.stringify(payload));
  }

  subscribe(channel: string): void {
    if (!this.ws || !this.isConnected) {
      console.warn('Cannot subscribe: not connected');
      return;
    }

    const payload: RedisMessage = {
      type: 'subscribe',
      channels: [channel]
    };

    this.ws.send(JSON.stringify(payload));
  }

  onConnectionStateChanged(callback: (connected: boolean) => void): void {
    this.onConnectionChange = callback;
  }

  private handleMessage(message: RedisMessage): void {
    switch (message.type) {
      case 'message':
        this.handleChannelMessage(message.channel!, message.message!);
        break;
      // Spec 024 (T048): bridge broadcastAll 推送的会话状态(非 Redis channel)。
      case 'session':
        if (this.onSessionCb) {
          this.onSessionCb({
            status: String(message.status ?? 'idle'),
            scenario: message.scenario ?? null,
            sessionId: message.sessionId ?? null,
            error: (message as RedisMessage & { error?: string | null }).error ?? null,
          });
        }
        break;
      case 'error':
        console.error('Redis error:', message.error);
        break;
      default:
        break;
    }
  }

  private handleChannelMessage(channel: string, messageStr: string): void {
    try {
      const message = JSON.parse(messageStr);

      // Spec 024 (T018): sim:progress 加载进度(仿真器 → bridge 转发)。
      // Task 3: engine phases are scaled ×ENGINE_PROGRESS_SCALE (0–85%) so the
      // Python controller's route-planning phase (sent as 0.85–0.98) and final
      // ready frame (1.0) own the upper band on the frontend progress bar.
      // Unknown/empty phases (including the controller's `规划车辆路线` and
      // runner's `就绪`) are passed through unscaled.
      if (channel === CHANNELS.progress && this.onProgressCb) {
        if (message.type === 'load_progress') {
          const rawPct = Number(message.pct ?? 0);
          // Guard against non-numeric pct (e.g. "abc" → NaN): NaN propagates
          // through scaling into the consumer's Math.max(high-water mark),
          // permanently breaking the bar. Coerce to 0 — consistent with the
          // surrounding defensive coercion (String(... ?? '') etc.).
          const safePct = Number.isFinite(rawPct) ? rawPct : 0;
          const phase = String(message.phase ?? '');
          const scaledPct = ENGINE_PROGRESS_PHASES.has(phase)
            ? safePct * ENGINE_PROGRESS_SCALE
            : safePct;
          this.onProgressCb({
            phase,
            pct: scaledPct,
            detail: typeof message.detail === 'string' ? message.detail : undefined,
          });
        }
        return;
      }

      // Spec 025: sim:score 实时评分(Python CoopTrackingEvaluator.score() → bridge 转发)。
      if (channel === CHANNELS.score && this.onScoreCb) {
        this.onScoreCb(message as ScoreSnapshot);
        return;
      }

      if (channel === this.config.stateChannel) {
        // Spec 020 T8: schema-driven validation gate. The frame is
        // validated against config/schema/sim-state.schema.json BEFORE
        // the manual normalisation runs; a schema-rejected frame is
        // dropped with its errors so contract drift surfaces loudly.
        // normalizeSimState keeps its own guards as a backstop and
        // returns null for the residual edge cases the schema permits.
        const schemaResult = validateSimState(message);
        if (!schemaResult.valid) {
          console.warn(
            'sim:state rejected by schema:',
            schemaResult.errors.join('; '));
          return;
        }
        const normalised = normalizeSimState(message, this.config.entityIds);
        if (normalised) {
          this.stateManager.updateState(normalised);
        } else {
          console.warn('Invalid sim:state message format');
        }
        return;
      }

      // Spec 018: handle sim:events channel
      const eventsChannel = this.config.eventsChannel || CHANNELS.events;
      if (channel === eventsChannel && this.onSimEvent) {
        const parsed = this.parseSimEvent(message);
        if (parsed) {
          this.onSimEvent(parsed);
        }
      }
    } catch (error) {
      console.error('Failed to handle channel message:', error);
    }
  }

  /** Parse a raw JSON object into a SimEvent. Returns null if invalid. */
  private parseSimEvent(raw: Record<string, unknown>): SimEvent | null {
    if (typeof raw.event_type !== 'string') return null;
    if (typeof raw.entity_uid !== 'string') return null;
    if (typeof raw.sim_time !== 'number') return null;

    const sourceRaw = raw.source;
    if (!sourceRaw || typeof sourceRaw !== 'object') return null;
    const src = sourceRaw as Record<string, unknown>;

    const source: EventSource = {
      kind: (src.kind === 'kernel' || src.kind === 'external')
        ? src.kind as 'kernel' | 'external'
        : 'external',
      producer: String(src.producer ?? 'unknown'),
    };
    // team: optional, fallback to white per contract
    if (src.team !== undefined && src.team !== null) {
      if (src.team === 'red' || src.team === 'blue' || src.team === 'white') {
        source.team = src.team as Team;
      } else {
        console.warn(`Unknown source.team value: ${src.team}, falling back to white`);
        source.team = 'white';
      }
    }
    if (src.auth !== undefined && src.auth !== null) {
      source.auth = src.auth;
    }

    return {
      event_type: raw.event_type as SimEvent['event_type'],
      source,
      entity_uid: raw.entity_uid as string,
      sim_time: raw.sim_time as number,
      payload: (raw.payload ?? {}) as Record<string, unknown>,
      event_id: raw.event_id !== undefined ? String(raw.event_id) : undefined,
    };
  }

  private attemptReconnect(): void {
    if (this.reconnectAttempts >= this.maxReconnectAttempts) {
      console.error('Max reconnection attempts reached');
      return;
    }

    this.reconnectAttempts++;
    const delay = this.reconnectDelay * Math.pow(2, this.reconnectAttempts - 1);

    console.log(`Attempting to reconnect in ${delay}ms (attempt ${this.reconnectAttempts})`);

    setTimeout(() => {
      this.connect().catch(() => {
        // Reconnect will be attempted on close event
      });
    }, delay);
  }
}