import { EventManager } from '../core/event-manager';
import { SimEvent } from '../core/wgs84-projection';

// ── Event type style mapping (exported for unit testing) ──

export interface EventTypeStyleEntry {
  label: string;
  colorClass: string;
}

export const EventTypeStyle: Record<string, EventTypeStyleEntry> = {
  'state.enter_track': { label: '进入跟踪', colorClass: 'event-enter-track' },
  'state.exit_track':  { label: '退出跟踪',  colorClass: 'event-exit-track' },
  'target.discovered': { label: '发现目标', colorClass: 'event-discovered' },
};

/** Get a human-readable label for an event_type. */
export function eventLabel(eventType: string): string {
  if (EventTypeStyle[eventType]) return EventTypeStyle[eventType].label;
  if (eventType.startsWith('kernel.')) return `内核: ${eventType.slice(7)}`;
  return eventType;
}

/** Get the CSS color class for an event_type. */
export function eventColorClass(eventType: string): string {
  if (EventTypeStyle[eventType]) return EventTypeStyle[eventType].colorClass;
  if (eventType.startsWith('kernel.')) return 'source-kernel';
  return '';
}

// ── Team filter (exported for unit testing) ──

export type TeamFilterValue = 'white' | 'red' | 'blue' | 'all';

export class TeamFilter {
  private current: TeamFilterValue = 'white';

  static getDefaultFilter(): TeamFilterValue {
    return 'white';
  }

  setFilter(value: TeamFilterValue): void {
    this.current = value;
  }

  getFilter(): TeamFilterValue {
    return this.current;
  }

  /** Check if an event passes the current team filter. */
  passes(event: SimEvent): boolean {
    if (this.current === 'all') return true;
    const team = event.source.team ?? 'white';
    return team === this.current;
  }
}

// ── EventWall UI ──

export class EventWall {
  private listEl: HTMLElement;
  private emptyEl: HTMLElement;
  private filter: TeamFilter;
  private unsubscribe?: () => void;

  constructor(eventManager: EventManager) {
    const panel = document.getElementById('event-wall-panel');
    if (!panel) {
      throw new Error('Event wall container #event-wall-panel not found');
    }
    this.listEl = document.getElementById('event-wall-list')!;
    this.emptyEl = this.listEl.querySelector('.event-wall-empty') as HTMLElement;
    this.filter = new TeamFilter();

    this.setupFilterButtons();
    // 023: dragging is handled by the generic hud-panel header mechanism.
    this.unsubscribe = eventManager.subscribe((events) => this.render(events));
  }

  private setupFilterButtons(): void {
    const filterContainer = document.getElementById('event-wall-filter');
    if (!filterContainer) return;

    const buttons = filterContainer.querySelectorAll('.team-filter-btn');
    buttons.forEach((btn) => {
      btn.addEventListener('click', () => {
        const team = (btn as HTMLElement).dataset.team as TeamFilterValue;
        if (team) {
          this.filter.setFilter(team);
          // Update active state
          buttons.forEach((b) => b.classList.remove('active'));
          btn.classList.add('active');
          // Re-render with new filter
          // EventManager will re-trigger via subscription, but we need to
          // filter the existing buffer manually
          this.renderFiltered();
        }
      });
    });

    // Set default filter button active
    const defaultBtn = filterContainer.querySelector('[data-team="white"]') as HTMLElement;
    if (defaultBtn) defaultBtn.classList.add('active');
  }

  private render(events: SimEvent[]): void {
    this.renderFiltered(events);
  }

  private renderFiltered(events?: SimEvent[]): void {
    // If events not passed, get from DOM state (re-filter scenario)
    // We'll re-use the last rendered events stored on the element
    const allEvents = events ?? (this as any)._lastEvents ?? [];
    if (events) (this as any)._lastEvents = events;

    // Filter by team (newest first)
    const filtered = allEvents
      .filter((e: SimEvent) => this.filter.passes(e))
      .reverse(); // newest on top

    if (filtered.length === 0) {
      this.emptyEl.style.display = 'block';
      // Remove all event items but keep empty placeholder
      const items = this.listEl.querySelectorAll('.event-item');
      items.forEach((item) => item.remove());
      return;
    }

    this.emptyEl.style.display = 'none';

    // Build HTML for filtered events (newest first)
    // Limit rendering to last 200 for performance
    const displayEvents = filtered.slice(0, 200);
    let html = '';
    for (const event of displayEvents) {
      html += this.renderEventItem(event);
    }
    // Replace content while preserving empty placeholder
    this.emptyEl.insertAdjacentHTML('afterend', html);
    // Remove old items (everything after emptyEl except the new ones)
    // Actually, simpler: set innerHTML and re-append empty
    this.listEl.innerHTML = `<p class="event-wall-empty" style="display:none;">暂无事件</p>${html}`;
    this.emptyEl = this.listEl.querySelector('.event-wall-empty') as HTMLElement;
  }

  private renderEventItem(event: SimEvent): string {
    const label = eventLabel(event.event_type);
    const colorClass = eventColorClass(event.event_type);
    const sourceClass = event.source.kind === 'kernel' ? 'source-kernel' : 'source-external';
    const sourceTagClass = event.source.kind === 'kernel' ? 'kernel' : 'external';
    const team = event.source.team ?? 'white';
    const producer = event.source.producer || '';

    // Summary line from payload
    const summary = this.payloadSummary(event.event_type, event.payload);

    return `
      <div class="event-item ${sourceClass} ${colorClass}" data-event-type="${event.event_type}">
        <div class="event-item-header">
          <span class="event-type-label">${label}</span>
          <span class="event-sim-time">t=${event.sim_time.toFixed(1)}s</span>
        </div>
        <div class="event-item-body">
          <span class="event-source-tag ${sourceTagClass}">${event.source.kind}</span>
          <span class="event-team-tag ${team}">${team}</span>
          ${producer ? `<span style="margin-left:4px;color:#888;">${producer}</span>` : ''}
          <span style="margin-left:4px;">${event.entity_uid}</span>
          ${summary ? `<br><span style="color:#999;font-size:10px;">${summary}</span>` : ''}
        </div>
      </div>
    `;
  }

  private payloadSummary(eventType: string, payload: Record<string, unknown>): string {
    if (!payload) return '';
    if (eventType === 'state.enter_track') {
      const tt = payload.target_type as string | undefined;
      const conf = payload.confidence as number | undefined;
      return tt ? `target_type=${tt}${conf ? `, conf=${(conf * 100).toFixed(0)}%` : ''}` : '';
    }
    if (eventType === 'state.exit_track') {
      const reason = payload.reason as string | undefined;
      return reason ? `reason=${reason}` : '';
    }
    if (eventType === 'target.discovered') {
      const tt = payload.target_type as string | undefined;
      const conf = payload.confidence as number | undefined;
      // 不显示 target_position：该字段是仿真真值坐标（见 entity-info-panel 同理），
      // 对选手可见的界面不展示。
      let s = tt ? `target_type=${tt}` : '';
      if (conf) s += `${s ? ', ' : ''}conf=${(conf * 100).toFixed(0)}%`;
      return s;
    }
    return '';
  }

  /** Dispose event subscriptions. */
  dispose(): void {
    this.unsubscribe?.();
  }
}
