/** 仿真结束结果总结弹窗 (result-modal)。
 *
 *  触发时机: sim:score 末帧(final=true)到达时由 app.ts 调 show()。
 *  解决的痛点: 仿真自然到时停止后, 旧逻辑在 session:idle 时无差别 scorePanel.reset()
 *  把最终分清掉, 用户"看不到得分"; 且 evaluation.json 保存在场景 output 目录、文件名是
 *  unix 时间戳, 用户既不知道在哪也找不到。本弹窗在结束时居中弹出, 醒目展示总分/
 *  PASS-FAIL/各维度, 并把完整 evaluation_path 可选中复制地展示出来。
 *
 *  设计与 ScorePanel 一致:
 *    1. 构造时一次性预创建所有 DOM, show() 仅改 textContent / width%, 不重建节点。
 *    2. 通过 .result-modal--open CSS 类切换显隐(默认 display:none)。
 *    3. 不直接 import RedisClient — 由调用方(app.ts onScore 回调)推送 ScoreSnapshot。
 *    4. 关闭途径三选一: 点「关闭」按钮 / 按 ESC / 点遮罩空白区。
 *    5. 维度中文标签复用 score-labels.ts(与 ScorePanel 同源, 不漂移)。
 */
import type { ScoreSnapshot } from '../core/redis-client';
import { dimLabel } from './score-labels';

/** 维度条目(与 ScorePanel.DimRow 同构, 局部定义避免跨文件类型耦合)。 */
interface DimRow {
  key: string;
  label: string;
  value: number;
}

/** 控制弹窗形态的 CSS 类(便于测试断言)。 */
export const RESULT_MODAL_CLASSES = {
  container: 'result-modal',
  open: 'result-modal--open',
} as const;

/** 弹窗按钮回调注入接口(app.ts 提供「关闭」与「再跑一次」的真实行为)。 */
export interface ResultModalCallbacks {
  /** 用户点了「再跑一次」(或按对应快捷键) — 用上次会话参数重新启动仿真。 */
  onRerun?: () => void;
}

export class ResultModal {
  private readonly container: HTMLElement;
  private overlay!: HTMLElement;
  private card!: HTMLElement;
  private totalEl!: HTMLElement;
  private badgeEl!: HTMLElement;
  private profileEl!: HTMLElement;
  private dimensionsEl!: HTMLElement;
  private evaluationPathEl!: HTMLElement;
  private closeBtn!: HTMLButtonElement;
  private rerunBtn!: HTMLButtonElement;
  private readonly callbacks: ResultModalCallbacks;

  /** 当前已渲染的维度 key 顺序 — 用于稳定结构的 in-place 更新(同 ScorePanel)。 */
  private renderedDimKeys: string[] = [];
  /** 当前锁定的 profile(首个非空 snapshot.profile), 防跨 profile 闪烁。 */
  private renderedProfile: string | null = null;
  /** ESC 键监听句柄(show 时绑, hide 时解, 避免泄漏/重复触发)。 */
  private escHandler: ((e: KeyboardEvent) => void) | null = null;

  constructor(containerId = 'result-modal', callbacks: ResultModalCallbacks = {}) {
    const el = document.getElementById(containerId);
    if (!el) {
      throw new Error(`ResultModal: container #${containerId} not found`);
    }
    this.container = el;
    this.container.classList.add(RESULT_MODAL_CLASSES.container);
    this.callbacks = callbacks;
    this.buildDom();
  }

  // ── public API ────────────────────────────────────────────────────────

  /** 由 app.ts onScore 回调在 final 帧调用 — 填充并显示弹窗。空快照 = noop。 */
  show(snapshot: ScoreSnapshot | null | undefined): void {
    if (!snapshot) return;
    this.fillCard(snapshot);
    this.container.classList.add(RESULT_MODAL_CLASSES.open);
    this.bindEsc();
  }

  /** 关闭弹窗(点关闭/ESC/遮罩)。不重置已填内容 — 下次 show 会重新 fill。 */
  hide(): void {
    this.container.classList.remove(RESULT_MODAL_CLASSES.open);
    this.unbindEsc();
  }

  /** 是否处于打开态(便于测试断言)。 */
  isOpen(): boolean {
    return this.container.classList.contains(RESULT_MODAL_CLASSES.open);
  }

  // ── internals ─────────────────────────────────────────────────────────

  /** 用快照数据填充卡片内容(总分/徽章/profile/维度/路径)。 */
  private fillCard(snapshot: ScoreSnapshot): void {
    // 防跨 profile 闪烁: 锁定首个非空 profile(同 ScorePanel 逻辑)。
    const snapProfile = snapshot.profile ?? null;
    if (snapProfile) {
      if (this.renderedProfile === null) {
        this.renderedProfile = snapProfile;
      } else if (this.renderedProfile !== snapProfile) {
        // 来自其他 profile 的帧 — 仅当用户尚未看到任何结果时才有意义,
        // 既然已锁定就忽略(避免维度 key 集抖动)。不更新展示。
        return;
      }
    }

    const score = Number(snapshot.total_score ?? 0);
    const intScore = Math.max(0, Math.min(100, Math.round(score)));
    this.totalEl.textContent = String(intScore);

    // 徽章: final 帧 passed→PASS, 未通过→FAIL(非 final 不应进此弹窗, 但兜底用 FAIL)。
    const passed = Boolean(snapshot.passed);
    if (passed) {
      this.setBadge('✓ 通过', 'pass');
    } else {
      this.setBadge('✗ 未通过', 'fail');
    }

    this.profileEl.textContent = snapshot.profile ?? '--';

    // 维度明细(中文标签来自 score-labels)。
    const dims = this.parseDimensions(snapshot.dimension_scores);
    this.renderDimensions(dims);

    // 保存路径: 醒目展示完整路径, 用户可直接选中复制。
    this.evaluationPathEl.textContent = snapshot.evaluation_path ?? '--';
  }

  private buildDom(): void {
    // 半透明遮罩(点空白区关闭)。
    this.overlay = document.createElement('div');
    this.overlay.className = 'result-modal__overlay';
    this.overlay.addEventListener('click', (e) => {
      // 仅点击遮罩本身(非冒泡自卡片)才关闭。
      if (e.target === this.overlay) this.hide();
    });

    // 居中卡片。
    this.card = document.createElement('div');
    this.card.className = 'result-modal__card';
    this.card.setAttribute('role', 'dialog');
    this.card.setAttribute('aria-modal', 'true');
    this.card.setAttribute('aria-label', '运行结果');

    // 标题。
    const header = document.createElement('div');
    header.className = 'result-modal__header';
    const title = document.createElement('h3');
    title.textContent = '运行结束';
    header.appendChild(title);

    // 总分行: 大字号总分 + /100 + PASS/FAIL 徽章。
    const totalRow = document.createElement('div');
    totalRow.className = 'result-modal__total';
    this.totalEl = document.createElement('span');
    this.totalEl.className = 'result-modal__total-value';
    this.totalEl.setAttribute('data-role', 'total-score');
    this.totalEl.textContent = '--';
    const suffix = document.createElement('span');
    suffix.className = 'result-modal__total-suffix';
    suffix.textContent = '/ 100';
    this.badgeEl = document.createElement('span');
    this.badgeEl.className = 'result-modal__badge';
    this.badgeEl.setAttribute('data-role', 'badge');
    totalRow.appendChild(this.totalEl);
    totalRow.appendChild(suffix);
    totalRow.appendChild(this.badgeEl);

    // profile 行。
    const meta = document.createElement('div');
    meta.className = 'result-modal__meta';
    const profileLabel = document.createElement('span');
    profileLabel.className = 'result-modal__meta-label';
    profileLabel.textContent = '评分场景: ';
    this.profileEl = document.createElement('span');
    this.profileEl.setAttribute('data-role', 'profile');
    this.profileEl.textContent = '--';
    meta.appendChild(profileLabel);
    meta.appendChild(this.profileEl);

    // 维度条形图容器。
    this.dimensionsEl = document.createElement('div');
    this.dimensionsEl.className = 'result-modal__dimensions';
    this.dimensionsEl.setAttribute('data-role', 'dimensions');

    // 保存路径区: 提示文案 + 可选中复制的完整路径。
    const pathSection = document.createElement('div');
    pathSection.className = 'result-modal__path';
    const pathHint = document.createElement('div');
    pathHint.className = 'result-modal__path-hint';
    pathHint.textContent = '完整评分已保存为 JSON 文件:';
    this.evaluationPathEl = document.createElement('code');
    this.evaluationPathEl.className = 'result-modal__path-value';
    this.evaluationPathEl.setAttribute('data-role', 'evaluation-path');
    this.evaluationPathEl.textContent = '--';
    pathSection.appendChild(pathHint);
    pathSection.appendChild(this.evaluationPathEl);

    // 按钮行: 关闭 + 再跑一次。
    const actions = document.createElement('div');
    actions.className = 'result-modal__actions';
    this.rerunBtn = document.createElement('button');
    this.rerunBtn.type = 'button';
    this.rerunBtn.className = 'result-modal__btn result-modal__btn--rerun';
    this.rerunBtn.textContent = '再跑一次';
    this.rerunBtn.addEventListener('click', () => {
      // 再跑前先关闭弹窗(否则启动进度与弹窗重叠)。
      this.hide();
      this.callbacks.onRerun?.();
    });
    this.closeBtn = document.createElement('button');
    this.closeBtn.type = 'button';
    this.closeBtn.className = 'result-modal__btn result-modal__btn--close';
    this.closeBtn.textContent = '关闭';
    this.closeBtn.addEventListener('click', () => this.hide());
    actions.appendChild(this.rerunBtn);
    actions.appendChild(this.closeBtn);

    this.card.appendChild(header);
    this.card.appendChild(totalRow);
    this.card.appendChild(meta);
    this.card.appendChild(this.dimensionsEl);
    this.card.appendChild(pathSection);
    this.card.appendChild(actions);

    this.overlay.appendChild(this.card);
    this.container.appendChild(this.overlay);
  }

  private setBadge(text: string, variant: 'pass' | 'fail'): void {
    this.badgeEl.textContent = text;
    this.badgeEl.classList.remove(
      'result-modal__badge--pass',
      'result-modal__badge--fail',
    );
    this.badgeEl.classList.add(`result-modal__badge--${variant}`);
  }

  private parseDimensions(dims: Record<string, number> | undefined): DimRow[] {
    if (!dims) return [];
    return Object.entries(dims).map(([key, value]) => ({
      key,
      label: dimLabel(this.renderedProfile, key),
      value: Number(value ?? 0),
    }));
  }

  /**
   * Stable-structure incremental update(同 ScorePanel): 首次按 key 顺序建行,
   * 后续只更新数值与宽度条, 避免重建 DOM 让条形图"跳"。
   */
  private renderDimensions(dims: DimRow[]): void {
    const newKeys = dims.map((d) => d.key);
    const sameStructure =
      newKeys.length === this.renderedDimKeys.length &&
      newKeys.every((k, i) => k === this.renderedDimKeys[i]);

    if (!sameStructure) {
      this.dimensionsEl.innerHTML = '';
      for (const d of dims) {
        this.dimensionsEl.appendChild(this.buildDimRow(d));
      }
      this.renderedDimKeys = newKeys;
      return;
    }

    for (const d of dims) {
      const row = this.dimensionsEl.querySelector<HTMLElement>(
        `.result-modal__dim[data-key="${d.key}"]`,
      );
      if (!row) continue;
      const valEl = row.querySelector<HTMLElement>('[data-role="dim-value"]');
      const fillEl = row.querySelector<HTMLElement>('[data-role="dim-fill"]');
      if (valEl) valEl.textContent = d.value.toFixed(1);
      if (fillEl) {
        const clamped = Math.max(0, Math.min(100, d.value));
        fillEl.style.width = `${clamped.toFixed(1)}%`;
      }
    }
  }

  private buildDimRow(d: DimRow): HTMLElement {
    const row = document.createElement('div');
    row.className = 'result-modal__dim';
    row.setAttribute('data-key', d.key);

    const label = document.createElement('span');
    label.className = 'result-modal__dim-label';
    label.textContent = d.label;

    const track = document.createElement('div');
    track.className = 'result-modal__dim-track';
    const fill = document.createElement('div');
    fill.className = 'result-modal__dim-fill';
    fill.setAttribute('data-role', 'dim-fill');
    const clamped = Math.max(0, Math.min(100, d.value));
    fill.style.width = `${clamped.toFixed(1)}%`;
    track.appendChild(fill);

    const valEl = document.createElement('span');
    valEl.className = 'result-modal__dim-value';
    valEl.setAttribute('data-role', 'dim-value');
    valEl.textContent = d.value.toFixed(1);

    row.appendChild(label);
    row.appendChild(track);
    row.appendChild(valEl);
    return row;
  }

  /** show() 时绑定 ESC 关闭; hide() 时解绑(避免弹窗关闭后仍拦截键盘)。 */
  private bindEsc(): void {
    if (this.escHandler) return;  // 已绑, 幂等
    this.escHandler = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        e.preventDefault();
        this.hide();
      }
    };
    document.addEventListener('keydown', this.escHandler);
  }

  private unbindEsc(): void {
    if (this.escHandler) {
      document.removeEventListener('keydown', this.escHandler);
      this.escHandler = null;
    }
  }
}
