import * as THREE from 'three';
import { WGS84Projection } from '../core/wgs84-projection';

export interface TerrainConfig {
  visible: boolean;
}

export interface HeightmapData {
  width: number;
  height: number;
  elevations: number[];
  vertexColors: number[];
  contours: number[][][];  // each contour: [[lat, lon, elev], ...]
  bounds: {
    minLatitude: number;
    maxLatitude: number;
    minLongitude: number;
    maxLongitude: number;
  };
}

export class TerrainRenderer {
  private mesh: THREE.Mesh | null = null;
  private wireframe: THREE.LineSegments | null = null;
  private contourGroup: THREE.Group | null = null;
  private projection: WGS84Projection;
  private config: TerrainConfig;
  private loaded = false;
  private heightmapData: HeightmapData | null = null;

  constructor(projection: WGS84Projection, config?: Partial<TerrainConfig>) {
    this.projection = projection;
    this.config = {
      visible: config?.visible ?? true,
    };
  }

  /**
   * Load heightmap data from a JSON URL and create the terrain mesh.
   */
  async load(url: string): Promise<void> {
    try {
      const response = await fetch(url);
      if (!response.ok) {
        throw new Error(`Failed to load heightmap: ${response.status} ${response.statusText}`);
      }
      const data: HeightmapData = await response.json();
      this.heightmapData = data;
      this.createTerrain(data);
      this.loaded = true;
      console.log(`Terrain loaded: ${data.width}x${data.height} grid`);
    } catch (error) {
      console.error('Failed to load terrain:', error);
    }
  }

  /**
   * Create the Three.js terrain mesh from heightmap data.
   *
   * Each vertex is positioned by converting its (lat, lon, elevation) to
   * the ENU Three.js coordinate system via WGS84Projection, ensuring the
   * terrain aligns perfectly with other scene entities.
   */
  private createTerrain(data: HeightmapData): void {
    const { width, height, elevations, bounds } = data;
    const { minLatitude, maxLatitude, minLongitude, maxLongitude } = bounds;

    // Create a plane geometry with the appropriate segment count
    // We'll displace vertices individually
    const geometry = new THREE.BufferGeometry();

    const verticesCount = width * height;

    // Allocate position and color arrays
    const positions = new Float32Array(verticesCount * 3);
    const colors = new Float32Array(verticesCount * 3);
    const uvs = new Float32Array(verticesCount * 2);

    // Build vertex data
    let idx = 0;
    for (let iz = 0; iz < height; iz++) {
      // Latitude: row index maps to latitude (top of image = max latitude)
      const lat = maxLatitude - (iz / (height - 1)) * (maxLatitude - minLatitude);

      for (let ix = 0; ix < width; ix++) {
        // Longitude: column index maps to longitude (left of image = min longitude)
        const lon = minLongitude + (ix / (width - 1)) * (maxLongitude - minLongitude);

        // Elevation from heightmap
        const elev = elevations[iz * width + ix]!;

        // Convert WGS84 to Three.js position
        const pos = this.projection.toVector3(lat, lon, elev);

        positions[idx * 3] = pos.x;
        positions[idx * 3 + 1] = pos.y;
        positions[idx * 3 + 2] = pos.z;

        // 科技风:始终用高程色阶(忽略 heightmap 自带的写实质感 vertexColors)
        const c = this.elevationToColor(elev);
        colors[idx * 3] = c.r;
        colors[idx * 3 + 1] = c.g;
        colors[idx * 3 + 2] = c.b;

        // UV coordinates for optional texturing
        uvs[idx * 2] = ix / (width - 1);
        uvs[idx * 2 + 1]  = 1.0 - iz / (height - 1);

        idx++;
      }
    }

    // Build index buffer (triangle strip)
    const indices: number[] = [];
    for (let iz = 0; iz < height - 1; iz++) {
      for (let ix = 0; ix < width - 1; ix++) {
        const a = iz * width + ix;
        const b = iz * width + ix + 1;
        const c = (iz + 1) * width + ix;
        const d = (iz + 1) * width + ix + 1;

        // Two triangles per grid cell
        indices.push(a, b, c);
        indices.push(b, d, c);
      }
    }

    geometry.setIndex(indices);
    geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));
    geometry.setAttribute('uv', new THREE.BufferAttribute(uvs, 2));

    geometry.computeVertexNormals();

    // 科技风材质:深色金属底 + 高程色 + 微自发光
    const material = new THREE.MeshStandardMaterial({
      vertexColors: true,
      side: THREE.DoubleSide,
      visible: this.config.visible,
      roughness: 0.55,
      metalness: 0.35,
      flatShading: false,
      emissive: 0x0a1830,
      emissiveIntensity: 0.35,
    });

    this.mesh = new THREE.Mesh(geometry, material);
    this.mesh.renderOrder = -1; // Render before transparent overlays
    this.mesh.receiveShadow = true;

    // 科技风网格叠加:细密青色线框,贴合地形起伏
    const wireGeom = new THREE.WireframeGeometry(geometry);
    const wireMat = new THREE.LineBasicMaterial({
      color: 0x38bdf8,
      transparent: true,
      opacity: 0.14,
      depthWrite: false,
    });
    this.wireframe = new THREE.LineSegments(wireGeom, wireMat);
    this.mesh.add(this.wireframe);

    // Create contour lines
    this.createContours(data);
  }

  /**
   * Create contour line geometry from precomputed contour polylines.
   */
  private createContours(data: HeightmapData): void {
    const { contours } = data;
    if (!contours || contours.length === 0) return;

    this.contourGroup = new THREE.Group();

    for (const polyline of contours) {
      if (polyline.length < 2) continue;

      const points: THREE.Vector3[] = [];
      for (const pt of polyline) {
        const lat = pt[0]!;
        const lon = pt[1]!;
        const elev = pt[2]!;
        const pos = this.projection.toVector3(lat, lon, elev);
        points.push(pos);
      }

      const geometry = new THREE.BufferGeometry().setFromPoints(points);
      const material = new THREE.LineBasicMaterial({
        color: 0x38bdf8,
        transparent: true,
        opacity: 0.55,
        depthTest: true,
      });
      const line = new THREE.Line(geometry, material);
      this.contourGroup.add(line);
    }
  }

  /**
   * Map elevation to a sci-fi / tactical color ramp: ascending from dark blue
   * to bright cyan as elevation rises (120–280 m, based on HeightSample.csv).
   */
  private elevationToColor(elevation: number): THREE.Color {
    // 全部为正(CSV 真实高程 ~120~274m),归一化到 120~280m,深蓝 → 亮青
    const t = Math.max(0, Math.min(1, (elevation - 120) / (280 - 120)));
    return new THREE.Color(
      0.04 + 0.18 * t,
      0.10 + 0.64 * t,
      0.20 + 0.77 * t,
    );
  }

  /**
   * Get the terrain mesh, or null if not loaded yet.
   */
  getMesh(): THREE.Mesh | null {
    return this.mesh;
  }

  /**
   * Get the contour line group, or null if not loaded yet.
   */
  getContourGroup(): THREE.Group | null {
    return this.contourGroup;
  }

  /**
   * Returns true if terrain data has been loaded and mesh created.
   */
  isLoaded(): boolean {
    return this.loaded;
  }

  /**
   * Toggle terrain visibility.
   */
  setVisible(visible: boolean): void {
    this.config.visible = visible;
    if (this.mesh) {
      this.mesh.visible = visible;
    }
    if (this.contourGroup) {
      this.contourGroup.visible = visible;
    }
  }

  /**
   * Get current visibility state.
   */
  isVisible(): boolean {
    return this.config.visible;
  }

  /**
   * Query terrain elevation at a given (latitude, longitude) using bilinear interpolation.
   * Returns elevation in meters, or 0 if terrain is not loaded or point is out of bounds.
   */
  getElevation(latitude: number, longitude: number): number {
    if (!this.heightmapData) return 0;

    const { width, height, elevations, bounds } = this.heightmapData;
    const { minLatitude, maxLatitude, minLongitude, maxLongitude } = bounds;

    // 越界时 clamp 到最近边界采样,避免覆盖区外的实体突然掉到 0
    // (视觉上车辆/航点在 heightmap 边缘"悬空掉崖")。
    if (latitude < minLatitude || latitude > maxLatitude ||
        longitude < minLongitude || longitude > maxLongitude) {
      return this.getElevation(
        Math.max(minLatitude, Math.min(maxLatitude, latitude)),
        Math.max(minLongitude, Math.min(maxLongitude, longitude)),
      );
    }

    // Compute grid coordinates (fractional)
    const fx = (longitude - minLongitude) / (maxLongitude - minLongitude) * (width - 1);
    const fy = (maxLatitude - latitude) / (maxLatitude - minLatitude) * (height - 1);

    const ix = Math.floor(fx);
    const iy = Math.floor(fy);
    const tx = fx - ix;
    const ty = fy - iy;

    // Clamp to valid range for interpolation
    const x0 = Math.max(0, Math.min(width - 1, ix));
    const x1 = Math.max(0, Math.min(width - 1, ix + 1));
    const y0 = Math.max(0, Math.min(height - 1, iy));
    const y1 = Math.max(0, Math.min(height - 1, iy + 1));

    // Four corners
    const v00 = elevations[y0 * width + x0]!;
    const v10 = elevations[y0 * width + x1]!;
    const v01 = elevations[y1 * width + x0]!;
    const v11 = elevations[y1 * width + x1]!;

    // Bilinear interpolation
    const v0 = v00 + (v10 - v00) * tx;
    const v1 = v01 + (v11 - v01) * tx;
    return v0 + (v1 - v0) * ty;
  }
}
