//
// Spec 020 T7: shared label factory. Before this, createLabel() was
// copy-pasted three times (uav-model / vehicle-model / decoy-model),
// differing only in text + fillStyle. This module produces the same
// THREE.Sprite those duplicated bodies produced, parameterised by text
// + colour. Canvas dimensions, font, scale and the dark background are
// identical to the originals so rendered output is byte-equivalent.
import * as THREE from 'three';

export interface LabelOptions {
  /** Sprite text (e.g. "UAV", "TARGET", "DECOY"). */
  text: string;
  /** CSS colour for the rendered text. Defaults to 'white'. */
  fillStyle?: string;
}

/**
 * Build a 128x64 canvas sprite with a translucent black background and
 * centred bold text. Scale (10, 5, 1) matches every prior caller so the
 * on-screen size is unchanged.
 */
export function createLabel(opts: LabelOptions): THREE.Sprite {
  const { text, fillStyle = 'white' } = opts;

  const canvas = document.createElement('canvas');
  const context = canvas.getContext('2d')!;
  canvas.width = 128;
  canvas.height = 64;

  context.fillStyle = 'rgba(0, 0, 0, 0.7)';
  context.fillRect(0, 0, canvas.width, canvas.height);

  context.fillStyle = fillStyle;
  context.font = 'bold 24px Arial';
  context.textAlign = 'center';
  context.textBaseline = 'middle';
  context.fillText(text, canvas.width / 2, canvas.height / 2);

  const texture = new THREE.CanvasTexture(canvas);
  const material = new THREE.SpriteMaterial({ map: texture });
  const sprite = new THREE.Sprite(material);
  sprite.scale.set(10, 5, 1);

  return sprite;
}
