/** Spec 025 — 实时评分浮动居中面板 (sim:score 频道消费者)。
 *
 *  该面板在屏幕中央以两种状态存在:
 *    - 折叠态: 一个 56px 圆形按钮,只显示当前总分(整数),半透明玻璃质感,
 *      点击后切换为展开态。
 *    - 展开态: 居中的窄面板(max-width 320px),显示总分大字号、通过/未通过徽章、
 *      profile 名、sim_time、维度明细(7 行条形图)、最终帧持久化路径提示,
 *      标题右侧的 × 按钮可折回折叠态。
 *
 *  设计原则:
 *    1. 构造时一次性预创建所有 DOM,update() 仅修改 textContent / width%,
 *       不重建节点 — 与 entity-info-panel 同款的"稳定结构 + 增量更新"模式,
 *       避免 10 Hz 高频更新时 click 事件被劫持或闪烁。
 *    2. 通过 .score-panel--collapsed / .score-panel--expanded CSS 类切换状态。
 *    3. 仿真器尚未发布 score / 切换到非评分示例 / 关闭仿真 三种情况下,面板
 *       走 reset() → 显示 "等待评分…" 占位文字(road 例用 showUnavailable())。
 *    4. 不直接 import RedisClient — 由调用方(redis-client.onScore 回调)
 *       推送 ScoreSnapshot 数据;面板只负责渲染。
 */
import type { ScoreSnapshot } from '../core/redis-client';
// 维度中文标签已抽离到 score-labels.ts, 供 ScorePanel 与 ResultModal 共享,
// 避免标签逻辑重复漂移。
import { dimLabel } from './score-labels';

/** Spec 025: 维度条目构造参数(被 buildDimensionsHtml 与 updateDimensions 共享)。 */
interface DimRow {
  key: string;
  label: string;
  /** 当前维度分(0-100)。 */
  value: number;
}

/** Spec 025: 控制面板展示形态的 CSS 类常量(便于测试断言)。 */
export const SCORE_PANEL_CLASSES = {
  container: 'score-panel',
  collapsed: 'score-panel--collapsed',
  expanded: 'score-panel--expanded',
  unavailable: 'score-panel--unavailable',
} as const;

export class ScorePanel {
  private readonly container: HTMLElement;
  private collapsedBtn!: HTMLButtonElement;
  private collapsedScoreEl!: HTMLElement;
  private expandedPanel!: HTMLElement;
  private closeBtn!: HTMLButtonElement;
  private totalEl!: HTMLElement;
  private badgeEl!: HTMLElement;
  private profileEl!: HTMLElement;
  private simTimeEl!: HTMLElement;
  private dimensionsEl!: HTMLElement;
  private finalEl!: HTMLElement;
  private evaluationPathEl!: HTMLElement;
  private unavailableEl!: HTMLElement;

  /** 当前已渲染的维度 key 顺序 — 用于稳定结构的 in-place 更新。 */
  private renderedDimKeys: string[] = [];
  /**
   * 当前锁定的 profile(首个非空 snapshot.profile)。一旦锁定, 来自其他
   * profile 的帧(残留进程/旧 publisher 混入)被忽略, 避免维度 key 集逐帧
   * 变化导致 renderDimensions 全量重建 → 闪烁。reset() 清空以支持合法的
   * 赛题切换(切换时 app.ts 会先调 reset)。
   */
  private renderedProfile: string | null = null;

  constructor(containerId = 'score-panel') {
    const el = document.getElementById(containerId);
    if (!el) {
      throw new Error(`ScorePanel: container #${containerId} not found`);
    }
    this.container = el;
    this.container.classList.add(SCORE_PANEL_CLASSES.container);
    this.container.classList.add(SCORE_PANEL_CLASSES.collapsed);
    this.buildDom();
  }

  // ── public API ────────────────────────────────────────────────────────

  /** 每 tick 由 redis-client.onScore 回调推送的快照。空快照 = noop。 */
  update(snapshot: ScoreSnapshot | null | undefined): void {
    if (!snapshot) return;
    // road 例的"未启用"占位优先级最高(由 showUnavailable 显式设置)。
    if (this.container.classList.contains(SCORE_PANEL_CLASSES.unavailable)) {
      return;
    }
    // 防闪烁: 锁定首个非空 profile, 忽略来自其他 profile 的帧(残留进程/
    // 旧 publisher 混入同一 sim:score 流)。否则 renderDimensions 会因维度
    // key 集逐帧变化而全量重建 → 评分面板闪烁。reset() 清空锁定以支持
    // 合法赛题切换。
    const snapProfile = snapshot.profile ?? null;
    if (snapProfile) {
      if (this.renderedProfile === null) {
        this.renderedProfile = snapProfile;
      } else if (this.renderedProfile !== snapProfile) {
        return;  // 来自其他 profile 的帧, 丢弃不渲染
      }
    }
    const score = Number(snapshot.total_score ?? 0);
    const intScore = Math.max(0, Math.min(100, Math.round(score)));

    // 折叠态数字始终刷新(让用户即使不展开也能感受到 score 在变化)。
    this.collapsedScoreEl.textContent = String(intScore);
    this.totalEl.textContent = String(intScore);

    // 徽章: 通过为绿色 ✓ PASS,未通过为灰色(无对勾) PENDING,final 帧未通过则 ✗ FAIL。
    const passed = Boolean(snapshot.passed);
    const final = Boolean(snapshot.final);
    if (final && !passed) {
      this.setBadge('✗ FAIL', 'fail');
    } else if (passed) {
      this.setBadge('✓ PASS', 'pass');
    } else {
      this.setBadge('PENDING', 'pending');
    }

    // profile + sim_time 元数据。
    this.profileEl.textContent = snapshot.profile ?? '--';
    const simTime = typeof snapshot.sim_time === 'number'
      ? snapshot.sim_time.toFixed(1) + ' s' : '--';
    this.simTimeEl.textContent = simTime;

    // 维度明细(只更新有数据的维度,顺序按 evaluator 返回顺序)。
    const dims = this.parseDimensions(snapshot.dimension_scores);
    this.renderDimensions(dims);

    // final 帧: 提示用户 evaluation.json 已落地。
    if (final) {
      this.finalEl.hidden = false;
      this.evaluationPathEl.textContent = snapshot.evaluation_path ?? '--';
    }
  }

  /** sessionStatus === 'idle' 时调用 — 清空面板回到"等待评分…"。 */
  reset(): void {
    this.container.classList.remove(SCORE_PANEL_CLASSES.unavailable);
    this.collapsedScoreEl.textContent = '--';
    this.totalEl.textContent = '--';
    this.setBadge('PENDING', 'pending');
    this.profileEl.textContent = '--';
    this.simTimeEl.textContent = '--';
    this.dimensionsEl.innerHTML = '';
    this.renderedDimKeys = [];
    this.renderedProfile = null;
    this.finalEl.hidden = true;
    this.evaluationPathEl.textContent = '--';
    this.collapse();
  }

  /** 当前示例无 score 系统(road_target 等) — 显示占位文字。 */
  showUnavailable(reason: string): void {
    this.container.classList.add(SCORE_PANEL_CLASSES.unavailable);
    this.unavailableEl.textContent = reason;
    this.unavailableEl.hidden = false;
    this.collapsedScoreEl.textContent = 'N/A';
    this.totalEl.textContent = 'N/A';
    this.setBadge('UNAVAILABLE', 'unavailable');
  }

  /** 测试/外部代码主动展开 / 折叠。 */
  expand(): void {
    this.container.classList.remove(SCORE_PANEL_CLASSES.collapsed);
    this.container.classList.add(SCORE_PANEL_CLASSES.expanded);
  }

  collapse(): void {
    this.container.classList.remove(SCORE_PANEL_CLASSES.expanded);
    this.container.classList.add(SCORE_PANEL_CLASSES.collapsed);
  }

  /** 是否处于展开态(便于测试断言)。 */
  isExpanded(): boolean {
    return this.container.classList.contains(SCORE_PANEL_CLASSES.expanded);
  }

  /** 是否处于 "unavailable" 占位态。 */
  isUnavailable(): boolean {
    return this.container.classList.contains(SCORE_PANEL_CLASSES.unavailable);
  }

  // ── internals ─────────────────────────────────────────────────────────

  private buildDom(): void {
    // 折叠态: 圆形按钮,内部显示总分数字。
    this.collapsedBtn = document.createElement('button');
    this.collapsedBtn.type = 'button';
    this.collapsedBtn.className = 'score-panel__collapsed';
    this.collapsedBtn.setAttribute('aria-label', '展开评分面板');
    this.collapsedScoreEl = document.createElement('span');
    this.collapsedScoreEl.className = 'score-panel__collapsed-score';
    this.collapsedScoreEl.setAttribute('data-role', 'collapsed-score');
    this.collapsedScoreEl.textContent = '--';
    this.collapsedBtn.appendChild(this.collapsedScoreEl);
    this.collapsedBtn.addEventListener('click', () => this.expand());

    // 展开态面板。
    this.expandedPanel = document.createElement('div');
    this.expandedPanel.className = 'score-panel__expanded';
    this.expandedPanel.setAttribute('role', 'dialog');
    this.expandedPanel.setAttribute('aria-label', '实时评分');

    const header = document.createElement('div');
    header.className = 'score-panel__header';
    const title = document.createElement('h3');
    title.textContent = '实时评分';
    this.closeBtn = document.createElement('button');
    this.closeBtn.type = 'button';
    this.closeBtn.className = 'score-panel__close';
    this.closeBtn.setAttribute('aria-label', '折叠评分面板');
    this.closeBtn.textContent = '×';
    this.closeBtn.addEventListener('click', () => this.collapse());
    header.appendChild(title);
    header.appendChild(this.closeBtn);

    const totalRow = document.createElement('div');
    totalRow.className = 'score-panel__total';
    this.totalEl = document.createElement('span');
    this.totalEl.className = 'score-panel__total-value';
    this.totalEl.setAttribute('data-role', 'total-score');
    this.totalEl.textContent = '--';
    const suffix = document.createElement('span');
    suffix.className = 'score-panel__total-suffix';
    suffix.textContent = '/ 100';
    this.badgeEl = document.createElement('span');
    this.badgeEl.className = 'score-panel__badge';
    this.badgeEl.setAttribute('data-role', 'badge');
    this.badgeEl.hidden = true;
    totalRow.appendChild(this.totalEl);
    totalRow.appendChild(suffix);
    totalRow.appendChild(this.badgeEl);

    const meta = document.createElement('div');
    meta.className = 'score-panel__meta';
    const profileLabel = document.createElement('span');
    profileLabel.className = 'score-panel__meta-label';
    profileLabel.textContent = 'profile: ';
    this.profileEl = document.createElement('span');
    this.profileEl.setAttribute('data-role', 'profile');
    this.profileEl.textContent = '--';
    const dot = document.createElement('span');
    dot.textContent = '  ·  ';
    const simTimeLabel = document.createElement('span');
    simTimeLabel.className = 'score-panel__meta-label';
    simTimeLabel.textContent = 'sim_time: ';
    this.simTimeEl = document.createElement('span');
    this.simTimeEl.setAttribute('data-role', 'sim-time');
    this.simTimeEl.textContent = '--';
    meta.appendChild(profileLabel);
    meta.appendChild(this.profileEl);
    meta.appendChild(dot);
    meta.appendChild(simTimeLabel);
    meta.appendChild(this.simTimeEl);

    this.dimensionsEl = document.createElement('div');
    this.dimensionsEl.className = 'score-panel__dimensions';
    this.dimensionsEl.setAttribute('data-role', 'dimensions');

    this.finalEl = document.createElement('div');
    this.finalEl.className = 'score-panel__final';
    this.finalEl.setAttribute('data-role', 'final');
    this.finalEl.hidden = true;
    this.evaluationPathEl = document.createElement('span');
    this.evaluationPathEl.setAttribute('data-role', 'evaluation-path');
    this.evaluationPathEl.textContent = '--';
    this.finalEl.appendChild(
      document.createTextNode('✓ 最终评分已保存至 ')
    );
    this.finalEl.appendChild(this.evaluationPathEl);

    this.unavailableEl = document.createElement('div');
    this.unavailableEl.className = 'score-panel__unavailable';
    this.unavailableEl.setAttribute('data-role', 'unavailable');
    this.unavailableEl.hidden = true;
    this.unavailableEl.textContent = '该示例未接入评分系统';

    this.expandedPanel.appendChild(header);
    this.expandedPanel.appendChild(totalRow);
    this.expandedPanel.appendChild(meta);
    this.expandedPanel.appendChild(this.dimensionsEl);
    this.expandedPanel.appendChild(this.finalEl);
    this.expandedPanel.appendChild(this.unavailableEl);

    this.container.appendChild(this.collapsedBtn);
    this.container.appendChild(this.expandedPanel);
  }

  private setBadge(text: string, variant: 'pass' | 'fail' | 'pending' | 'unavailable'): void {
    this.badgeEl.textContent = text;
    this.badgeEl.classList.remove(
      'score-panel__badge--pass',
      'score-panel__badge--fail',
      'score-panel__badge--pending',
      'score-panel__badge--unavailable',
    );
    this.badgeEl.classList.add(`score-panel__badge--${variant}`);
    this.badgeEl.hidden = false;
  }

  /** 把 evaluator 返回的 dimension_scores 字典归一为有序 DimRow[]。 */
  private parseDimensions(dims: Record<string, number> | undefined): DimRow[] {
    if (!dims) return [];
    return Object.entries(dims).map(([key, value]) => ({
      key,
      label: dimLabel(this.renderedProfile, key),
      value: Number(value ?? 0),
    }));
  }

  /**
   * Stable-structure incremental update: 首次按 key 顺序建行,后续只更新
   * 数值与宽度条,避免重建 DOM 让条形图"跳"。
   */
  private renderDimensions(dims: DimRow[]): void {
    const newKeys = dims.map((d) => d.key);
    const sameStructure =
      newKeys.length === this.renderedDimKeys.length &&
      newKeys.every((k, i) => k === this.renderedDimKeys[i]);

    if (!sameStructure) {
      this.dimensionsEl.innerHTML = '';
      for (const d of dims) {
        this.dimensionsEl.appendChild(this.buildDimRow(d));
      }
      this.renderedDimKeys = newKeys;
      return;
    }

    // In-place: 用 data-key 选择器更新数值与宽度条。
    for (const d of dims) {
      const row = this.dimensionsEl.querySelector<HTMLElement>(
        `.score-panel__dim[data-key="${d.key}"]`,
      );
      if (!row) continue;
      const valEl = row.querySelector<HTMLElement>('[data-role="dim-value"]');
      const fillEl = row.querySelector<HTMLElement>('[data-role="dim-fill"]');
      if (valEl) valEl.textContent = d.value.toFixed(1);
      if (fillEl) {
        const clamped = Math.max(0, Math.min(100, d.value));
        fillEl.style.width = `${clamped.toFixed(1)}%`;
      }
    }
  }

  private buildDimRow(d: DimRow): HTMLElement {
    const row = document.createElement('div');
    row.className = 'score-panel__dim';
    row.setAttribute('data-key', d.key);

    const label = document.createElement('span');
    label.className = 'score-panel__dim-label';
    label.textContent = d.label;

    const track = document.createElement('div');
    track.className = 'score-panel__dim-track';
    const fill = document.createElement('div');
    fill.className = 'score-panel__dim-fill';
    fill.setAttribute('data-role', 'dim-fill');
    const clamped = Math.max(0, Math.min(100, d.value));
    fill.style.width = `${clamped.toFixed(1)}%`;
    track.appendChild(fill);

    const valEl = document.createElement('span');
    valEl.className = 'score-panel__dim-value';
    valEl.setAttribute('data-role', 'dim-value');
    valEl.textContent = d.value.toFixed(1);

    row.appendChild(label);
    row.appendChild(track);
    row.appendChild(valEl);
    return row;
  }
}