import { EntityState } from '../core/wgs84-projection';
// Spec 020 T6: EntityType + per-kind presentation metadata live in the
// EntityKindRegistry. The list panel routes kind → dot/label via the
// registry instead of a ternary chain.
import { describeEntityKind, EntityType } from '../core/entity-kind-registry';

export type { EntityType };

export type EntityClickCallback = (entityType: EntityType, entityId?: string) => void;

interface ButtonEntry {
  el: HTMLButtonElement;
  uid: string;
  entityType: EntityType;
}

export class EntityListPanel {
  private container: HTMLElement;
  private buttons: Map<EntityType, HTMLElement> = new Map();
  private onClickCallback: EntityClickCallback | null = null;
  private selected: EntityType | null = null;

  // Spec 017 Bug 1/2: multi-entity list state. Buttons are keyed by uid
  // (not EntityType, since there are many entities of the same kind).
  // Rebuild happens only when the set of uids CHANGES — not every frame
  // (which would tear down click handlers before the user could click).
  private listEl: HTMLElement | null = null;
  private multiButtons: Map<string, ButtonEntry> = new Map();
  private knownUids: string = '';
  private multiSelectedUid: string | null = null;

  constructor(containerId: string) {
    const container = document.getElementById(containerId);
    if (!container) throw new Error(`Container #${containerId} not found`);
    this.container = container;
    this.render();
  }

  private render(): void {
    // Header is provided by index.html; fill the .entity-list body only.
    const listEl = this.container.querySelector('.entity-list') as HTMLElement | null;
    if (!listEl) return;
    this.listEl = listEl;
    listEl.innerHTML = `
      <button class="entity-btn" data-entity="uav">
        <span class="entity-dot uav-dot"></span> UAV
      </button>
      <button class="entity-btn" data-entity="target">
        <span class="entity-dot target-dot"></span> Target Vehicle
      </button>
      <button class="entity-btn" data-entity="gimbal">
        <span class="entity-dot gimbal-dot"></span> Gimbal
      </button>
    `;

    for (const type of ['uav', 'target', 'gimbal'] as EntityType[]) {
      const btn = listEl.querySelector(`[data-entity="${type}"]`) as HTMLElement;
      if (btn) {
        this.buttons.set(type, btn);
        btn.addEventListener('click', () => {
          this.select(type);
          this.onClickCallback?.(type);
        });
      }
    }
  }

  private select(type: EntityType): void {
    if (this.selected) {
      const prev = this.buttons.get(this.selected);
      prev?.classList.remove('selected');
    }
    this.selected = type;
    const btn = this.buttons.get(type);
    btn?.classList.add('selected');
  }

  onEntityClick(callback: EntityClickCallback): void {
    this.onClickCallback = callback;
  }

  highlight(type: EntityType): void {
    this.select(type);
  }

  /**
   * Spec 017 (FR-017) + Bug 1/2 fixes: rebuild the button list from the
   * multi-entity map. Two critical fixes vs the first implementation:
   *
   *  1. REBUILD ONLY ON CHANGE: we string-compare the sorted uid set and
   *     skip the DOM rebuild when it's identical to last frame. Rebuilding
   *     every frame (60Hz) tore down click handlers before clicks could
   *     fire — that was Bug 1.
   *  2. UID IN LABEL: each button shows the entity's uid alongside its
   *     name so the user can tell "uav_alpha (20001)" from "uav_bravo
   *     (20002)" — that was Bug 2.
   */
  updateFromEntities(entities: Record<string, EntityState>): void {
    const entries = Object.entries(entities);
    // Spec 024: 空实体(关闭仿真 reset)→ 清空列表。原来直接 return 导致
    // reset 后旧实体残留;现仅在有旧实体时清空(无则跳过,保持每帧性能)。
    if (entries.length === 0) {
      if (this.knownUids !== '' && this.listEl) {
        this.listEl.innerHTML = '';
        this.multiButtons.clear();
        this.knownUids = '';
        this.multiSelectedUid = null;
      }
      return;
    }

    // Stable signature of the current entity set — rebuild only on change.
    const uids = entries.map(([k]) => k).sort().join(',');
    if (uids === this.knownUids && this.listEl) return;
    this.knownUids = uids;

    // .entity-list is provided by index.html (render() cached it). Clear
    // children but keep the element so scroll position persists across updates.
    if (!this.listEl) return;
    this.listEl.innerHTML = '';
    this.multiButtons.clear();

    for (const [uid, entity] of entries) {
      // Spec 020 T6: resolve dot/label/control category from the registry.
      const desc = describeEntityKind(entity.kind);
      const btn = document.createElement('button');
      btn.className = 'entity-btn';
      btn.dataset.entityId = uid;

      // Bug 2: include the uid so the user can distinguish entities.
      btn.innerHTML = `<span class="entity-dot ${desc.dotClass}"></span>` +
        ` <strong>${desc.labelPrefix}</strong> ${entity.name}` +
        ` <span style="opacity:0.6;font-size:0.85em">(${uid})</span>`;

      btn.addEventListener('click', () => {
        this.highlightByEntityId(uid);
        this.onClickCallback?.(desc.entityType, uid);
      });
      this.listEl!.appendChild(btn);
      this.multiButtons.set(uid, { el: btn, uid, entityType: desc.entityType });
    }
    this.multiSelectedUid = null;
  }

  private highlightByEntityId(uid: string): void {
    if (this.multiSelectedUid) {
      const prev = this.multiButtons.get(this.multiSelectedUid);
      prev?.el.classList.remove('selected');
    }
    const entry = this.multiButtons.get(uid);
    if (entry) {
      entry.el.classList.add('selected');
      this.multiSelectedUid = uid;
    }
  }
}
