// 通用 HUD 面板行为：整体折叠 + 位置拖拽（Spec 023）。
//
// 每个面板统一结构：.hud-panel[data-hud-panel] > .hud-panel__header + .hud-panel__body。
// - 折叠：点 header → toggle .is-collapsed（CSS 隐藏 body、chevron 旋转、面板塌缩）。
// - 拖拽：按住 header 移动 → 改 left/top（清 right/bottom，clamp 到视口）。
// - 用 5px 阈值区分「点击折叠」与「拖拽移动」，避免冲突（复用 camera-pip 模式）。

/** 移动距离小于此值视为点击（折叠），否则视为拖拽。 */
const DRAG_THRESHOLD = 5;

export interface HudPanelOptions {
  /** 允许拖动面板（改 left/top）。默认 true。 */
  draggable?: boolean;
  /** 初始即为折叠态。 */
  defaultCollapsed?: boolean;
}

interface DragState {
  x: number;
  y: number;
  offX: number;
  offY: number;
}

/**
 * 装配一个 HUD 面板的折叠+拖拽行为。在 app 启动时对每个 [data-hud-panel] 调用。
 * 事件委托/折叠记忆等面板内部逻辑不受影响 —— 本函数只管 header 的折叠与拖拽。
 */
export function initHudPanel(panel: HTMLElement, opts: HudPanelOptions = {}): void {
  const header = panel.querySelector<HTMLElement>('.hud-panel__header');
  if (!header) return;

  const draggable = opts.draggable !== false;

  if (opts.defaultCollapsed) panel.classList.add('is-collapsed');

  let drag: DragState | null = null;
  let moved = false;

  header.addEventListener('mousedown', (e) => {
    if (e.button !== 0) return;
    const rect = panel.getBoundingClientRect();
    drag = { x: e.clientX, y: e.clientY, offX: e.clientX - rect.left, offY: e.clientY - rect.top };
    moved = false;
    if (draggable) e.preventDefault(); // 防止选中文本/拖出图像
  });

  document.addEventListener('mousemove', (e) => {
    if (!drag || !draggable) return;
    const dist = Math.hypot(e.clientX - drag.x, e.clientY - drag.y);
    if (!moved && dist < DRAG_THRESHOLD) return;
    if (!moved) {
      moved = true;
      panel.classList.add('dragging');
    }
    const maxX = Math.max(0, window.innerWidth - panel.offsetWidth);
    const maxY = Math.max(0, window.innerHeight - panel.offsetHeight);
    panel.style.right = 'auto';
    panel.style.bottom = 'auto';
    panel.style.left = `${Math.max(0, Math.min(maxX, e.clientX - drag.offX))}px`;
    panel.style.top = `${Math.max(0, Math.min(maxY, e.clientY - drag.offY))}px`;
  });

  const endDrag = (): void => {
    if (!drag) return;
    drag = null;
    if (moved) panel.classList.remove('dragging');
  };
  document.addEventListener('mouseup', endDrag);
  document.addEventListener('mouseleave', endDrag);

  // 折叠：header click 且本次未拖拽 → toggle。拖拽产生的 click 因 moved=true 被忽略。
  header.addEventListener('click', () => {
    if (moved) {
      moved = false;
      return;
    }
    panel.classList.toggle('is-collapsed');
  });
}
