//
// Spec 020 T7: sim:state frame normaliser, extracted verbatim from
// redis-client.ts. The redis client used to carry ~175 lines of frame
// parsing (component-organised → flat SimulationState) inline; that
// parsing has nothing to do with the WebSocket transport, so it lives
// here now. redis-client.ts re-exports normalizeSimState for backwards
// compatibility with the Spec 017 multi-entity + Spec 019 zones-state
// contract tests that import it from there.
//
// T8 wires this into JSON-Schema validation (config/schema/) before the
// normaliser runs, so the manual guards below become a defence-in-depth
// backstop rather than the sole correctness check.
import { SimulationState } from './state-manager';
import {
  UAVState, GimbalState, TargetState, EntityState, ExtendedDetection,
  CommState,
} from './wgs84-projection';
import { resolveEntityKind } from './entity-kind-registry';

// Spec 020 T6: top-level keys in a sim:state frame that are NOT entities.
// Shared by extractFlatFields (flat-slot population) and extractAllEntities
// (multi-entity map). Centralised so adding a new metadata key is one edit.
const NON_ENTITY_KEYS = new Set([
  'timestamp', 'status', 'sim_time', 'sim_time_str', 'step_perf', 'reason',
]);

function getEntity(raw: Record<string, unknown>, keyOrId: string): Record<string, unknown> | undefined {
  const e = raw[keyOrId];
  if (typeof e === 'object' && e !== null) return e as Record<string, unknown>;
  return undefined;
}

function getPos(e: Record<string, unknown>): Record<string, unknown> {
  const p = e['platform'];
  if (typeof p === 'object' && p !== null) {
    const pos = (p as Record<string, unknown>)['position'];
    if (typeof pos === 'object' && pos !== null) return pos as Record<string, unknown>;
  }
  return {};
}

function getAtt(e: Record<string, unknown>): Record<string, unknown> {
  const p = e['platform'];
  if (typeof p === 'object' && p !== null) {
    const att = (p as Record<string, unknown>)['attitude'];
    if (typeof att === 'object' && att !== null) return att as Record<string, unknown>;
  }
  return {};
}

function getKin(e: Record<string, unknown>): Record<string, unknown> {
  const k = e['kinematics'];
  if (typeof k === 'object' && k !== null) return k as Record<string, unknown>;
  return {};
}

function getGimbal(e: Record<string, unknown>): Record<string, unknown> {
  const g = e['gimbal_tracking'];
  if (typeof g === 'object' && g !== null) return g as Record<string, unknown>;
  return {};
}

function getTraj(e: Record<string, unknown>): Record<string, unknown> {
  const t = e['trajectory'];
  if (typeof t === 'object' && t !== null) return t as Record<string, unknown>;
  return {};
}

// Spec 020 T6: `extractFlatFields` derives the legacy single-uav/target/gimbal
// slots from the first matching entity in the frame. These flat slots are
// still part of the SimulationState contract (consumed by the navigation-path
// terrain clamp and by the replan handler) and are covered by the
// "legacy single-uav fields remain populated" test, so they stay — but they
// are no longer used for single-entity rendering (the render path is the
// multi-entity map exclusively).

/**
 * Scan the frame for the first UAV + first ground_vehicle entity objects
 * and return them keyed by 'uav' / 'target'. Used to populate the flat
 * SimulationState slots from the component-organised frame.
 */
function extractFlatFields(raw: Record<string, unknown>, entityIds: Record<string, string>): {
  uav: Record<string, unknown>;
  target: Record<string, unknown>;
} {
  const result: { uav: Record<string, unknown>; target: Record<string, unknown> } = {
    uav: {},
    target: {},
  };

  // Look up by configured ID first
  for (const [name, id] of Object.entries(entityIds)) {
    const e = getEntity(raw, id);
    if (e) {
      result[name as 'uav' | 'target'] = e;
    }
  }

  // Fallback: scan top-level keys for the first entity-like object of each kind
  const uavEmpty = Object.keys(result.uav).length === 0;
  const targetEmpty = Object.keys(result.target).length === 0;
  if (!uavEmpty && !targetEmpty) return result;

  for (const key of Object.keys(raw)) {
    if (NON_ENTITY_KEYS.has(key)) continue;
    const e = getEntity(raw, key);
    if (!e) continue;
    const typeStr = String(e['type'] ?? '');
    if (uavEmpty && (typeStr === 'uav' || typeStr === 'fixed_wing_uav')) {
      result.uav = e;
    } else if (targetEmpty && typeStr === 'ground_vehicle') {
      result.target = e;
    }
  }

  return result;
}

// Spec 017: exported for unit testing of multi-entity extraction.
export function normalizeSimState(message: unknown, entityIds?: Record<string, string>): SimulationState | null {
  if (typeof message !== 'object' || message === null) return null;
  const raw = message as Record<string, unknown>;

  if (typeof raw.timestamp !== 'number') return null;
  const status = String(raw.status ?? '');
  if (!['running', 'paused', 'ended', 'idle'].includes(status)) return null;

  const eids = entityIds ?? {};
  const entities = extractFlatFields(raw, eids);

  // Spec 019 (T077 / FR-016): extract sim:state["zones"] bucket for the
  // 3D visualizer.  The bucket is published by ThreatArbiter and
  // contains {air_defense: [...], comm_jam_static: [...],
  // comm_jam_random: [...]}.  Carried in `state.zones` and consumed by
  // KillZoneOverlay / JamZoneOverlay.
  const zonesRaw = raw['zones'];
  const zones = (typeof zonesRaw === 'object' && zonesRaw !== null)
    ? (zonesRaw as Record<string, unknown>)
    : undefined;

  // Build flatten UAV state
  const uavPos = getPos(entities.uav);
  const uavAtt = getAtt(entities.uav);
  const uavKin = getKin(entities.uav);
  const uav: UAVState = {
    latitude: Number(uavPos['latitude'] ?? 0),
    longitude: Number(uavPos['longitude'] ?? 0),
    altitude: Number(uavPos['altitude'] ?? 0),
    roll: Number(uavAtt['roll'] ?? 0),
    pitch: Number(uavAtt['pitch'] ?? 0),
    yaw: Number(uavAtt['yaw'] ?? 0),
    velocity: Number(uavKin['velocity'] ?? 0),
  };

  // Build flatten Target state
  const tgtPos = getPos(entities.target);
  const tgtTraj = getTraj(entities.target);
  const target: TargetState = {
    latitude: Number(tgtPos['latitude'] ?? 0),
    longitude: Number(tgtPos['longitude'] ?? 0),
    altitude: Number(tgtPos['altitude'] ?? 0),
    speed: Number(tgtTraj['speed'] ?? entities.target['speed'] ?? 0),
    heading: Number(entities.target['heading'] ?? 0),
  };

  // Build flatten Gimbal state (from UAV's gimbal_tracking component)
  const uavGimbal = getGimbal(entities.uav);
  const gimbal: GimbalState = {
    pan_angle: Number(uavGimbal['pan_angle'] ?? 0),
    tilt_angle: Number(uavGimbal['tilt_angle'] ?? 0),
    track_enabled: Boolean(uavGimbal['track_enabled'] ?? false),
    fov: Number(uavGimbal['fov'] ?? 70),
  };

  // Validate required fields
  if (!isFinite(uav.latitude) || uav.latitude < -90 || uav.latitude > 90) return null;
  if (!isFinite(uav.longitude) || uav.longitude < -180 || uav.longitude > 180) return null;
  if (!isFinite(target.latitude)) return null;
  if (!isFinite(target.longitude)) return null;

  // Spec 017 (FR-017): build the full multi-entity map.
  const multiEntities = extractAllEntities(raw);

  return {
    timestamp: raw.timestamp as number,
    status: status as SimulationState['status'],
    uav,
    gimbal,
    target,
    path: { waypoints: [] },
    entities: multiEntities,
    // Spec 019: pass-through the published zones bucket.
    zones,
  };
}

// Spec 017 (FR-017/V-1): extract ALL entities from the sim:state frame,
// keyed by unique_id. This is the multi-entity view the visualization
// uses to render all UAVs + vehicles. Kind recognition goes through the
// EntityKindRegistry (Spec 020 T6) so adding a kind is one registry edit.
export function extractAllEntities(raw: Record<string, unknown>): Record<string, EntityState> {
  const out: Record<string, EntityState> = {};
  for (const key of Object.keys(raw)) {
    if (NON_ENTITY_KEYS.has(key)) continue;
    const e = getEntity(raw, key);
    if (!e) continue;
    const kind = resolveEntityKind(String(e['type'] ?? ''));
    if (kind === null) continue;

    const name = String(e['name'] ?? key);
    if (kind === 'uav') {
      const pos = getPos(e);
      const att = getAtt(e);
      const kin = getKin(e);
      const g = getGimbal(e);
      const detRaw = (g['detection'] ?? {}) as Record<string, unknown>;
      const detPos = detRaw['target_position'] as Record<string, unknown> | undefined;
      const detection: ExtendedDetection = {
        detected: Boolean(detRaw['detected'] ?? false),
        confidence: Number(detRaw['confidence'] ?? 0),
        target_position: detPos ? {
          latitude: Number(detPos['latitude'] ?? 0),
          longitude: Number(detPos['longitude'] ?? 0),
          altitude: Number(detPos['altitude'] ?? 0),
        } : undefined,
        azimuth_error: typeof detRaw['azimuth_error'] === 'number'
          ? Number(detRaw['azimuth_error']) : undefined,
        target_type: String(detRaw['target_type'] ?? ''),
        misid_flag: Boolean(detRaw['misid_flag'] ?? false),
        misid_count: Number(detRaw['misid_count'] ?? 0),
        misid_track_duration: Number(detRaw['misid_track_duration'] ?? 0),
      };
      const commRaw = (e['comm'] ?? null) as Record<string, unknown> | null;
      let comm: CommState | undefined;
      if (commRaw) {
        const stats = (commRaw['stats'] ?? {}) as Record<string, unknown>;
        comm = {
          enabled: Boolean(commRaw['enabled'] ?? false),
          range_m: Number(commRaw['range_m'] ?? 1000),
          max_bytes: Number(commRaw['max_bytes'] ?? 50),
          max_rate_hz: Number(commRaw['max_rate_hz'] ?? 4),
          inbox: ((commRaw['inbox'] ?? []) as Record<string, unknown>[]).map(m => ({
            sender: String(m['sender'] ?? ''),
            payload: String(m['payload'] ?? ''),
            recv_time: Number(m['recv_time'] ?? 0),
          })),
          stats: {
            sent: Number(stats['sent'] ?? 0),
            delivered: Number(stats['delivered'] ?? 0),
            received: Number(stats['received'] ?? 0),
            rejected_bytes: Number(stats['rejected_bytes'] ?? 0),
            rejected_rate: Number(stats['rejected_rate'] ?? 0),
            rejected_range: Number(stats['rejected_range'] ?? 0),
            rejected_jam: Number(stats['rejected_jam'] ?? 0),
          },
        };
      }
      out[key] = {
        uid: key, kind, name,
        uav: {
          latitude: Number(pos['latitude'] ?? 0),
          longitude: Number(pos['longitude'] ?? 0),
          altitude: Number(pos['altitude'] ?? 0),
          roll: Number(att['roll'] ?? 0),
          pitch: Number(att['pitch'] ?? 0),
          yaw: Number(att['yaw'] ?? 0),
          velocity: Number(kin['velocity'] ?? 0),
        },
        gimbal: {
          pan_angle: Number(g['pan_angle'] ?? 0),
          tilt_angle: Number(g['tilt_angle'] ?? 0),
          track_enabled: Boolean(g['track_enabled'] ?? false),
          fov: Number(g['fov'] ?? 70),
        },
        detection, comm,
      };
    } else {
      // ground_vehicle or decoy_vehicle
      const pos = getPos(e);
      const traj = getTraj(e);
      out[key] = {
        uid: key, kind, name,
        vehicle: {
          latitude: Number(pos['latitude'] ?? 0),
          longitude: Number(pos['longitude'] ?? 0),
          altitude: Number(pos['altitude'] ?? 0),
          speed: Number(traj['speed'] ?? e['speed'] ?? 0),
          heading: Number(e['heading'] ?? 0),
        },
      };
    }
  }
  return out;
}
