import * as THREE from 'three';
import { GimbalState } from '../core/wgs84-projection';

/**
 * Gimbal direction ray + FOV cone.
 *
 * Direction ray: a thin line from the UAV along the gimbal boresight,
 * sized so its tip lands on the terrain:
 *
 *     L_ray = altitudeAboveGround / sin(|tilt|)
 *
 * (tilt is the depression angle from horizontal; at -90 deg the ray points
 * straight down and L_ray == altitudeAboveGround; at shallow tilts it grows
 * but is capped so it doesn't shoot past the horizon). This fixes the
 * original bug where the ray had a fixed 330-unit length and stopped in
 * mid-air when a UAV flew high.
 *
 * FOV cone: a standard right cone along the boresight, sized so its NEAR
 * rim — the base edge pointing most steeply at the ground — sits on the
 * terrain:
 *
 *     L_cone = agl * cos(fov/2) / sin(|tilt| + fov/2)
 *
 * The cone's radius is tan(fov/2) * L_cone, so its true 3D half-angle
 * stays exactly fov/2 — it remains an honest FOV indicator at every tilt.
 *
 * Why the near rim and not the far rim: a tilted cone's circular base
 * cannot have both its near edge (toward nadir) and far edge (toward
 * horizon) on a flat ground at once (only at |tilt| = 90 deg do they
 * coincide). Sizing for the FAR rim — the previous behaviour,
 * L_old = agl*cos(fov/2)/sin(|tilt|-fov/2) — drove the cone far past the
 * aim point and pushed the near rim deep underground at shallow gimbal
 * angles, so the cone appeared to shoot through the terrain instead of
 * lying on it. Sizing for the near rim puts the cone's footprint on the
 * ground (near rim at the terrain, far rim trailing slightly above it),
 * which reads as a cone lying on the surface — no ground penetration.
 * The terrain mesh being opaque further hides any incidental overlap.
 *
 * Geometry note: the indicator is attached as a child of the UAV model and
 * lives in the UAV body frame where local -Z is "forward" (nose). The model
 * group is rotated by pan (Y) then tilt (X) so local -Z points along the
 * gimbal boresight. WGS84Projection maps 1 metre of altitude to 1 Three.js
 * unit (Y), so the altitude delta in metres is directly the ray length in
 * world units when looking straight down.
 */
export class GimbalIndicator {
  private model: THREE.Group;
  private directionLine: THREE.Line;
  private fovCone: THREE.Mesh;

  // Caps so a near-horizontal tilt doesn't produce an absurd ray.
  private static readonly kMinTiltDeg = 5.0;
  private static readonly kMaxRayM = 5000.0;
  private static readonly kMinRayM = 1.0;

  constructor() {
    this.model = new THREE.Group();
    this.model.rotation.order = 'YXZ'; // tilt (X) applied after pan (Y)

    // Unit-length direction line along local -Z (0 → -1). Scaled on Z each
    // update so its tip lands on the ground — no per-frame geometry rebuild.
    const lineGeometry = new THREE.BufferGeometry();
    lineGeometry.setFromPoints([
      new THREE.Vector3(0, 0, 0),
      new THREE.Vector3(0, 0, -1),
    ]);
    const lineMaterial = new THREE.LineBasicMaterial({
      color: 0xffff00, linewidth: 1,
    });
    this.directionLine = new THREE.Line(lineGeometry, lineMaterial);
    this.model.add(this.directionLine);

    // Unit FOV cone (tip at origin, opens forward along -Z after the
    // rotation.x = PI/2 axis remap). Scaled on all axes each update.
    const coneGeometry = new THREE.ConeGeometry(1, 1, 24, 1, true);
    const coneMaterial = new THREE.MeshBasicMaterial({
      color: 0xffff00,
      transparent: true,
      opacity: 0.25,
      side: THREE.DoubleSide,
      depthWrite: false,
    });
    this.fovCone = new THREE.Mesh(coneGeometry, coneMaterial);
    this.fovCone.rotation.x = Math.PI / 2;  // cone axis +Y → -Z
    this.fovCone.visible = false;
    this.model.add(this.fovCone);
  }

  /**
   * @param gimbalState  pan/tilt/fov from the kernel.
   * @param uavAltitudeM the UAV's current altitude (metres).
   * @param groundAltitudeM  terrain elevation under the UAV (metres). 0
   *        when no heightmap is loaded — in that case the ray falls back
   *        to a length proportional to the UAV altitude.
   */
  update(gimbalState: GimbalState,
          uavAltitudeM: number = 0,
          groundAltitudeM: number = 0): void {
    // Relative rotation in UAV body frame. tilt: +up/-down (NED); pan:
    // +right. Three.js rotation.y is CCW from above, so negate pan.
    this.model.rotation.x = THREE.MathUtils.degToRad(gimbalState.tilt_angle);
    this.model.rotation.y = THREE.MathUtils.degToRad(-gimbalState.pan_angle);

    // Altitude above the terrain in metres (== Three.js world units).
    const agl = Math.max(GimbalIndicator.kMinRayM,
                          uavAltitudeM - groundAltitudeM);
    // Slant length so the boresight tip lands on the ground given the
    // depression angle. Clamp |tilt| to a small floor so a level gimbal
    // doesn't divide by ~0.
    const tiltAbs = Math.max(GimbalIndicator.kMinTiltDeg,
                              Math.abs(gimbalState.tilt_angle));
    let slantLen = agl / Math.sin(THREE.MathUtils.degToRad(tiltAbs));
    if (!isFinite(slantLen) || slantLen <= 0) {
      slantLen = agl;
    }
    slantLen = Math.min(slantLen, GimbalIndicator.kMaxRayM);

    // Direction line: the boresight centre ray, tip on the ground at the
    // aim point.
    this.directionLine.scale.set(1, 1, slantLen);

    // FOV cone: size so the NEAR rim — the base edge pointing most steeply
    // at the ground (depressed |tilt|+fov/2) — sits on the terrain. This
    // avoids the previous far-rim sizing, which drove the near rim deep
    // underground at shallow tilts (cone shooting through the terrain).
    // Solve for the cone length whose near-rim depth equals -agl:
    //   -(L*sin(tilt) + L*tan(fov/2)*cos(tilt)) = -agl
    //   → L = agl / (sin(tilt) + tan(fov/2)*cos(tilt))
    //        = agl*cos(fov/2) / sin(tilt+fov/2)   (half-angle identity)
    // The near rim is always more steeply depressed than the boresight, so
    // the denominator never approaches 0 for any physical tilt ≥ 0; there
    // is no horizon edge case to cap.
    const fovAngle = gimbalState.fov;
    const halfTan = Math.tan(THREE.MathUtils.degToRad(fovAngle / 2));
    const nearDepression = tiltAbs + fovAngle / 2;   // near-rim depression
    let coneLen = agl * Math.cos(THREE.MathUtils.degToRad(fovAngle / 2))
                       / Math.sin(THREE.MathUtils.degToRad(nearDepression));
    if (!isFinite(coneLen) || coneLen <= 0) coneLen = slantLen;
    coneLen = Math.min(coneLen, GimbalIndicator.kMaxRayM);

    // radius = tan(fov/2) * length keeps the true 3D half-angle at fov/2
    // regardless of the extension.
    this.fovCone.scale.set(
      halfTan * coneLen,
      coneLen,
      halfTan * coneLen,
    );
    // Keep the cone centred along its length so the tip sits at the UAV.
    this.fovCone.position.z = -coneLen / 2;
  }

  setFovVisible(visible: boolean): void {
    this.fovCone.visible = visible;
  }

  getModel(): THREE.Group {
    return this.model;
  }
}
