// 仿真控制 HTTP 客户端。
// 封装 bridge 的 /api/scenarios + /api/sim/* 端点;注入 fetchImpl 便于测试。

/** 算法条目(与 bridge AlgorithmEntry 对齐, 取 UI 需要的字段)。 */
export interface AlgorithmInfo {
  name: string;
  entryClass?: string;
  modulePath?: string;
  agentSpec: string;
  docstring?: string;
  shortName?: string;
  source: 'baseline' | 'user';
  scenarioId?: string;
}

export interface ScenarioInfo {
  id: string;
  name: string;
  label?: string;            // UI 编号前缀, 如 "赛题一"
  order?: number;            // 显示排序
  description: string;
  baselineAgent: string;
  defaultDuration: number;
  scenarioJson: string;
  available: boolean;
  algorithms: AlgorithmInfo[];   // 该赛题的算法清单(baseline + 参赛者)
}

export interface SimStatus {
  status: string;
  scenario: string | null;
  sessionId: string | null;
  error: string | null;
}

export interface SimControlResult {
  ok: boolean;
  httpStatus: number;
  sessionId?: string;
  scenario?: string;
  status?: string;
  error?: string;
}

export interface SimControlConfig {
  /** bridge HTTP 基址,如 http://host:8081。 */
  baseUrl: string;
  fetchImpl?: typeof fetch;
}

// 感知参数透传（photoMode 三态；undefined → body 写 'auto'，带 UE 环境自动拉相机帧）。
export interface PerceptionOverrides {
  mode?: 'train' | 'eval';
  photoMode?: 'auto' | 'on' | 'off';
  yoloModel?: string;
}

export class SimControlClient {
  private fetchImpl: typeof fetch;

  constructor(private cfg: SimControlConfig) {
    this.fetchImpl = cfg.fetchImpl ?? fetch.bind(globalThis);
  }

  async getScenarios(): Promise<ScenarioInfo[]> {
    const r = await this.fetchImpl(`${this.cfg.baseUrl}/api/scenarios`);
    const body = await r.json();
    return (body.scenarios ?? []) as ScenarioInfo[];
  }

  /** 拉取单个赛题的算法清单(刷新用)。GET /api/algorithms/:scenarioId → {scenarioId, algorithms}。 */
  async getAlgorithms(scenarioId: string): Promise<AlgorithmInfo[]> {
    const r = await this.fetchImpl(`${this.cfg.baseUrl}/api/algorithms/${encodeURIComponent(scenarioId)}`);
    const body = await r.json();
    return (body.algorithms ?? []) as AlgorithmInfo[];
  }

  async start(
    scenario: string,
    agent?: string,
    perception?: PerceptionOverrides,
    routeSeed?: number,
  ): Promise<SimControlResult> {
    const body: Record<string, string | boolean | number> = { scenario };
    if (agent) body.agent = agent;
    // 感知参数写入：photoMode 三态（默认 auto），mode/yoloModel 有效值才进 body。
    if (perception?.mode) body.mode = perception.mode;
    body.photoMode = perception?.photoMode ?? 'auto';
    if (perception?.yoloModel) body.yoloModel = perception.yoloModel;
    // 路线种子(generate 产生): 正整数才透传,后端按 seed%30 选路线。
    if (typeof routeSeed === 'number' && Number.isFinite(routeSeed) && routeSeed > 0) {
      body.routeSeed = Math.floor(routeSeed);
    }
    return this.post('/api/sim/start', body);
  }

  async pause(): Promise<SimControlResult> {
    return this.post('/api/sim/pause', {});
  }

  async resume(): Promise<SimControlResult> {
    return this.post('/api/sim/resume', {});
  }

  async stop(): Promise<SimControlResult> {
    return this.post('/api/sim/stop', {});
  }

  /** 写回指定赛题想定文件的 weather 字段(就地改 scenario.json)。 */
  async setWeather(scenario: string, weather: string): Promise<SimControlResult> {
    return this.post('/api/scenario/weather', { scenario, weather });
  }

  async getStatus(): Promise<SimStatus> {
    const r = await this.fetchImpl(`${this.cfg.baseUrl}/api/sim/status`);
    return r.json();
  }

  private async post(path: string, body: unknown): Promise<SimControlResult> {
    const r = await this.fetchImpl(`${this.cfg.baseUrl}${path}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });
    let data: Record<string, unknown> = {};
    try { data = await r.json(); } catch { /* 非 JSON 响应 */ }
    return {
      ok: Boolean(data.ok),
      httpStatus: r.status,
      sessionId: data.sessionId as string | undefined,
      scenario: data.scenario as string | undefined,
      status: data.status as string | undefined,
      error: data.error as string | undefined,
    };
  }
}
