//
// Spec 017 (FR-016): DecoyVehicle renderer. The shared geometry +
// lifecycle lives in VehicleModelBase (Spec 020 T7); this subclass pins
// the palette + label to the amber "DECOY" identity and enables the
// diagonal roof stripe marker. Rendered output is byte-equivalent to
// the pre-refactor DecoyModelRenderer.
//
// Visually distinct from the real TargetVehicle:
//   - Body colour: amber/yellow (0xffc107) vs red (0xf44336)
//   - Label: "DECOY" vs "TARGET"
//   - Roof: deeper amber (0xffa000) + diagonal black stripe
// Red-vs-yellow is distinguishable for protanopia/deuteranopia.
import { WGS84Projection } from '../core/wgs84-projection';
import { VehicleModelBase, DECOY_VEHICLE_CONFIG } from './vehicle-model-base';

export class DecoyModelRenderer extends VehicleModelBase {
  constructor(projection: WGS84Projection) {
    super(projection, DECOY_VEHICLE_CONFIG);
  }
}
