// 022 — 相机帧 WebSocket 拉流客户端(替代 HTTP CameraFrameClient)。
//
// 背景:HTTP 拉取模式下,30Hz × N 路 fetch 会打满浏览器连接池,偶发 700ms+
// 长尾尖刺 → inFlight 锁死 → 该路画面停顿。WS 推送模式下,一条长连接复用
// 所有 uid,bridge 主动推帧,无连接池问题。
//
// 协议(与 camera-ws-server.ts 对应):
//   text(JSON) 控制消息:{type:'subscribe'|'unsubscribe', uids:['10002']}
//   binary 帧消息:[16字节 header][uid][PNG]
//     header: frame_no(u32 LE) + sim_time(f64 LE) + uid_len(u16 LE) + reserved(u16)
//
// 设计:所有 uid 共享一条 WS 连接(CameraPip 持有一个实例,open(uid) 调
// subscribe,close(uid) 调 unsubscribe)。按 uid 维护去重游标(displayedFrameNo)。

/** 一帧解码结果(传给 onFrame 回调)。 */
export interface CameraFrame {
  frameNo: number;
  simTime: number;
  blob: Blob;
}

/** 去重/追帧决策(与 camera-frame-client 保持一致语义)。 */
export function shouldDisplayFrame(incomingFrameNo: number, displayedFrameNo: number): boolean {
  return incomingFrameNo > displayedFrameNo;
}

/** 固定 header 长度(字节),与 server 端 HEADER_LEN 一致。 */
const HEADER_LEN = 16;

export interface CameraStreamClientOptions {
  /** WS server URL,如 ws://host:8082。 */
  wsUrl: string;
  /** 收到某 uid 的新帧时回调(已去重)。 */
  onFrame: (uid: string, frame: CameraFrame) => void;
  /** 注入 WebSocket 构造器(测试用)。 */
  WebSocketImpl?: typeof WebSocket;
  /** 日志(默认 console.log)。 */
  log?: (msg: string) => void;
}

export class CameraStreamClient {
  private readonly wsUrl: string;
  private readonly onFrame: (uid: string, frame: CameraFrame) => void;
  private readonly WebSocketCtor: typeof WebSocket;
  private readonly log: (msg: string) => void;

  private ws: WebSocket | null = null;
  private connecting = false;
  /** 已 subscribe 的 uid 集合(重连后重新订阅)。 */
  private subscribedUids = new Set<string>();
  /** uid → 已显示的最大 frame_no(去重)。 */
  private displayedFrameNo = new Map<string, number>();
  /** 重连退避(毫秒)。 */
  private reconnectDelay = 500;
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null;
  /** 是否已主动 close(阻止重连)。 */
  private closed = false;

  constructor(opts: CameraStreamClientOptions) {
    this.wsUrl = opts.wsUrl;
    this.onFrame = opts.onFrame;
    this.WebSocketCtor = opts.WebSocketImpl ?? WebSocket;
    this.log = opts.log ?? ((m: string) => console.log(m));
  }

  /** 订阅指定 uid 的帧流(幂等;首次 subscribe 触发懒连接)。 */
  subscribe(uid: string): void {
    const isNew = !this.subscribedUids.has(uid);
    this.subscribedUids.add(uid);
    // displayedFrameNo 不清:重连后仍按已显示帧号去重,避免旧帧重放。
    // 但若 uid 是新订阅,从 -1 开始(显示首帧)。
    if (!this.displayedFrameNo.has(uid)) this.displayedFrameNo.set(uid, -1);
    // 关键修复:WS 已 OPEN 时,新 subscribe 必须立即发送该 uid 的订阅消息。
    // 不能只靠 open 回调批量订阅 —— 那只在首次/重连时触发,后续 open 窗口的
    // subscribe 会因为 WS 已 OPEN 被 ensureConnected 直接跳过,导致该路收不到帧。
    if (isNew && this.ws && this.ws.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify({ type: 'subscribe', uids: [uid] }));
    }
    this.ensureConnected();
  }

  /** 取消订阅指定 uid(发 unsubscribe + 清去重状态)。 */
  unsubscribe(uid: string): void {
    this.subscribedUids.delete(uid);
    this.displayedFrameNo.delete(uid);
    if (this.ws && this.ws.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify({ type: 'unsubscribe', uids: [uid] }));
    }
  }

  /** 关闭连接 + 清状态(不再重连)。 */
  close(): void {
    this.closed = true;
    if (this.reconnectTimer) {
      clearTimeout(this.reconnectTimer);
      this.reconnectTimer = null;
    }
    if (this.ws) {
      try { this.ws.close(); } catch { /* ignore */ }
      this.ws = null;
    }
    this.subscribedUids.clear();
    this.displayedFrameNo.clear();
    this.connecting = false;
  }

  // ── 连接管理 ────────────────────────────────────────────

  /** 确保 WS 已连接(懒连接:首次 subscribe 时建)。 */
  private ensureConnected(): void {
    if (this.closed) return;
    if (this.ws && (this.ws.readyState === WebSocket.OPEN || this.ws.readyState === WebSocket.CONNECTING)) {
      return;
    }
    if (this.connecting) return;
    this.connecting = true;
    this.log(`[CamStream] connecting ${this.wsUrl}`);
    let ws: WebSocket;
    try {
      ws = new this.WebSocketCtor(this.wsUrl);
      // 关键:WS 默认接收 binary 为 Blob,改成 ArrayBuffer 便于 DataView 解析。
      ws.binaryType = 'arraybuffer';
    } catch (e) {
      this.connecting = false;
      this.log(`[CamStream] connect error: ${(e as Error).message}`);
      this.scheduleReconnect();
      return;
    }
    this.ws = ws;

    ws.addEventListener('open', () => {
      this.connecting = false;
      this.reconnectDelay = 500; // 重置退避
      this.log(`[CamStream] connected, subscribing ${this.subscribedUids.size} uid(s)`);
      // 重连/首次连接后重新订阅所有 uid。
      if (this.subscribedUids.size > 0) {
        ws.send(JSON.stringify({ type: 'subscribe', uids: Array.from(this.subscribedUids) }));
      }
    });

    ws.addEventListener('message', (event: MessageEvent) => {
      if (typeof event.data === 'string') {
        // 控制消息(ack/error),目前只 debug 打日志。
        this.log(`[CamStream] control: ${event.data}`);
        return;
      }
      // binary frame: ArrayBuffer。
      this.handleBinary(event.data as ArrayBuffer);
    });

    ws.addEventListener('close', () => {
      this.connecting = false;
      this.ws = null;
      if (this.closed) return;
      this.log(`[CamStream] disconnected, will reconnect`);
      this.scheduleReconnect();
    });

    ws.addEventListener('error', (e: Event) => {
      this.log(`[CamStream] ws error: ${(e as ErrorEvent).message ?? 'unknown'}`);
      // close 事件会随之触发,重连在 close handler 里调度。
    });
  }

  /** 解析 binary 帧消息:读 header → 提取 uid/frameNo/simTime → 去重 → onFrame。 */
  private handleBinary(buf: ArrayBuffer): void {
    if (buf.byteLength < HEADER_LEN) return; // 不完整,丢弃
    const view = new DataView(buf);
    const frameNo = view.getUint32(0, true);     // LE
    const simTime = view.getFloat64(4, true);     // LE
    const uidLen = view.getUint16(12, true);      // LE
    if (buf.byteLength < HEADER_LEN + uidLen) return;
    const uidBytes = new Uint8Array(buf, HEADER_LEN, uidLen);
    const uid = new TextDecoder().decode(uidBytes);
    const imgStart = HEADER_LEN + uidLen;
    const imgBytes = new Uint8Array(buf, imgStart, buf.byteLength - imgStart);

    const displayed = this.displayedFrameNo.get(uid) ?? -1;
    if (!shouldDisplayFrame(frameNo, displayed)) return; // 去重/防回退
    this.displayedFrameNo.set(uid, frameNo);

    // Blob 持有 imgBytes 的副本(createImageBitmap 异步解码后 Blob 可回收)。
    // format 字段(header 偏移14):0=PNG 1=JPEG;createImageBitmap 靠 magic 嗅探,
    // blob type 主要影响语义/调试,但写对更严谨。
    const format = view.getUint16(14, true);
    const mime = format === 1 ? 'image/jpeg' : 'image/png';
    const blob = new Blob([imgBytes], { type: mime });
    this.onFrame(uid, { frameNo, simTime, blob });
  }

  /** 指数退避重连(上限 10 秒)。 */
  private scheduleReconnect(): void {
    if (this.closed) return;
    if (this.reconnectTimer) return;
    const delay = this.reconnectDelay;
    this.reconnectDelay = Math.min(this.reconnectDelay * 2, 10000);
    this.log(`[CamStream] reconnect in ${delay}ms`);
    this.reconnectTimer = setTimeout(() => {
      this.reconnectTimer = null;
      this.ensureConnected();
    }, delay);
  }
}
