import {
  Waypoint,
  SimulationState
} from './wgs84-projection';

export interface PathState {
  waypoints: Waypoint[];
  total_distance: number;
}

export type StateSubscriber = (state: SimulationState) => void;

export type { SimulationState }; 

export class StateManager {
  private state: SimulationState;
  private subscribers: StateSubscriber[] = [];

  constructor() {
    this.state = this.createDefaultState();
  }

  private createDefaultState(): SimulationState {
    return {
      timestamp: 0,
      status: 'idle',
      uav: {
        latitude: 0,
        longitude: 0,
        altitude: 0,
        roll: 0,
        pitch: 0,
        yaw: 0,
        velocity: 0
      },
      gimbal: {
        pan_angle: 0,
        tilt_angle: 0,
        track_enabled: false,
        fov: 70
      },
      target: {
        latitude: 0,
        longitude: 0,
        altitude: 0,
        speed: 0,
        heading: 0
      },
      path: {
        waypoints: []
      }
    };
  }

  updateState(message: Partial<SimulationState>): void {
    if (message.timestamp !== undefined) {
      this.state.timestamp = message.timestamp;
    }
    if (message.status !== undefined) {
      this.state.status = message.status;
    }
    if (message.uav !== undefined) {
      this.state.uav = { ...this.state.uav, ...message.uav };
    }
    if (message.gimbal !== undefined) {
      this.state.gimbal = { ...this.state.gimbal, ...message.gimbal };
    }
    if (message.target !== undefined) {
      this.state.target = { ...this.state.target, ...message.target };
    }
    if (message.path !== undefined) {
      this.state.path = { ...this.state.path, ...message.path };
    }
    // Spec 017 (FR-017): pass through the multi-entity map verbatim
    // (replaced each tick, not merged).
    if (message.entities !== undefined) {
      this.state.entities = message.entities;
    }
    // Spec 019 (FR-016): pass through the published zones bucket verbatim.
    if (message.zones !== undefined) {
      this.state.zones = message.zones;
    }

    this.notifySubscribers();
  }

  getState(): SimulationState {
    return { ...this.state };
  }

  /** Spec 024: 重置为默认状态(关闭仿真时清空所有面板)。
   *  entities 显式设为 {} 以触发 onStateUpdate 的实体清空分支
   *  (entityManager/entityListPanel/commLinkRenderer/selection.reconcile/syncCameraPip);
   *  zones 留 undefined → ZoneController 收到空 bucket → 清威胁区。 */
  reset(): void {
    this.state = this.createDefaultState();
    this.state.entities = {};
    this.notifySubscribers();
  }

  subscribe(callback: StateSubscriber): () => void {
    this.subscribers.push(callback);

    return () => {
      const index = this.subscribers.indexOf(callback);
      if (index > -1) {
        this.subscribers.splice(index, 1);
      }
    };
  }

  private notifySubscribers(): void {
    const state = this.getState();
    for (const subscriber of this.subscribers) {
      try {
        subscriber(state);
      } catch (error) {
        console.error('Error in state subscriber:', error);
      }
    }
  }
}