//
// Spec 020 T7: ZoneController — extracted from app.ts. Owns the
// threat-zone overlays (KillZoneOverlay + JamZoneOverlay) and the
// KillEventFX, plus the active→destroyed transition detection that drives
// the kill burst. This was onSpec019ZonesUpdate() in app.ts.
//
// The reference (lat, lon) used to project zone polygons into the Three.js
// scene **must** match the App-level WGS84Projection reference (the same
// one used to render terrain, UAVs, vehicles and trails). Using a
// per-run reference (e.g. "first UAV seen") mis-projects the polygon by
// up to ~1500 m in lon for this scenario, making the visualised bounding
// box appear offset from where the backend actually destroys UAVs.
// Callers are responsible for passing the App's WGS84Projection origin
// via the constructor.
import { KillZoneOverlay, AirDefenseZone } from '../rendering/kill-zone-overlay';
import { JamZoneOverlay, JamZone } from '../rendering/jam-zone-overlay';
import { KillEventFX } from '../rendering/kill-event.fx';
import { SimulationState } from './state-manager';
import * as THREE from 'three';

export class ZoneController {
  private killZoneOverlay: KillZoneOverlay;
  private jamZoneOverlay: JamZoneOverlay;
  private killEventFX: KillEventFX;
  private lastEntityStatus: Map<string, string> = new Map();
  private referenceLat: number;
  private referenceLon: number;

  // 性能优化 (对抗蜂群搜索 12 fps 排查):zone overlay 的两类数据有不同的
  // 时变性,放在 60Hz sim:state 路径上每帧重建是无谓的开销。
  //  - air_defense:scenario 级固定,仿真全程只在 polygon 变化时重建。
  //    注意:引擎在 init() 阶段用空 routes 生成一个临时 air_defense(coverage=random
  //    退化),runner 注入 A* 路线后发 regenerate_zones 命令,引擎 deferred 重建
  //    出最终 polygon。两次 polygon 中心可相差 ~1 km。若首次构建后永久锁死,
  //    3D web 会一直显示临时 polygon,而引擎按最终 polygon 击毁 UAV —— 视觉与
  //    实际严重错位(飞机飞进红圈不死、在红圈外被击毁)。故用 polygon 签名做
  //    变更检测,仅在变化时重建(整局通常只变 1 次,性能等同"只构建一次")。
  //  - comm_jam_*:comm_jam_random spawn_interval_s=12 / lifetime_s=25,
  //    1Hz 颗粒度肉眼无感但足以捕获变化。
  // 节流前实测在 adversarial_swarm_search 场景下 fps=12。
  private static readonly JAM_THROTTLE_MS = 1000;
  private lastAirDefenseSig = '';
  // 哨兵用 -Infinity 而非 0:首次 update() 必然满足节流条件
  // (now - (-Infinity) = +Infinity ≥ THROTTLE),避免页面刚加载时
  // performance.now() < THROTTLE 导致第一帧 jam 更新被跳过。
  private lastJamUpdate = Number.NEGATIVE_INFINITY;

  constructor(
    scene: THREE.Scene,
    referenceLat: number,
    referenceLon: number,
  ) {
    this.killZoneOverlay = new KillZoneOverlay(scene);
    this.jamZoneOverlay = new JamZoneOverlay(scene);
    this.killEventFX = new KillEventFX(scene);
    // Pin the projection origin to the App-level WGS84Projection origin
    // so that the polygon overlay aligns with terrain / UAV / vehicle
    // renderers. Using a different reference here would shift the
    // bounding box by tens to thousands of metres relative to the
    // entities that are actually subject to the kill zone.
    this.referenceLat = referenceLat;
    this.referenceLon = referenceLon;
  }

  /** Refresh overlays + trigger kill FX for active→destroyed transitions.
   *  `now` is exposed as an optional second argument so tests can drive a
   *  deterministic clock; in production it defaults to performance.now(). */
  update(state: SimulationState, now: number = performance.now()): void {
    const zonesBucket = (state.zones ?? {}) as Record<string, unknown>;
    const airDefenseRaw = (zonesBucket['air_defense'] ?? []) as AirDefenseZone[];
    const jamStaticRaw = (zonesBucket['comm_jam_static'] ?? []) as JamZone[];
    const jamRandomRaw = (zonesBucket['comm_jam_random'] ?? []) as JamZone[];

    // (1) 杀伤区:scenario 级固定,仅在 polygon 变化时重建。
    //
    // 历史 bug 1: 早期实现无条件在首次 update() 调用时即置位 killZoneBuilt,
    //   当第一帧 sim:state 早于 ThreatArbiter 装配 zones 桶到达时(zones 缺失
    //   或 air_defense=[]),overlay 用空列表构建出 0 个 mesh 然后被永久锁死,
    //   红色击毁区整个仿真都看不见。已修:只在非空时才记签名。
    // 历史 bug 2 (本次修复): killZoneBuilt 只防"首帧空",仍永久锁死在首个
    //   非空 polygon。但引擎 init() 阶段用空 routes 生成临时 air_defense,
    //   runner 注入路线后发 regenerate_zones,引擎重建出最终 polygon —— 两次
    //   polygon 中心相差 ~1 km。改成用 polygon JSON 签名做变更检测:仅在签名
    //   变化时重建。空列表不更新签名(保留 bug 1 的修复:首帧空不锁死)。
    //   干扰区不受影响,它每 tick 都重建(1Hz)。
    if (airDefenseRaw.length > 0) {
      const sig = JSON.stringify(airDefenseRaw);
      if (sig !== this.lastAirDefenseSig) {
        this.killZoneOverlay.update(
          airDefenseRaw, this.referenceLat, this.referenceLon,
        );
        this.lastAirDefenseSig = sig;
      }
    }

    // (2) 通信干扰区:1Hz 节流。comm_jam_random 至少 12s 才有一次变化,
    // 1s 颗粒度对 25s 寿命的 zone 来说视觉无感,但保留 1Hz 心跳以应对
    // 极端情况下后端节奏变化(比如 spawn_interval 调小)。
    if (now - this.lastJamUpdate >= ZoneController.JAM_THROTTLE_MS) {
      this.lastJamUpdate = now;
      this.jamZoneOverlay.update(
        [...jamStaticRaw, ...jamRandomRaw],
        this.referenceLat, this.referenceLon,
      );
    }

    if (state.entities) {
      for (const [uid, ent] of Object.entries(state.entities)) {
        const status = (ent as { status?: string }).status ?? 'unknown';
        const prev = this.lastEntityStatus.get(uid);
        if (prev === 'active' && status === 'destroyed') {
          // NOTE (behaviour-equivalent): the pre-refactor App read
          // `ent.position` here, which is never present on the
          // multi-entity EntityState shape (positions live under
          // uav/vehicle). So this branch was effectively dead code. We
          // preserve that exact read so behaviour is unchanged; a future
          // task can wire the real position for live FX.
          const pos = (ent as { position?: { latitude: number; longitude: number; altitude: number } }).position;
          if (pos) {
            this.killEventFX.trigger(
              uid, pos.latitude, pos.longitude, pos.altitude,
              this.referenceLat, this.referenceLon,
            );
          }
        }
        this.lastEntityStatus.set(uid, status);
      }
    }

    this.killEventFX.tick();
  }

  private findAnyUav(state: SimulationState):
      { position: { latitude: number; longitude: number; altitude: number } } | null {
    if (state.entities) {
      for (const ent of Object.values(state.entities)) {
        const e = ent as { uav?: { latitude: number; longitude: number; altitude: number } };
        if (e.uav) {
          return {
            position: {
              latitude: e.uav.latitude,
              longitude: e.uav.longitude,
              altitude: e.uav.altitude,
            },
          };
        }
      }
    }
    return null;
  }

  /** First-UAV position for camera auto-centering (reused by App). */
  findAnyUavPosition(state: SimulationState):
      { latitude: number; longitude: number; altitude: number } | null {
    return this.findAnyUav(state)?.position ?? null;
  }
}
