//
// Spec 020 T7: JamZoneOverlay is now a thin typed wrapper around the
// parameterised ZoneOverlay (purple comm-jam, fill only — no boundary
// line). The implementation moved to zone-overlay.ts; this file keeps
// the historical class name + JamZone type so existing imports and the
// Spec 019 US6 contract tests keep working unchanged.
import type * as THREE from 'three';
import { ZoneOverlay, ZonePolygon } from './zone-overlay';
import { ZONE_COLORS, ZONE_ALPHA } from './constants';

// Polygon shape published at sim:state.zones.comm_jam_static / comm_jam_random.
export type JamZone = ZonePolygon;

export class JamZoneOverlay extends ZoneOverlay {
  constructor(parent: THREE.Scene) {
    super(parent, {
      color: ZONE_COLORS.jamZone,
      alpha: ZONE_ALPHA.jamZone,
      showBoundary: false,
      name: 'JamZoneOverlay',
      defaultAltMax: 5000,
      label: '通信干扰区',
    });
  }
}
