// 022 US2 — 帧时间戳 ↔ 云台姿态 一致性核验。
//
// 经既有 bridge WS 持续收 sim:state,维护每架 UAV 的
// sim_time → {pan, tilt} 缓冲;给定帧 sim_ts,对齐到最近姿态,
// 供人工/离线核验"画面视角 ↔ 相机指向"一致性。

import type { SimulationState } from '../core/state-manager';

export interface GimbalPose {
  pan: number;
  tilt: number;
}

interface PoseEntry {
  simTime: number;
  pose: GimbalPose;
}

export class CameraConsistency {
  private readonly byUid = new Map<string, PoseEntry[]>();
  private readonly maxEntries: number;

  constructor(maxEntries = 200) {
    this.maxEntries = maxEntries;
  }

  /** 收到一帧 sim:state → 记录各 UAV 的 sim_time → gimbal 姿态。 */
  update(state: SimulationState): void {
    const s = state as unknown as {
      simTime?: number;
      entities?: Record<string, { kind?: string; gimbal?: { pan_angle: number; tilt_angle: number } }>;
    };
    const t = s.simTime;
    if (t == null || !s.entities) return;
    for (const [uid, ent] of Object.entries(s.entities)) {
      if (ent && ent.kind === 'uav' && ent.gimbal) {
        const arr = this.byUid.get(uid) ?? [];
        arr.push({ simTime: t, pose: { pan: ent.gimbal.pan_angle, tilt: ent.gimbal.tilt_angle } });
        while (arr.length > this.maxEntries) arr.shift();
        this.byUid.set(uid, arr);
      }
    }
  }

  /** 对齐:给定帧 sim_ts → 最近 sim_time 的云台姿态;sim_ts 无效或无记录 → null(不可核验)。 */
  alignPose(uid: string, simTs: number): GimbalPose | null {
    const arr = this.byUid.get(uid);
    if (!arr || arr.length === 0 || !Number.isFinite(simTs)) return null;
    const first = arr[0];
    if (!first) return null;
    let best = first;
    let bestD = Math.abs(first.simTime - simTs);
    for (const e of arr) {
      const d = Math.abs(e.simTime - simTs);
      if (d < bestD) {
        bestD = d;
        best = e;
      }
    }
    return best.pose;
  }
}
