import * as THREE from 'three';

export interface WGS84Coord {
  latitude: number;
  longitude: number;
  altitude: number;
}

export interface ENUCoord {
  x: number;
  y: number;
  z: number;
}

export interface UAVState {
  latitude: number;
  longitude: number;
  altitude: number;
  roll: number;
  pitch: number;
  yaw: number;
  velocity: number;
}

export interface GimbalState {
  pan_angle: number;
  tilt_angle: number;
  track_enabled: boolean;
  fov: number;
}

export interface TargetState {
  latitude: number;
  longitude: number;
  altitude: number;
  heading: number;
  speed: number;
}

export interface Waypoint {
  latitude: number;
  longitude: number;
  altitude: number;
}

export interface NavigationPathState {
  waypoints: Waypoint[];
}

export type SimulationStatus = 'running' | 'paused' | 'ended' | 'idle';

export interface SimulationState {
  timestamp: number;
  status: SimulationStatus;
  uav: UAVState;
  gimbal: GimbalState;
  target: TargetState;
  path: NavigationPathState;
  // ── Spec 017 (FR-016/017/018): multi-entity view ──
  // When present, `entities` holds ALL entities keyed by unique_id. The
  // legacy single-uav/single-target fields above remain populated (for
  // backward compat) from the first UAV / first ground_vehicle found.
  entities?: Record<string, EntityState>;
  // ── Spec 019 (US6 / T077): published threat zones bucket ──
  // Carried verbatim from sim:state["zones"].  Contains three keys
  // (`air_defense`, `comm_jam_static`, `comm_jam_random`) each holding
  // an array of {polygon, alt_min, alt_max} records.  Consumed by
  // KillZoneOverlay (red) and JamZoneOverlay (purple) for the
  // adversarial-swarm-search scenario.
  zones?: Record<string, unknown>;
}

// Spec 017: per-message comm inbox entry (FR-018 visualization input).
export interface CommInboxEntry {
  sender: string;
  payload: string;
  recv_time: number;
}

// Spec 017: per-UAV comm state.
export interface CommState {
  enabled: boolean;
  range_m: number;
  max_bytes: number;
  max_rate_hz: number;
  inbox: CommInboxEntry[];
  stats: {
    sent: number;
    delivered: number;
    received: number;
    rejected_bytes: number;
    rejected_rate: number;
    rejected_range: number;
    rejected_jam: number;
  };
}

// Spec 018: Team enum for red/blue/white role filtering.
export type Team = 'white' | 'red' | 'blue';

// Spec 018: Event source kind — kernel vs external.
export type EventSourceKind = 'kernel' | 'external';

// Spec 018: Two-part source object identifying who produced the event.
export interface EventSource {
  kind: EventSourceKind;
  producer: string;
  team?: Team | null;
  auth?: unknown;
}

// Spec 018: Auth token placeholder (reserved, not implemented this feature).
export interface AuthToken {
  token?: string;
  expires_at?: number;
}

// Spec 018: Event type namespace prefixes defined by the contract.
// `state.*` / `target.*` — external controller events
// `kernel.*` — reserved, not published this feature
export type EventType =
  | 'state.enter_track'
  | 'state.exit_track'
  | 'target.discovered'
  | (string & {}); // allow unknown future types

// Spec 018: Payload per event_type.
export interface EventPayloadBase {
  [key: string]: unknown;
}

export interface StateEnterTrackPayload extends EventPayloadBase {
  target_position?: { latitude: number; longitude: number; altitude: number };
  target_type?: string;
  confidence?: number;
}

export interface StateExitTrackPayload extends EventPayloadBase {
  reason?: string;
  last_known_position?: { latitude: number; longitude: number; altitude: number } | null;
}

export interface TargetDiscoveredPayload extends EventPayloadBase {
  target_position?: { latitude: number; longitude: number; altitude: number };
  target_type?: string;
  confidence?: number;
  azimuth_error?: number;
}

// Spec 018: Full SimEvent message structure on the `sim:events` channel.
export interface SimEvent {
  event_type: EventType;
  source: EventSource;
  entity_uid: string;
  sim_time: number;
  payload: EventPayloadBase;
  event_id?: string;
}

// Spec 018: detection extended with misid fields (FR-014/015).
export interface ExtendedDetection {
  detected: boolean;
  confidence: number;
  target_position?: WGS84Coord;
  azimuth_error?: number;
  target_type: string;   // "ground_vehicle" | "decoy_vehicle" | ""
  misid_flag: boolean;
  misid_count: number;
  misid_track_duration: number;
}

// Spec 017: one entity in the multi-entity view.
export type EntityKind = 'uav' | 'ground_vehicle' | 'decoy_vehicle';

export interface EntityState {
  uid: string;
  kind: EntityKind;
  name: string;
  // UAV-only fields (undefined for vehicles).
  uav?: UAVState;
  gimbal?: GimbalState;
  detection?: ExtendedDetection;
  comm?: CommState;
  // Vehicle-only fields (undefined for UAVs).
  vehicle?: TargetState;
}

/**
 * Free-function WGS84 → ENU conversion for code paths that do not own a
 * WGS84Projection instance (e.g. overlay builders and FX that need to
 * project a single (lat, lon) into local frame).  Returns [east, north]
 * in meters using the same WGS84 spherical model as WGS84Projection.
 */
export function wgs84ToEnu(
  latitude: number,
  longitude: number,
  referenceLat: number,
  referenceLon: number,
): [number, number] {
  const R = 6371000; // m
  const toRad = (d: number) => (d * Math.PI) / 180;
  const lat1 = toRad(referenceLat);
  const lat2 = toRad(latitude);
  const dLat = lat2 - lat1;
  const dLon = toRad(longitude - referenceLon);
  const e = R * dLon * Math.cos(lat1);
  const n = R * dLat;
  return [e, n];
}

export class WGS84Projection {
  private centerLat: number;
  private centerLon: number;
  private centerAlt: number;

  constructor(centerLatitude: number, centerLongitude: number, centerAltitude: number = 0) {
    this.centerLat = centerLatitude;
    this.centerLon = centerLongitude;
    this.centerAlt = centerAltitude;
  }

  /**
   * Expose the WGS84 origin (lat, lon) used to define the local ENU frame.
   * Other renderers (e.g. threat-zone overlays) must use the **same**
   * origin or their geometry will be mis-projected by tens to thousands
   * of metres relative to the terrain / entity renderers.
   */
  getCenterLat(): number { return this.centerLat; }
  getCenterLon(): number { return this.centerLon; }
  getCenterAlt(): number { return this.centerAlt; }

  /**
   * Convert WGS84 coordinates to ENU (East-North-Up) coordinates
   */
  toENU(latitude: number, longitude: number, altitude: number): ENUCoord {
    const R = 6371000; // Earth's radius in meters

    const lat1 = this.toRad(this.centerLat);
    const lat2 = this.toRad(latitude);
    const dLat = lat2 - lat1;
    const dLon = this.toRad(longitude - this.centerLon);

    const x = R * dLon * Math.cos(lat1);
    const y = R * dLat;
    const z = altitude - this.centerAlt;

    return { x, y, z };
  }

  /**
   * Convert ENU coordinates to WGS84 coordinates
   */
  toWGS84(x: number, y: number, z: number): WGS84Coord {
    const R = 6371000;

    const lat1 = this.toRad(this.centerLat);
    const dLat = y / R;
    const dLon = x / (R * Math.cos(lat1));

    const latitude = this.centerLat + this.toDeg(dLat);
    const longitude = this.centerLon + this.toDeg(dLon);
    const altitude = z + this.centerAlt;

    return { latitude, longitude, altitude };
  }

  /**
   * Convert WGS84 coordinates to Three.js Vector3
   */
  toVector3(latitude: number, longitude: number, altitude: number): THREE.Vector3 {
    const enu = this.toENU(latitude, longitude, altitude);
    return new THREE.Vector3(enu.x, enu.z, -enu.y); // Swap Y/Z for Three.js coordinate system
  }

  /**
   * Convert Three.js Vector3 to WGS84 coordinates
   */
  fromVector3(vector: THREE.Vector3): WGS84Coord {
    return this.toWGS84(vector.x, -vector.z, vector.y);
  }

  private toRad(deg: number): number {
    return (deg * Math.PI) / 180;
  }

  private toDeg(rad: number): number {
    return (rad * 180) / Math.PI;
  }
}