//
// Spec 020 T7: EntityManager — extracted from app.ts. Owns the
// per-entity renderer / trajectory-trail / gimbal-indicator maps and the
// spawn-update-dispose loop that was updateMultiEntityRenderers(). The
// App now delegates the multi-entity render path here so app.ts stays
// under 200 lines.
//
// Behaviour is byte-equivalent to the pre-refactor App: each entity that
// appears gets a renderer + trail (UAVs also get a gimbal indicator),
// vehicles are clamped to terrain, and disappearing entities are disposed
// + removed from the scene. Kind dispatch goes through EntityKindRegistry.
import * as THREE from 'three';
import { SceneManager } from '../rendering/scene';
import { WGS84Projection, EntityState, EntityKind } from '../core/wgs84-projection';
import { SimulationState } from '../core/state-manager';
import { TerrainRenderer } from '../rendering/terrain';
import { UAVModelRenderer } from '../rendering/uav-model';
import { VehicleModelRenderer } from '../rendering/vehicle-model';
import { DecoyModelRenderer } from '../rendering/decoy-model';
import { GimbalIndicator } from '../rendering/gimbal-indicator';
import { TrajectoryTrail } from '../rendering/trajectory-trail';
import { describeEntityKind } from '../core/entity-kind-registry';

/** Minimal renderer shape the manager needs (getModel + optional dispose). */
interface SpawnedRenderer {
  getModel(): THREE.Object3D;
}

/** Toggle readers the manager inherits from the UI at spawn time. */
export interface EntityManagerToggles {
  /** Current trail-visibility checkbox state. */
  trailVisible: () => boolean;
  /** Current gimbal-FOV checkbox state. */
  gimbalFovVisible: () => boolean;
}

export class EntityManager {
  private renderers: Map<string, SpawnedRenderer> = new Map();
  private trails: Map<string, TrajectoryTrail> = new Map();
  private uavIndicators: Map<string, GimbalIndicator> = new Map();

  constructor(
    private sceneManager: SceneManager,
    private projection: WGS84Projection,
    private terrain: TerrainRenderer,
    private toggles: EntityManagerToggles,
  ) {}

  /** Reconcile the per-entity maps with the current frame's entities. */
  update(entities: Record<string, EntityState>): void {
    const seen = new Set<string>();

    for (const [uid, entity] of Object.entries(entities)) {
      const descriptor = describeEntityKind(entity.kind);
      const payload = entity.uav ?? entity.vehicle;
      if (!payload) continue;

      seen.add(uid);

      let r = this.renderers.get(uid);
      if (!r) {
        r = this.spawnRenderer(entity.kind);
        this.renderers.set(uid, r);
        this.sceneManager.add(r.getModel());
        this.sceneManager.registerSelectable({
          object: r.getModel(),
          entityType: descriptor.entityType,
          entityId: uid,
        });
        const trail = new TrajectoryTrail(this.projection, descriptor.trailKind);
        this.trails.set(uid, trail);
        this.sceneManager.add(trail.getLine());
        trail.setVisible(this.toggles.trailVisible());
        if (entity.kind === 'uav') {
          const indicator = new GimbalIndicator();
          r.getModel().add(indicator.getModel());
          this.uavIndicators.set(uid, indicator);
          indicator.setFovVisible(this.toggles.gimbalFovVisible());
        }
      }

      if (entity.kind === 'uav') {
        (r as UAVModelRenderer).update(entity.uav!);
        const trail = this.trails.get(uid);
        if (trail && entity.uav) {
          trail.updatePosition(
            entity.uav.latitude, entity.uav.longitude, entity.uav.altitude);
        }
        const indicator = this.uavIndicators.get(uid);
        if (indicator && entity.gimbal) {
          const groundAlt = this.terrain.getElevation(
            entity.uav!.latitude, entity.uav!.longitude);
          indicator.update(entity.gimbal, entity.uav!.altitude, groundAlt);
        }
      } else {
        const v = entity.vehicle!;
        // 直接使用 Redis 传回的真实 altitude（仿真引擎的海拔基准）。
        if (entity.kind === 'decoy_vehicle') {
          (r as DecoyModelRenderer).update(v);
        } else {
          (r as VehicleModelRenderer).update(v);
        }
        const trail = this.trails.get(uid);
        if (trail) {
          trail.updatePosition(v.latitude, v.longitude, v.altitude);
        }
      }
    }

    // Dispose renderers for entities that disappeared this tick (V-4).
    for (const [uid, r] of this.renderers) {
      if (!seen.has(uid)) {
        this.sceneManager.remove(r.getModel());
        (r as unknown as { dispose?: () => void }).dispose?.();
        this.renderers.delete(uid);
      }
    }
    for (const [uid, trail] of this.trails) {
      if (!seen.has(uid)) {
        this.sceneManager.remove(trail.getLine());
        this.trails.delete(uid);
      }
    }
    for (const uid of this.uavIndicators.keys()) {
      if (!seen.has(uid)) {
        this.uavIndicators.delete(uid);
      }
    }
  }

  /** Propagate the trail-visibility toggle to all trails. */
  setTrailsVisible(visible: boolean): void {
    for (const trail of this.trails.values()) trail.setVisible(visible);
  }

  /** Propagate the FOV toggle to all UAV gimbal indicators. */
  setGimbalFovVisible(visible: boolean): void {
    for (const indicator of this.uavIndicators.values()) indicator.setFovVisible(visible);
  }

  /**
   * Resolve a selected entity's 3D position by unique_id (multi-entity
   * path). Returns the origin if the id is not in the map.
   */
  positionForEntity(entityId: string | null | undefined, state: SimulationState): THREE.Vector3 {
    if (!entityId || !state.entities) return new THREE.Vector3();
    const e = state.entities[entityId];
    if (!e) return new THREE.Vector3();
    if (e.uav) {
      return this.projection.toVector3(e.uav.latitude, e.uav.longitude, e.uav.altitude);
    }
    if (e.vehicle) {
      // 直接用 Redis 传回的真实 altitude（与 update() 一致）。
      return this.projection.toVector3(e.vehicle.latitude, e.vehicle.longitude, e.vehicle.altitude);
    }
    return new THREE.Vector3();
  }

  private spawnRenderer(kind: EntityKind): SpawnedRenderer {
    switch (kind) {
      case 'uav': return new UAVModelRenderer(this.projection);
      case 'ground_vehicle': return new VehicleModelRenderer(this.projection);
      case 'decoy_vehicle': return new DecoyModelRenderer(this.projection);
      default: {
        const _exhaustive: never = kind;
        throw new Error(`spawnRenderer: no factory for kind ${_exhaustive}`);
      }
    }
  }
}
