//
// Spec 020 T7: shared base for the two vehicle renderers
// (vehicle-model.ts = real target, decoy-model.ts = decoy). Before this
// the two classes were ~95% identical: same body/roof/wheel geometry,
// same update()/getModel()/dispose(), differing only in colour + the
// decoy's diagonal roof stripe. This base centralises the geometry +
// lifecycle; subclasses pass a `VehicleModelConfig` that drives colour,
// label text, and the optional roof-stripe decoration. The rendered
// output is byte-equivalent to the pre-refactor classes.
import * as THREE from 'three';
import { WGS84Projection, TargetState } from '../core/wgs84-projection';
import { createLabel } from './label-factory';
import { ENTITY_COLORS, ENTITY_EMISSIVE, ENTITY_LABEL_CSS } from './constants';

/** Palette + label for one vehicle variant. */
export interface VehicleModelConfig {
  /** Body colour (hex). */
  bodyColor: number;
  /** Body emissive tint (hex). */
  bodyEmissive: number;
  /** Roof colour (hex). */
  roofColor: number;
  /** Roof emissive tint (hex). */
  roofEmissive: number;
  /** Sprite label text + its canvas fill colour. */
  label: { text: string; fillStyle: string };
  /** When true, add the diagonal black roof stripe (decoy marker). */
  decoyStripe?: boolean;
}

export const TARGET_VEHICLE_CONFIG: VehicleModelConfig = {
  bodyColor: ENTITY_COLORS.target,
  bodyEmissive: ENTITY_EMISSIVE.target,
  roofColor: 0xd32f2f,
  roofEmissive: ENTITY_EMISSIVE.target,
  label: { text: 'TARGET', fillStyle: ENTITY_LABEL_CSS.target },
};

export const DECOY_VEHICLE_CONFIG: VehicleModelConfig = {
  bodyColor: ENTITY_COLORS.decoy,
  bodyEmissive: ENTITY_EMISSIVE.decoy,
  roofColor: 0xffa000,
  roofEmissive: ENTITY_EMISSIVE.decoy,
  label: { text: 'DECOY', fillStyle: ENTITY_LABEL_CSS.decoy },
  decoyStripe: true,
};

/**
 * Four-wheeled box-vehicle renderer. Body + roof + wheels + label are
 * shared; the `decoyStripe` flag adds the decoy-only diagonal marker.
 */
export class VehicleModelBase {
  protected model: THREE.Group;
  protected projection: WGS84Projection;

  constructor(projection: WGS84Projection, config: VehicleModelConfig) {
    this.projection = projection;
    this.model = this.createModel(config);
  }

  private createModel(config: VehicleModelConfig): THREE.Group {
    const group = new THREE.Group();

    // Body
    const bodyGeometry = new THREE.BoxGeometry(4, 2, 6);
    const bodyMaterial = new THREE.MeshPhongMaterial({
      color: config.bodyColor,
      emissive: config.bodyEmissive,
      emissiveIntensity: 0.2,
    });
    const body = new THREE.Mesh(bodyGeometry, bodyMaterial);
    body.position.y = 1.5;
    group.add(body);

    // Roof
    const roofGeometry = new THREE.BoxGeometry(3.5, 1.5, 4);
    const roofMaterial = new THREE.MeshPhongMaterial({
      color: config.roofColor,
      emissive: config.roofEmissive,
      emissiveIntensity: 0.2,
    });
    const roof = new THREE.Mesh(roofGeometry, roofMaterial);
    roof.position.y = 3.25;
    roof.position.z = -0.5;
    group.add(roof);

    // Decoy-only diagonal stripe marker on the roof.
    if (config.decoyStripe) {
      const stripeGeometry = new THREE.BoxGeometry(4.2, 0.2, 1.0);
      const stripeMaterial = new THREE.MeshPhongMaterial({ color: 0x212121 });
      const stripe = new THREE.Mesh(stripeGeometry, stripeMaterial);
      stripe.position.y = 4.05;
      stripe.rotation.y = Math.PI / 4;
      group.add(stripe);
    }

    // Wheels (shared)
    const wheelGeometry = new THREE.CylinderGeometry(0.8, 0.8, 0.5, 16);
    const wheelMaterial = new THREE.MeshPhongMaterial({ color: 0x212121 });
    const wheelPositions = [
      { x: -2.2, y: 0.8, z: 2 },
      { x: 2.2, y: 0.8, z: 2 },
      { x: -2.2, y: 0.8, z: -2 },
      { x: 2.2, y: 0.8, z: -2 },
    ];
    for (const pos of wheelPositions) {
      const wheel = new THREE.Mesh(wheelGeometry, wheelMaterial);
      wheel.position.set(pos.x, pos.y, pos.z);
      wheel.rotation.z = Math.PI / 2;
      group.add(wheel);
    }

    // Label
    const label = createLabel(config.label);
    label.position.y = 8;
    group.add(label);

    return group;
  }

  update(state: TargetState): void {
    const position = this.projection.toVector3(
      state.latitude,
      state.longitude,
      state.altitude,
    );
    this.model.position.copy(position);
    this.model.rotation.y = THREE.MathUtils.degToRad(-state.heading + 180);
  }

  getModel(): THREE.Group {
    return this.model;
  }

  dispose(): void {
    this.model.traverse((obj) => {
      if (obj instanceof THREE.Mesh) {
        obj.geometry.dispose();
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => m.dispose());
        } else {
          obj.material.dispose();
        }
      }
      if (obj instanceof THREE.Sprite) {
        obj.material.map?.dispose();
        obj.material.dispose();
      }
    });
  }
}
