//
// Spec 020 T8: schema-driven validation for inbound sim:state frames.
// Before T8 the only thing guarding normalizeSimState was a handful of
// ad-hoc `typeof`/range checks. This module compiles the JSON Schemas
// under config/schema/ with ajv (draft 2020-12) and exposes:
//
//   - validateSimState(frame):  ValidationResult   (inbound gate)
//   - validateSimCommand(cmd):  ValidationResult   (outbound gate)
//
// validateSimState is wired into redis-client so a frame that fails
// schema validation is dropped (with a console.warn) BEFORE the manual
// normalisation runs — the schema is now the contract, and the manual
// guards become a defence-in-depth backstop. The command validator is
// available for the services layer to assert outbound payloads.
//
// Schema JSON is imported directly (resolveJsonModule: true) so webpack
// bundles them at build time — no runtime file fetch.
import Ajv2020, { ValidateFunction, ErrorObject } from 'ajv/dist/2020';
// @schemas/* is aliased (tsconfig paths + webpack resolve.alias) to
// ../../config/schema, so the contract JSON lives in ONE place
// (config/schema) and is shared with the C++ validator.
import simStateSchema from '@schemas/sim-state.schema.json';
import zonesBucketSchema from '@schemas/zones-bucket.schema.json';
import simCommandsSchema from '@schemas/sim-commands.schema.json';

export interface ValidationResult {
  valid: boolean;
  /** Human-readable error list (empty when valid). */
  errors: string[];
}

const ajv = new Ajv2020({ allErrors: true, strict: false, allowUnionTypes: true });
// zones-bucket is referenced by $id inside sim-state; register both.
ajv.addSchema(zonesBucketSchema);
const validateState: ValidateFunction = ajv.compile(simStateSchema);
const validateCommand: ValidateFunction = ajv.compile(simCommandsSchema);

function formatErrors(errors: ErrorObject[] | null | undefined): string[] {
  if (!errors) return [];
  return errors.map((e) =>
    `${e.instancePath || '(root)'} ${e.message ?? ''}`.trim());
}

/** Validate an inbound sim:state frame against sim-state.schema.json. */
export function validateSimState(frame: unknown): ValidationResult {
  const ok = validateState(frame);
  return { valid: ok, errors: ok ? [] : formatErrors(validateState.errors) };
}

/** Validate an outbound sim:commands payload against sim-commands.schema.json. */
export function validateSimCommand(command: unknown): ValidationResult {
  const ok = validateCommand(command);
  return { valid: ok, errors: ok ? [] : formatErrors(validateCommand.errors) };
}
