import * as THREE from 'three';
import { WGS84Projection, UAVState } from '../core/wgs84-projection';
import { createLabel } from './label-factory';
import { ENTITY_COLORS, ENTITY_EMISSIVE, ENTITY_LABEL_CSS } from './constants';

export class UAVModelRenderer {
  private model: THREE.Group;
  private projection: WGS84Projection;

  constructor(projection: WGS84Projection) {
    this.projection = projection;
    this.model = this.createModel();
  }

  private createModel(): THREE.Group {
    const group = new THREE.Group();
    group.rotation.order = 'YXZ';  // yaw → pitch → roll 航空标准顺序

    // Create UAV body (cone + cylinder)
    const bodyGeometry = new THREE.ConeGeometry(2, 10, 8);
    const bodyMaterial = new THREE.MeshPhongMaterial({
      color: ENTITY_COLORS.uav,
      emissive: ENTITY_EMISSIVE.uav,
      emissiveIntensity: 0.2
    });
    const body = new THREE.Mesh(bodyGeometry, bodyMaterial);
    body.rotation.x = -Math.PI / 2;  // 指向 -Z (North)
    group.add(body);

    // Create wings
    const wingGeometry = new THREE.BoxGeometry(15, 0.3, 3);
    const wingMaterial = new THREE.MeshPhongMaterial({
      color: 0x1976d2,
      emissive: ENTITY_EMISSIVE.uav,
      emissiveIntensity: 0.2
    });
    const wings = new THREE.Mesh(wingGeometry, wingMaterial);
    wings.position.z = 1;
    group.add(wings);

    // Create tail
    const tailGeometry = new THREE.BoxGeometry(1, 4, 2);
    const tailMaterial = new THREE.MeshPhongMaterial({
      color: 0x1976d2,
      emissive: ENTITY_EMISSIVE.uav,
      emissiveIntensity: 0.2
    });
    const tail = new THREE.Mesh(tailGeometry, tailMaterial);
    tail.position.z = 4;  // 尾部在 +Z (South)
    tail.position.y = 2;
    group.add(tail);

    // Add label
    const label = createLabel({ text: 'UAV', fillStyle: ENTITY_LABEL_CSS.uav });
    label.position.y = 8;
    group.add(label);

    return group;
  }

  update(state: UAVState): void {
    // Update position
    const position = this.projection.toVector3(
      state.latitude,
      state.longitude,
      state.altitude
    );
    this.model.position.copy(position);

    // Update rotation (convert degrees to radians)
    // C++ yaw: 顺时针从北方 (0=N, 90=E, 180=S, 270=W)
    // Three.js rotation.y: 逆时针从上方看，需要取反
    // 模型默认朝 -Z (North)，pitch/roll 也需要相应调整
    this.model.rotation.x = THREE.MathUtils.degToRad(-state.pitch);  // pitch>0 机头向上
    this.model.rotation.y = THREE.MathUtils.degToRad(-state.yaw);    // yaw 顺时针→逆时针
    this.model.rotation.z = THREE.MathUtils.degToRad(state.roll);    // roll>0 右翼向下
  }

  getModel(): THREE.Group {
    return this.model;
  }
}