// Spec 019 US6 / T075 — KillEventFX
//
// A lightweight particle-based explosion/disappear effect triggered
// when an entity transitions from active -> destroyed.  The
// visualisation subscribes to the StateManager's state changes; any
// entity whose previous status was 'active' and current status is
// 'destroyed' produces a `trigger(uid, lat, lon, alt)` call.
//
// The effect is a Three.js particle system with a short lifetime
// (1.5 s) that fades and shrinks.  We use a small `Points` mesh
// rather than per-particle meshes for performance.
import * as THREE from 'three';

import { wgs84ToEnu } from '../core/wgs84-projection';

interface ActiveEffect {
  uid: string;
  points: THREE.Points;
  start: number;
  lifetime_s: number;
  velocities: Float32Array;  // per-particle
}

export class KillEventFX {
  private group: THREE.Group;
  private effects: ActiveEffect[] = [];
  private now: () => number;

  constructor(parent: THREE.Scene, clock: () => number = () => performance.now() / 1000) {
    this.group = new THREE.Group();
    this.group.name = 'KillEventFX';
    parent.add(this.group);
    this.now = clock;
  }

  trigger(uid: string, lat: number, lon: number, alt: number,
          referenceLat: number, referenceLon: number): void {
    const N = 32;
    const positions = new Float32Array(N * 3);
    const velocities = new Float32Array(N * 3);
    const [e, n] = wgs84ToEnu(lat, lon, referenceLat, referenceLon);
    for (let i = 0; i < N; i++) {
      positions[i * 3 + 0] = e;
      positions[i * 3 + 1] = alt;
      positions[i * 3 + 2] = -n;
      // Random outward velocity
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.acos(2 * Math.random() - 1);
      const speed = 8 + Math.random() * 12;  // m/s
      velocities[i * 3 + 0] = speed * Math.sin(phi) * Math.cos(theta);
      velocities[i * 3 + 1] = speed * Math.cos(phi);
      velocities[i * 3 + 2] = speed * Math.sin(phi) * Math.sin(theta);
    }
    const geom = new THREE.BufferGeometry();
    geom.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    const mat = new THREE.PointsMaterial({
      color: 0xffaa33, size: 4, transparent: true, opacity: 1.0,
      depthWrite: false,
    });
    const points = new THREE.Points(geom, mat);
    this.group.add(points);
    this.effects.push({
      uid, points, start: this.now(), lifetime_s: 1.5, velocities,
    });
  }

  tick(): void {
    const t = this.now();
    for (let i = this.effects.length - 1; i >= 0; i--) {
      const e = this.effects[i];
      if (!e) continue;
      const dt = t - e.start;
      if (dt >= e.lifetime_s) {
        this.group.remove(e.points);
        e.points.geometry.dispose();
        (e.points.material as THREE.Material).dispose();
        this.effects.splice(i, 1);
        continue;
      }
      // Animate: expand and fade
      const pos = e.points.geometry.getAttribute('position') as THREE.BufferAttribute;
      for (let j = 0; j < pos.count; j++) {
        const v0 = e.velocities[j * 3 + 0];
        const v1 = e.velocities[j * 3 + 1];
        const v2 = e.velocities[j * 3 + 2];
        if (v0 === undefined || v1 === undefined || v2 === undefined) continue;
        const a0 = pos.array[j * 3 + 0];
        const a1 = pos.array[j * 3 + 1];
        const a2 = pos.array[j * 3 + 2];
        if (a0 === undefined || a1 === undefined || a2 === undefined) continue;
        pos.array[j * 3 + 0] = a0 + v0 * 0.05;
        pos.array[j * 3 + 1] = a1 + v1 * 0.05;
        pos.array[j * 3 + 2] = a2 + v2 * 0.05;
      }
      pos.needsUpdate = true;
      (e.points.material as THREE.PointsMaterial).opacity = 1.0 - (dt / e.lifetime_s);
    }
  }

  dispose(): void {
    for (const e of this.effects) {
      this.group.remove(e.points);
      e.points.geometry.dispose();
    }
    this.effects = [];
    this.group.parent?.remove(this.group);
  }
}
