// 赛题选择面板 —— 风琴页版本。
// 每个赛题一个 section(默认展开全部: 赛题名 + 简介, 无折叠), 选中赛题后:
//   - 配置行(天气 / 车辆随机路线种子) 始终显示在赛题列表下方。
//   - "官方示例算法 / 参赛者算法" 选择栏统一放在所有赛题的最下面;
//     选参赛者时显示参赛者算法列表(含"刷新参赛者算法"按钮),
//     选官方时使用 baseline 算法。

export interface PanelAlgorithm {
  name: string;
  agentSpec: string;
  source: 'baseline' | 'user';
  scenarioId: string;
  docstring?: string;
}

export interface PanelScenario {
  id: string;
  name: string;
  label?: string;          // UI 编号前缀, 如 "赛题一"
  description: string;
  available?: boolean;
  algorithms?: PanelAlgorithm[];
}

export interface ScenarioSelectorEvents {
  onStart?: (id: string, agent?: string, routeSeed?: number) => void;
  onPauseResume?: () => void;
  onClose?: () => void;
  onRefresh?: (scenarioId: string) => void;
  /** 天气变更(启动前写回 scenario.json)。 */
  onWeatherChange?: (weather: string) => void;
  /** 车辆随机路线种子变更(字符串, 用户输入; 仅正整数会被透传)。 */
  onRouteSeedChange?: (seed: number | null) => void;
}


/**
 * 转义 HTML 特殊字符, 防止 innerHTML 注入(XSS)。
 * 参赛者算法的 name/docstring 来自磁盘 .py 文件 docstring,
 * 不可信 —— 必须在插入 innerHTML 前转义(含属性值)。
 */
function escapeHtml(s: string): string {
  return s
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

/** UE 渲染端支持的 6 种天气(英文枚举 + 中文标签)。 */
const WEATHER_OPTIONS: ReadonlyArray<{ value: string; label: string }> = [
  { value: 'Clear_Skies', label: '晴天' },
  { value: 'Foggy', label: '雾' },
  { value: 'Rain', label: '雨' },
  { value: 'Snow_Light', label: '小雪' },
  { value: 'Sand_Dust_Calm', label: '沙尘' },
  { value: 'Partly_Cloudy', label: '多云' },
];
const DEFAULT_WEATHER = 'Rain';

export class ScenarioSelectorPanel {
  private events: ScenarioSelectorEvents = {};
  private scenarios: PanelScenario[] = [];
  /** 当前选中的赛题 id(取代原来的 expandedId)。 */
  private selectedId: string | null = null;
  /** 算法模式: baseline(官方示例) 或 user(参赛者)。 */
  private mode: 'baseline' | 'user' = 'baseline';
  /** user 模式下选中的参赛者算法 agentSpec。 */
  private selectedAlgo: string = '';
  private status = 'idle';
  private pct = 0;
  private phase = '';
  private errorMsg: string | null = null;
  private stallTimer: ReturnType<typeof setTimeout> | null = null;
  /** 刷新按钮恢复函数(请求完成后重置按钮状态)。 */
  private refreshBtnReset: (() => void) | null = null;
  private weather: string = DEFAULT_WEATHER;
  /** 车辆随机路线种子(字符串输入, 内部 parse 为 number 或 null)。 */
  private routeSeedInput: string = '';

  constructor(containerId: string) {
    const container = document.getElementById(containerId);
    if (!container) {
      throw new Error(`Container element #${containerId} not found`);
    }
    this.render();
  }

  private render(): void {
    const body = document.getElementById('scenario-selector-body');
    if (!body) return;
    body.innerHTML = `
      <div class="sc-list" id="sc-list"></div>
      <div class="sc-config-row" id="sc-config-row">
        <label class="sc-config-item">
          <span class="sc-config-label">天气</span>
          <select id="sc-weather">
            ${WEATHER_OPTIONS.map(
              (w) =>
                `<option value="${w.value}"${w.value === this.weather ? ' selected' : ''}>${w.label}</option>`,
            ).join('')}
          </select>
        </label>
        <label class="sc-config-item">
          <span class="sc-config-label">车辆随机路线种子</span>
          <input type="number" id="sc-route-seed" min="1" step="1" placeholder="(可选)" />
        </label>
      </div>
      <div class="sc-algo-picker" id="sc-algo-picker" style="display:none;">
        <div class="sc-algo-mode-row">
          <label class="sc-mode-item sc-mode-baseline">
            <input type="radio" name="sc-mode" value="baseline" ${this.mode === 'baseline' ? 'checked' : ''} />
            <span class="sc-mode-name">官方示例算法</span>
          </label>
          <label class="sc-mode-item sc-mode-user">
            <input type="radio" name="sc-mode" value="user" ${this.mode === 'user' ? 'checked' : ''} />
            <span class="sc-mode-name">参赛者算法</span>
          </label>
        </div>
        <div class="sc-user-list" id="sc-user-list"></div>
      </div>
      <div class="sc-progress" id="sc-progress" style="display:none;">
        <div class="sc-progress-track"><div class="sc-progress-fill" id="sc-progress-fill"></div></div>
        <div class="sc-progress-text" id="sc-progress-text"></div>
      </div>
      <div class="sc-buttons">
        <button id="sc-start" class="control-btn primary" disabled>开始仿真</button>
        <button id="sc-pause" class="control-btn" disabled>暂停</button>
        <button id="sc-close" class="control-btn" disabled>关闭仿真</button>
      </div>
      <div class="sc-error" id="sc-error" style="display:none;"></div>
    `;
    // 默认回填种子输入框(保留状态)。
    const seedInput = document.getElementById('sc-route-seed') as HTMLInputElement | null;
    if (seedInput) seedInput.value = this.routeSeedInput;
    this.bindEvents();
    // render 重建 DOM 会丢失 disabled 属性, 按当前 status 恢复配置控件锁定态。
    this.updateConfigLockState();
  }

  private bindEvents(): void {
    document.getElementById('sc-start')?.addEventListener('click', () => {
      const id = this.selectedId;
      if (!id) return;
      const agent = this.resolveAgent(id);
      if (agent === null) return;
      const seed = this.parsedRouteSeed();
      this.events.onStart?.(id, agent ?? undefined, seed ?? undefined);
    });
    document.getElementById('sc-pause')?.addEventListener('click', () => this.events.onPauseResume?.());
    document.getElementById('sc-close')?.addEventListener('click', () => this.events.onClose?.());

    const weatherSel = document.getElementById('sc-weather') as HTMLSelectElement | null;
    weatherSel?.addEventListener('change', () => {
      this.weather = weatherSel.value;
      this.events.onWeatherChange?.(this.weather);
    });

    const seedInput = document.getElementById('sc-route-seed') as HTMLInputElement | null;
    seedInput?.addEventListener('input', () => {
      this.routeSeedInput = seedInput.value.trim();
      this.events.onRouteSeedChange?.(this.parsedRouteSeed());
    });

    // 算法模式切换(baseline / user)。
    document.querySelectorAll<HTMLInputElement>('input[name="sc-mode"]').forEach((r) => {
      r.addEventListener('change', (ev) => {
        const input = ev.target as HTMLInputElement;
        this.mode = input.value as 'baseline' | 'user';
        // 切回 baseline 时清掉可能不再有效的用户选中。
        if (this.mode === 'baseline') this.selectedAlgo = '';
        this.renderAlgoPicker();
        this.updateButtonStates();
      });
    });
  }

  /** 解析种子输入框: 正整数才返回(后端按 seed%30 选路线), 否则 null。 */
  private parsedRouteSeed(): number | null {
    const raw = this.routeSeedInput;
    if (!raw) return null;
    const n = Number(raw);
    if (!Number.isFinite(n) || !Number.isInteger(n) || n <= 0) return null;
    return n;
  }

  /**
   * 解析当前应启动的 agent。
   * @returns agentSpec 字符串; null 表示不可启动(user 模式但未选具体参赛者算法)。
   */
  private resolveAgent(id: string): string | null {
    if (this.mode === 'user') {
      return this.selectedAlgo || null;
    }
    return this.baselineSpec(id) ?? null;
  }

  private baselineSpec(id: string): string | undefined {
    const sc = this.scenarios.find((s) => s.id === id);
    return sc?.algorithms?.find((a) => a.source === 'baseline')?.agentSpec;
  }

  setScenarios(list: PanelScenario[]): void {
    this.scenarios = list;
    // 默认选中第一个赛题(若之前选中的已不存在则回落)。
    if (this.selectedId !== null && !list.some((s) => s.id === this.selectedId)) {
      this.selectedId = null;
    }
    if (this.selectedId === null && list.length > 0) {
      this.selectedId = list[0]!.id;
    }
    this.renderList();
    this.renderAlgoPicker();
    this.updateButtonStates();
  }

  /** 刷新单个赛题的算法列表(user 模式下保留仍存在的选中, 否则清空选中)。 */
  refreshAlgos(scenarioId: string, algorithms: PanelAlgorithm[]): void {
    const sc = this.scenarios.find((s) => s.id === scenarioId);
    if (!sc) return;
    sc.algorithms = algorithms;
    // 若当前 user 选中已不在新列表 → 清空(启动将禁用, 直到用户重选)。
    const cur = this.selectedAlgo;
    if (cur && !algorithms.some((a) => a.agentSpec === cur && a.source === 'user')) {
      this.selectedAlgo = '';
    }
    this.renderList();
    this.renderAlgoPicker();
    this.updateButtonStates();
    this.refreshBtnReset?.();
    this.refreshBtnReset = null;
  }

  private renderList(): void {
    const el = document.getElementById('sc-list');
    if (!el) return;
    el.innerHTML = this.scenarios.map((s) => this.renderScenario(s)).join('');
    el.querySelectorAll<HTMLElement>('.sc-scenario-card').forEach((card) => {
      card.addEventListener('click', () => {
        // 点 checkbox / 文字描述都算选; 不再有点击展开/折叠。
        const id = card.getAttribute('data-scenario')!;
        if (id === this.selectedId) return;
        this.selectedId = id;
        // 切赛题时清掉之前 user 模式的选中(可能不适用于新赛题)。
        this.selectedAlgo = '';
        this.renderList();
        this.renderAlgoPicker();
        this.updateButtonStates();
      });
    });
  }

  private renderScenario(s: PanelScenario): string {
    const isSelected = s.id === this.selectedId;
    const title = s.label ? `${escapeHtml(s.label)}：${escapeHtml(s.name)}` : escapeHtml(s.name);
    const unavailable = s.available === false;
    return `
      <div class="sc-scenario-card${isSelected ? ' selected' : ''}${unavailable ? ' unavailable' : ''}" data-scenario="${escapeHtml(s.id)}">
        <div class="sc-scenario-head">
          <span class="sc-scenario-radio${isSelected ? ' checked' : ''}"></span>
          <span class="sc-scenario-name">${title}</span>
        </div>
        <div class="sc-scenario-desc">${escapeHtml(s.description)}</div>
      </div>`;
  }

  private renderAlgoPicker(): void {
    const picker = document.getElementById('sc-algo-picker');
    const list = document.getElementById('sc-user-list');
    if (!picker || !list) return;
    // 算法选择栏: 选中赛题时才显示。
    picker.style.display = this.selectedId ? '' : 'none';
    if (!this.selectedId) {
      list.innerHTML = '';
      return;
    }
    // 同步模式 radio 的 checked 状态(用户切赛题时可能变化)。
    const radios = document.querySelectorAll<HTMLInputElement>('input[name="sc-mode"]');
    radios.forEach((r) => { r.checked = r.value === this.mode; });

    if (this.mode !== 'user') {
      list.innerHTML = '';
      return;
    }
    // user 模式: 显示参赛者算法列表 + 刷新按钮(放在列表里)。
    const sc = this.scenarios.find((s) => s.id === this.selectedId);
    const users = sc?.algorithms?.filter((a) => a.source === 'user') ?? [];
    if (!users.length) {
      list.innerHTML = `
        <div class="sc-empty">暂无参赛者算法。<br>将算法 .py 放入 <code>competition/user_algorithms/${escapeHtml(this.selectedId)}/</code> 后点击下方「刷新」。</div>
        <button id="sc-refresh" class="control-btn sc-refresh-btn" type="button" title="刷新当前赛题的参赛者算法">↻ 刷新参赛者算法</button>`;
    } else {
      list.innerHTML = users.map((a) => {
        const checked = a.agentSpec === this.selectedAlgo ? 'checked' : '';
        const doc = a.docstring ? `<div class="sc-algo-doc">${escapeHtml(a.docstring.split('\n').slice(1).join(' ').trim())}</div>` : '';
        return `
          <label class="sc-algo-item">
            <input type="radio" name="sc-user" value="${escapeHtml(a.agentSpec)}" ${checked} />
            <span class="sc-algo-name">${escapeHtml(a.name)}</span>
            <span class="sc-algo-tag user">参赛者</span>
            ${doc}
          </label>`;
      }).join('')
      + `<button id="sc-refresh" class="control-btn sc-refresh-btn" type="button" title="刷新当前赛题的参赛者算法">↻ 刷新参赛者算法</button>`;
    }

    // 绑定参赛者算法 radio + 刷新按钮。
    list.querySelectorAll<HTMLInputElement>('input[name="sc-user"]').forEach((r) => {
      r.addEventListener('change', (ev) => {
        const input = ev.target as HTMLInputElement;
        this.selectedAlgo = input.value;
        this.updateButtonStates();
      });
    });
    const refreshBtn = document.getElementById('sc-refresh');
    refreshBtn?.addEventListener('click', (ev) => {
      if (!this.selectedId) return;
      const btn = ev.currentTarget as HTMLButtonElement;
      btn.disabled = true;
      const orig = btn.textContent;
      btn.textContent = '刷新中…';
      const timer = setTimeout(() => { btn.disabled = false; btn.textContent = orig; }, 3000);
      this.refreshBtnReset = () => { clearTimeout(timer); btn.disabled = false; btn.textContent = orig; };
      this.events.onRefresh?.(this.selectedId);
    });
  }

  selectById(id: string): void {
    if (this.selectedId !== id) {
      // 切赛题时清掉之前 user 模式的选中(可能不适用于新赛题)。
      this.selectedAlgo = '';
    }
    this.selectedId = id;
    this.renderList();
    this.renderAlgoPicker();
    this.updateButtonStates();
  }

  updateProgress(pct: number, phase?: string): void {
    this.pct = Math.max(this.pct, pct);
    if (phase) this.phase = phase;
    const wrap = document.getElementById('sc-progress');
    const fill = document.getElementById('sc-progress-fill');
    const text = document.getElementById('sc-progress-text');
    if (wrap) wrap.style.display = '';
    if (fill) fill.style.width = `${(this.pct * 100).toFixed(0)}%`;
    if (text) {
      const phaseTxt = this.phase ? `${this.phase} · ` : '';
      text.textContent = `${phaseTxt}${(this.pct * 100).toFixed(0)}%`;
    }
    // 加载完成(100%)自动隐藏进度条 —— 不依赖 session 状态机:
    // bridge 在 spawn competition 后立即推 running(sim 尚未发进度), 若 running
    // 隐藏进度条会导致"5% → 消失 → 真实进度再现"。改为由进度本身决定隐藏。
    if (this.pct >= 1 && wrap) {
      wrap.style.display = 'none';
    }
    this.armStallTimer();
  }

  updateStatus(status: string, error?: string | null): void {
    this.status = status;
    if (error !== undefined) this.errorMsg = error;
    const wrap = document.getElementById('sc-progress');
    if (wrap) {
      // 只有 idle/error 隐藏进度条; running 不隐藏 —— bridge 在 spawn 后立即推
      // running, 但此时 sim 尚未发 sim:progress, 过早隐藏会让乐观更新的进度条
      // 闪退。进度条由 updateProgress 到 100% 或仿真结束(idle)自然关闭。
      // 036-safeguard: 一旦真正 running(由 ready 帧或首个 sim:state 触发),
      // 立即收起进度条,避免 ready 帧丢失时卡死在 100%。
      wrap.style.display =
        status === 'idle' || status === 'error' ? 'none' : '';
      if (status === 'running') {
        wrap.style.display = 'none';
      }
    }
    const errEl = document.getElementById('sc-error');
    if (errEl) {
      if (status === 'error' && this.errorMsg) {
        errEl.textContent = `⚠ ${this.errorMsg}`;
        errEl.style.display = '';
      } else {
        errEl.style.display = 'none';
      }
    }
    if (status === 'idle') { this.pct = 0; this.phase = ''; }
    if (status === 'loading' || status === 'starting') this.armStallTimer();
    else this.clearStallTimer();
    this.updateButtonStates();
    // 仿真运行中(内核存活)锁定天气/种子配置, 防止运行时修改;
    // 回到 idle/error(内核完全停止)再开放, 允许下一轮调整。
    this.updateConfigLockState();
  }

  /**
   * 根据当前 status 切换天气 select / 种子 input 的 disabled 态。
   * 锁定条件与 start 按钮的启用条件互补: 内核非存活(idle/error)才开放。
   */
  private updateConfigLockState(): void {
    const locked = this.status !== 'idle' && this.status !== 'error';
    const weather = document.getElementById('sc-weather') as HTMLSelectElement | null;
    const seed = document.getElementById('sc-route-seed') as HTMLInputElement | null;
    if (weather) weather.disabled = locked;
    if (seed) seed.disabled = locked;
  }

  private updateButtonStates(): void {
    const start = document.getElementById('sc-start') as HTMLButtonElement | null;
    const pause = document.getElementById('sc-pause') as HTMLButtonElement | null;
    const close = document.getElementById('sc-close') as HTMLButtonElement | null;
    const s = this.status;
    const busy = s === 'stopping';
    const sel = this.selectedId !== null
      ? this.scenarios.find((sc) => sc.id === this.selectedId) : undefined;
    const canStart = !busy && (s === 'idle' || s === 'error')
      && this.selectedId !== null
      && sel?.available !== false
      && this.resolveAgent(this.selectedId!) !== null;
    if (start) start.disabled = !canStart;
    if (pause) {
      const running = s === 'running';
      const paused = s === 'paused';
      pause.disabled = busy || !(running || paused);
      pause.textContent = paused ? '恢复' : '暂停';
    }
    if (close) {
      close.disabled = busy || s === 'idle';
      close.textContent = busy ? '关闭中…' : '关闭仿真';
    }
  }

  private armStallTimer(): void {
    this.clearStallTimer();
    this.stallTimer = setTimeout(() => {
      if (this.status === 'loading' || this.status === 'starting') {
        const text = document.getElementById('sc-progress-text');
        if (text) text.textContent = '加载可能卡住,请稍候或检查仿真器…';
      }
    }, 5000);
  }

  private clearStallTimer(): void {
    if (this.stallTimer) { clearTimeout(this.stallTimer); this.stallTimer = null; }
  }

  getWeather(): string {
    return this.weather;
  }

  /** 当前解析后的种子(正整数才返回); 未填或非法返回 null。 */
  getRouteSeed(): number | null {
    return this.parsedRouteSeed();
  }

  on<K extends keyof ScenarioSelectorEvents>(event: K, callback: NonNullable<ScenarioSelectorEvents[K]>): void {
    this.events[event] = callback;
  }
}