/** 新手引导主组件 —— 聚光灯式分步引导(自建, 零依赖)。
 *
 *  流程: 欢迎卡(idx0, 不计步) → 第1步「快速开始」(idx1) → 第2步「查看仿真
 *  三维画面」(idx2) → 完成。全屏暗化遮罩 + box-shadow 挖洞高亮目标元素。
 *
 *  设计参考 camera-pip.ts: body 附加覆盖层 + 内联/注入样式, 复用 index.html
 *  :root 的 design token(--accent / --cta / --panel-bg-solid 等)。 */
import { OnboardingStorage } from './onboarding-storage';

type CardPlacement = 'left' | 'right';

interface TourStep {
  /** CSS 选择器; null = 欢迎卡(居中全暗, 无高亮)。 */
  target: string | null;
  title: string;
  body: string;
  /** 灰色小字提示(可选, 仅第2步用)。 */
  hint?: string;
  /** 卡片相对目标方向; 仅 target 非 null 时有效。 */
  placement?: CardPlacement;
}

const STEPS: TourStep[] = [
  {
    target: null,
    title: '欢迎使用',
    body: '欢迎参加『红枫2026』无人集群自主协同智能算法挑战赛。只需 2 步，快速上手仿真平台的核心操作。',
  },
  {
    target: '#scenario-selector',
    placement: 'left',
    title: '快速开始',
    body: '右下角面板提供三道赛题：单无人机自主识别跟踪、无人机群自主协同跟踪、无人机群自主协同打击。展开任意一题，可选择官方示例算法直接体验，或将自己的算法放入对应赛题目录后点「刷新」选用参赛者算法。选好后点击橙色「开始仿真」按钮启动。',
  },
  {
    target: '#entity-list',
    placement: 'right',
    title: '查看仿真三维画面',
    body: '仿真启动后，点击实体列表中任意一架无人机，界面下方会自动弹出该无人机的 UE 实时视频流小窗，可拖拽移动、双击放大全屏。',
    hint: '提示：需下载包含 UE 的安装包才可查看',
  },
];

/** 操作步总数(不含欢迎卡), 用于「第 N 步 / 共 2 步」与进度点。 */
const OP_STEP_COUNT = STEPS.length - 1;

/** 卡片宽度 —— 须与 .hf-tour-card { width: 300px } 保持一致。 */
const CARD_W = 300;
/** 卡片高度回退值(happy-dom 无布局, offsetHeight 为 0 时用此)。 */
const CARD_H_FALLBACK = 260;
/** 视口安全边距(px), 卡片不贴边。 */
const VP_MARGIN = 8;
/** 卡片与高亮目标之间的间距(px)。 */
const CARD_GAP = 24;

/** AI 火花星图标(四芒星 + 橙色火花), 内联 SVG。 */
const ICON_SVG = `<svg width="22" height="22" viewBox="0 0 64 64" fill="none" stroke="var(--accent)" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
  <path d="M32 8 L36 26 L54 30 L36 34 L32 52 L28 34 L10 30 L28 26 Z" fill="var(--accent)" fill-opacity="0.2"/>
  <path d="M48 10 L49.5 15 L54 16.5 L49.5 18 L48 23 L46.5 18 L42 16.5 L46.5 15 Z" fill="var(--cta)" stroke="var(--cta)" stroke-width="2"/>
  <path d="M14 44 L15 47.5 L18 48.5 L15 49.5 L14 53 L13 49.5 L10 48.5 L13 47.5 Z" fill="var(--cta)" stroke="var(--cta)" stroke-width="2"/>
</svg>`;

/** 引导样式(注入一次)。全部复用 :root design token, 零硬编码主题色。 */
const STYLE_CSS = `
.hf-tour-overlay {
  position: fixed; inset: 0; z-index: var(--z-pop);
  pointer-events: auto;
}
.hf-tour-highlight {
  position: absolute; border: 2px solid var(--accent); border-radius: 10px;
  box-shadow: 0 0 0 9999px rgba(0,0,0,0.72), 0 0 20px rgba(56,189,248,0.5);
  transition: all var(--transition);
}
.hf-tour-card {
  position: absolute; z-index: calc(var(--z-pop) + 1);
  width: 300px; background: var(--panel-bg-solid); opacity: 0.97;
  border: 1px solid rgba(56,189,248,0.5); border-radius: var(--panel-radius);
  padding: 16px; box-shadow: 0 8px 32px rgba(0,0,0,0.6);
  color: var(--text); font-family: inherit; transition: all var(--transition);
}
.hf-tour-card * { box-sizing: border-box; }
.hf-tour-top { display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px; }
.hf-tour-step-no { color: var(--accent); font-size: 10px; font-weight: 700; letter-spacing: 1px; text-transform: uppercase; }
.hf-tour-title { font-size: 16px; font-weight: 700; margin-bottom: 8px; }
.hf-tour-body { color: var(--text-dim); font-size: 12.5px; line-height: 1.65; margin-bottom: 0; }
.hf-tour-hint { color: var(--text-muted); font-size: 11px; line-height: 1.5; font-style: italic; margin: 8px 0 0; }
.hf-tour-dots { display: flex; gap: 6px; margin: 14px 0; }
.hf-tour-dot { height: 4px; border-radius: 2px; background: rgba(255,255,255,0.2); transition: width var(--transition); }
.hf-tour-dot.active { width: 24px; background: var(--cta); }
.hf-tour-dot.inactive { width: 8px; }
.hf-tour-actions { display: flex; justify-content: space-between; align-items: center; }
.hf-tour-btn-skip { color: var(--text-muted); font-size: 12px; background: none; border: none; cursor: pointer; padding: 4px 0; }
.hf-tour-btn-skip:hover { color: var(--text); }
.hf-tour-btn-next { background: var(--cta); color: #fff; font-size: 13px; font-weight: 600; padding: 8px 20px; border: none; border-radius: 8px; cursor: pointer; }
.hf-tour-btn-next:hover { background: var(--cta-hover); }
.hf-tour-btn-next.done { background: var(--ok); }
.hf-tour-arrow { position: absolute; width: 12px; height: 12px; background: var(--panel-bg-solid); }
.hf-tour-arrow.left { top: 50%; left: -6px; transform: translateY(-50%) rotate(45deg); border-bottom: 1px solid rgba(56,189,248,0.5); border-left: 1px solid rgba(56,189,248,0.5); }
.hf-tour-arrow.right { top: 50%; right: -6px; transform: translateY(-50%) rotate(45deg); border-top: 1px solid rgba(56,189,248,0.5); border-right: 1px solid rgba(56,189,248,0.5); }
@media (prefers-reduced-motion: reduce) {
  .hf-tour-card, .hf-tour-highlight { transition: none; }
}
`;

export class OnboardingTour {
  private currentIdx = 0;
  private active = false;
  private overlay: HTMLDivElement | null = null;
  private card: HTMLDivElement | null = null;
  private highlight: HTMLDivElement | null = null;
  private boundKeydown: (e: KeyboardEvent) => void = () => {};
  private boundReposition: () => void = () => {};

  /** 引导是否正在播放。 */
  get isActive(): boolean {
    return this.active;
  }

  /** 从欢迎卡开始播放引导。重复调用被忽略。 */
  start(): void {
    if (this.active) return;
    this.active = true;
    this.currentIdx = 0;
    this.injectStyle();
    this.buildDom();
    document.body.style.overflow = 'hidden';
    this.render();
    this.bindEvents();
  }

  /** 注入引导样式(仅一次)。 */
  private injectStyle(): void {
    if (document.getElementById('hf-tour-style')) return;
    const style = document.createElement('style');
    style.id = 'hf-tour-style';
    style.textContent = STYLE_CSS;
    document.head.appendChild(style);
  }

  /** 构建遮罩 + 高亮框 + 卡片骨架(一次性)。 */
  private buildDom(): void {
    this.overlay = document.createElement('div');
    this.overlay.className = 'hf-tour-overlay';

    this.highlight = document.createElement('div');
    this.highlight.className = 'hf-tour-highlight';
    this.overlay.appendChild(this.highlight);

    this.card = document.createElement('div');
    this.card.className = 'hf-tour-card';
    this.card.setAttribute('role', 'dialog');
    this.card.setAttribute('aria-modal', 'true');
    this.overlay.appendChild(this.card);

    document.body.appendChild(this.overlay);
  }

  /** 渲染当前步卡片: 欢迎卡居中, 操作步聚光灯定位。 */
  private render(): void {
    // currentIdx 始终落在 [0, STEPS.length-1] 内(由推进逻辑约束), 但
    // noUncheckedIndexedAccess 下 STEPS[idx] 仍是 TourStep | undefined,
    // 故用断言收窄; 若越界属于逻辑 bug, 应在源头修复而非在此兜底。
    const step = STEPS[this.currentIdx]!;
    const isWelcome = this.currentIdx === 0;
    const card = this.card!;

    // 步骤号: 欢迎卡不显示。
    const stepNoHtml = isWelcome ? '' : `<span class="hf-tour-step-no">第 ${this.currentIdx} 步 / 共 ${OP_STEP_COUNT} 步</span>`;
    // 提示小字: 仅第2步有。
    const hintHtml = step.hint ? `<p class="hf-tour-hint">${step.hint}</p>` : '';
    // 进度点: 仅操作步显示。
    const dotsHtml = isWelcome ? '' : this.renderDots();
    // 右侧按钮文案: 欢迎卡→开始引导, 末步→完成, 否则→下一步。
    const isLast = this.currentIdx === STEPS.length - 1;
    const btnText = isWelcome ? '开始引导' : isLast ? '完成 ✓' : '下一步 →';
    const btnClass = isLast ? 'hf-tour-btn-next done' : 'hf-tour-btn-next';

    card.innerHTML = `
      <div class="hf-tour-top">${stepNoHtml}${ICON_SVG}</div>
      <div class="hf-tour-title">${step.title}</div>
      <p class="hf-tour-body">${step.body}</p>
      ${hintHtml}
      ${dotsHtml}
      <div class="hf-tour-actions">
        <button class="hf-tour-btn-skip">跳过引导</button>
        <button class="${btnClass}">${btnText}</button>
      </div>`;

    // 高亮框: 欢迎卡隐藏(居中全暗)。
    this.highlight!.style.display = isWelcome ? 'none' : 'block';
    if (isWelcome) {
      this.centerCard();
    } else {
      this.positionCard(step);
    }
  }

  /** 进度点 HTML。 */
  private renderDots(): string {
    // currentIdx 是全局索引; 操作步从 1 开始, 映射到 0-based 进度位。
    const activePos = this.currentIdx - 1;
    let html = '<div class="hf-tour-dots">';
    for (let i = 0; i < OP_STEP_COUNT; i++) {
      html += `<span class="hf-tour-dot ${i === activePos ? 'active' : 'inactive'}"></span>`;
    }
    return html + '</div>';
  }

  /** 欢迎卡居中定位。 */
  private centerCard(): void {
    const card = this.card!;
    card.style.left = '50%';
    card.style.top = '50%';
    card.style.transform = 'translate(-50%, -50%)';
  }

  /** 聚光灯定位: 高亮目标 + 卡片贴边。目标缺失时降级居中。 */
  private positionCard(step: TourStep): void {
    const target = step.target ? document.querySelector(step.target) as HTMLElement | null : null;
    if (!target) {
      // 目标不存在 → 降级居中(保留步骤号/进度点/正文)。
      this.centerCard();
      this.highlight!.style.display = 'none';
      return;
    }
    const rect = target.getBoundingClientRect();

    // 1. 高亮框贴目标。
    const hl = this.highlight!;
    hl.style.display = 'block';
    hl.style.left = `${rect.left}px`;
    hl.style.top = `${rect.top}px`;
    hl.style.width = `${rect.width}px`;
    hl.style.height = `${rect.height}px`;

    // 2. 卡片定位: 按 placement 摆边, 超出视口则翻转到对侧。
    const card = this.card!;
    card.style.transform = 'none'; // 清除居中的 translate
    // happy-dom 无布局, offsetHeight 恒为 0 → 用回退值。
    const cardH = card.offsetHeight || CARD_H_FALLBACK;
    const vw = window.innerWidth;
    const vh = window.innerHeight;

    let place: CardPlacement = step.placement ?? 'right';
    // 边界兜底: 放不下就翻转。
    if (place === 'left' && rect.left - CARD_GAP - CARD_W < VP_MARGIN) place = 'right';
    if (place === 'right' && rect.right + CARD_GAP + CARD_W > vw - VP_MARGIN) place = 'left';
    // 翻转后还是放不下(两侧都窄) → 居中。
    const fitsLeft = rect.left - CARD_GAP - CARD_W >= VP_MARGIN;
    const fitsRight = rect.right + CARD_GAP + CARD_W <= vw - VP_MARGIN;
    if (!fitsLeft && !fitsRight) {
      this.centerCard();
      return;
    }

    if (place === 'left') {
      card.style.left = `${rect.left - CARD_GAP - CARD_W}px`;
      card.style.right = 'auto';
      this.setArrow('right'); // 箭头指向右侧目标
    } else {
      card.style.left = `${rect.right + CARD_GAP}px`;
      card.style.right = 'auto';
      this.setArrow('left'); // 箭头指向左侧目标
    }
    // 垂直居中于目标, 但不超出视口。
    let top = rect.top + rect.height / 2 - cardH / 2;
    top = Math.max(VP_MARGIN, Math.min(top, vh - cardH - VP_MARGIN));
    card.style.top = `${top}px`;
  }

  /** 设置卡片箭头方向(指向目标一侧)。 */
  private setArrow(side: 'left' | 'right'): void {
    const card = this.card!;
    const existing = card.querySelector('.hf-tour-arrow');
    if (existing) existing.remove();
    const arrow = document.createElement('div');
    arrow.className = `hf-tour-arrow ${side}`;
    card.appendChild(arrow);
  }

  /** 绑定按钮点击 + 键盘 + resize/scroll。 */
  private bindEvents(): void {
    // 按钮事件(事件委托, 避免 render 后重绑)。
    this.overlay!.addEventListener('click', (e) => {
      const t = e.target as HTMLElement;
      if (t.classList.contains('hf-tour-btn-next')) this.next();
      else if (t.classList.contains('hf-tour-btn-skip')) this.skip();
    });
    // 键盘: Esc 跳过, → 下一步。
    this.boundKeydown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') this.skip();
      else if (e.key === 'ArrowRight') this.next();
    };
    window.addEventListener('keydown', this.boundKeydown);
    // resize/scroll 重新定位当前步。
    this.boundReposition = () => {
      if (this.currentIdx > 0) this.positionCard(STEPS[this.currentIdx]!);
    };
    window.addEventListener('resize', this.boundReposition);
    window.addEventListener('scroll', this.boundReposition, true);
  }

  /** 推进到下一步; 末步则完成。 */
  private next(): void {
    if (!this.active) return;
    if (this.currentIdx >= STEPS.length - 1) {
      this.complete();
      return;
    }
    this.currentIdx++;
    this.render();
  }

  /** 跳过引导(销毁 + 标记已读)。 */
  private skip(): void {
    if (!this.active) return;
    this.teardown();
    OnboardingStorage.markCompleted();
    this.active = false;
  }

  /** 完成引导(销毁 + 标记已读)。
   *  公开出口(宿主/测试可直接调用); next/skip 仅供内部事件处理器调用。 */
  complete(): void {
    if (!this.active) return;
    this.teardown();
    OnboardingStorage.markCompleted();
    this.active = false;
  }

  /** 解绑事件 + 移除 DOM(供 skip/complete 共用, 不动 active 标志)。 */
  private teardown(): void {
    window.removeEventListener('keydown', this.boundKeydown);
    window.removeEventListener('resize', this.boundReposition);
    window.removeEventListener('scroll', this.boundReposition, true);
    this.overlay?.remove();
    this.overlay = null;
    this.card = null;
    this.highlight = null;
    document.body.style.overflow = '';
  }
}
