import * as THREE from 'three';
import { WGS84Projection, NavigationPathState } from '../core/wgs84-projection';

export interface PathConfig {
  color: number;
  lineWidth: number;
  waypointSize: number;
}

const DEFAULT_CONFIG: PathConfig = {
  color: 0x00ff00,
  lineWidth: 3,
  waypointSize: 2
};

export class NavigationPath {
  private pathLine: THREE.Line;
  private waypointMarkers: THREE.Mesh[] = [];
  private projection: WGS84Projection;
  private config: PathConfig;

  constructor(projection: WGS84Projection, config?: Partial<PathConfig>) {
    this.projection = projection;
    this.config = { ...DEFAULT_CONFIG, ...config };

    // Create path line
    const geometry = new THREE.BufferGeometry();
    const material = new THREE.LineBasicMaterial({
      color: this.config.color,
      linewidth: this.config.lineWidth
    });
    this.pathLine = new THREE.Line(geometry, material);
  }

  update(state: NavigationPathState): void {
    // Clear existing waypoints
    this.clearWaypoints();

    // Create path points
    const points: THREE.Vector3[] = [];
    const waypointGeometry = new THREE.SphereGeometry(this.config.waypointSize, 16, 16);
    const waypointMaterial = new THREE.MeshPhongMaterial({
      color: this.config.color,
      emissive: this.config.color,
      emissiveIntensity: 0.3
    });

    for (const waypoint of state.waypoints) {
      const point = this.projection.toVector3(
        waypoint.latitude,
        waypoint.longitude,
        waypoint.altitude
      );
      points.push(point);

      // Create waypoint marker
      const marker = new THREE.Mesh(waypointGeometry, waypointMaterial);
      marker.position.copy(point);
      this.waypointMarkers.push(marker);
    }

    // Update path line
    this.pathLine.geometry.dispose();
    this.pathLine.geometry = new THREE.BufferGeometry().setFromPoints(points);
  }

  private clearWaypoints(): void {
    for (const marker of this.waypointMarkers) {
      marker.geometry.dispose();
      if (Array.isArray(marker.material)) {
        marker.material.forEach(m => m.dispose());
      } else {
        marker.material.dispose();
      }
    }
    this.waypointMarkers = [];
  }

  setVisible(visible: boolean): void {
    this.pathLine.visible = visible;
    for (const marker of this.waypointMarkers) {
      marker.visible = visible;
    }
  }

  getPathLine(): THREE.Line {
    return this.pathLine;
  }

  getWaypointMarkers(): THREE.Mesh[] {
    return this.waypointMarkers;
  }

  getLine(): THREE.Group {
    const group = new THREE.Group();
    group.add(this.pathLine);
    for (const marker of this.waypointMarkers) {
      group.add(marker);
    }
    return group;
  }
}