// webpack 5 bundle shim: unmapped process.env.* reads must return
// undefined rather than throw "process is not defined" in the browser.
const g = globalThis as unknown as { process?: { env?: Record<string, unknown> } };
if (!g.process) g.process = { env: {} };

import { SceneManager } from './rendering/scene';
import { StateManager, SimulationState } from './core/state-manager';
import { RedisClient, ScoreSnapshot } from './core/redis-client';
import { WGS84Projection } from './core/wgs84-projection';
import { NavigationPath } from './rendering/navigation-path';
import { CommLinkRenderer } from './rendering/comm-link';
import { ScenarioSelectorPanel } from './ui/scenario-selector-panel';
import { SimControlClient } from './services/sim-control-client';
import { EntityInfoPanel } from './ui/entity-info-panel';
import { EntityListPanel } from './ui/entity-list-panel';
import { EventManager } from './core/event-manager';
import { EventWall } from './ui/event-wall';
import { TerrainRenderer } from './rendering/terrain';
// Spec 020 T7: extracted controllers + shared channel constants.
import { EntityManager } from './core/entity-manager';
import { ZoneController } from './core/zone-controller';
import { SelectionController } from './core/selection-controller';
import { CHANNELS } from './rendering/constants';
import { CameraPip } from './ui/camera-pip';
import { initHudPanel } from './ui/hud-panel';
import { CameraConsistency } from './services/camera-consistency';
// Spec 025: 实时评分浮动居中面板。
import { ScorePanel } from './ui/score-panel';
// 仿真结束结果总结弹窗(在 final 帧弹出,解决"得分闪一下就消失")。
import { ResultModal } from './ui/result-modal';
import { OnboardingTour } from './ui/onboarding/onboarding-tour';

// Configuration — channel names come from the shared constants module
// (Spec 020 T7) so redis-client.ts and this file share one source of truth.
const env = process.env;
// static-server.js 在 index.html <head> 末尾注入 window.__OPENSIM__={wsPort,camPort,camBaseUrl}。
// 这里读取并回落 8080/8081,让前端不再依赖硬编码(支持 start.ps1 的端口错开)。
const runtimeCfg: { wsPort?: number; camPort?: number; camWsPort?: number; camWsUrl?: string; camBaseUrl?: string } =
  (typeof window !== 'undefined' && (window as any).__OPENSIM__) || {};
const WS_PORT = runtimeCfg.wsPort ?? parseInt(env.WS_PORT || '8080', 10);
const CAM_PORT = runtimeCfg.camPort ?? parseInt(env.CAM_HTTP_PORT || '8081', 10);
const CAM_WS_PORT = runtimeCfg.camWsPort ?? parseInt(env.CAM_WS_PORT || '8082', 10);
const REDIS_CONFIG = {
  host: env.REDIS_HOST || 'localhost',
  port: WS_PORT,
  stateChannel: env.SIM_STATE_CHANNEL || CHANNELS.state,
  commandsChannel: env.SIM_COMMANDS_CHANNEL || CHANNELS.commands,
  entityCommandsChannel: env.ENTITY_COMMANDS_CHANNEL || CHANNELS.entityCommands,
  eventsChannel: env.SIM_EVENTS_CHANNEL || CHANNELS.events,
  entityIds: {
    uav: env.UAV_ENTITY_ID || '10002',
    target: env.TARGET_ENTITY_ID || '10001',
  },
};

// 仿真状态中英文映射(023 中文化)
const STATUS_CN: Record<string, string> = {
  running: '运行中', paused: '已暂停', ended: '已结束', idle: '待机',
};

// 022: bridge 相机帧 WebSocket URL(WS 推送模式,替代 HTTP 拉取)。
// 默认跟随当前页面 hostname,避免远程浏览器访问 <server-ip>:3000 时
// 仍请求浏览器本机的 localhost:8082。static-server 注入 camWsPort 时优先用。
const pageHost = typeof window !== 'undefined' ? window.location.hostname : 'localhost';
const CAM_WS_URL =
  runtimeCfg.camWsUrl ||
  env.CAM_WS_URL ||
  `ws://${pageHost}:${CAM_WS_PORT}`;
// 旧 HTTP 端点基址(保留:camera-pip 已迁移到 WS,此变量仅供后续兼容/降级)。
const CAM_BASE_URL =
  runtimeCfg.camBaseUrl ||
  env.CAM_BASE_URL ||
  `http://${pageHost}:${CAM_PORT}`;
// 多窗口:同时可开的相机小窗上限。临时(10 路压测):默认 10,LAYOUT_SLOTS
// 已扩到 10 槽。可经 CAM_MAX_WINDOWS 配置;超 10 截到 10,小于 1 取 1。
// 验证后可还原为 4。
const CAM_MAX_WINDOWS = Math.min(Math.max(parseInt(env.CAM_MAX_WINDOWS || '10', 10) || 10, 1), 10);

// Center coordinates (simulation area: East China Sea).
const CENTER_LAT = 27.0, CENTER_LON = 125.0;

class App {
  private sceneManager: SceneManager;
  private stateManager = new StateManager();
  private projection = new WGS84Projection(CENTER_LAT, CENTER_LON);
  private redisClient: RedisClient;

  private navigationPath: NavigationPath;
  private terrainRenderer: TerrainRenderer;
  private commLinkRenderer: CommLinkRenderer;
  // Spec 020 T7: behaviour previously inlined in this class now lives in the controllers below.
  private entityManager: EntityManager;
  private zoneController: ZoneController;
  private selection: SelectionController;
  // competition 场景选择面板(内含天气/种子配置 + 算法选择, 取代原独立 competition-config-panel)。
  private scenarioSelector: ScenarioSelectorPanel;
  private simControlClient: SimControlClient;
  // Spec 025: 实时评分浮动居中面板。
  private scorePanel: ScorePanel;
  // 仿真结束结果总结弹窗(final 帧触发)。
  private resultModal: ResultModal;
  /** 最近一次「开始仿真」的参数(scenario id / agent / 种子),供结果弹窗
   *  「再跑一次」复用 —— 避免用户回到场景面板重新点一遍。 */
  private lastStart?: { id: string; agent?: string; routeSeed?: number };
  /** 标记「用户刚点了开始/再跑一次,正在等待新会话首帧」。
   *  用于区分 onSession 收到的非 idle 状态是「用户主动开启的新会话」(需清掉上一轮
   *  评分/事件/相机)还是「页面刷新后 bridge 补推的进行中会话」(不清,保留运行态)。
   *  startSession() 置 true,onSession 首次非 idle 帧消费后回 false。 */
  private pendingNewSession = false;
  private sessionStatus = 'idle';
  private connectionIndicator = document.getElementById('connection-indicator')!;
  private connectionText = document.getElementById('connection-text')!;
  private simulationStatus = document.getElementById('simulation-status')!;
  private fpsDisplay = document.getElementById('fps-display')!;
  private entityInfoPanel: EntityInfoPanel;
  private entityListPanel: EntityListPanel;
  // Spec 018: 事件墙 —— 推流 sim:events → EventManager(ring buffer + dedup)
  // → EventWall(team filter 过滤 + 渲染)。sim 关闭时 EventManager.clear()
  // 清空,事件墙回到空态。
  private eventManager = new EventManager();
  private cameraPip: CameraPip;
  private cameraConsistency: CameraConsistency;
  private autoCentered = false;
  private onboardingTour = new OnboardingTour();
  /** 标记首次 WS 连接已完成(用于区分"首次连接"与"断线重连")。
   *  重连后需重新拉 /api/sim/status 同步 session 状态 —— 否则若 WS 在
   *  仿真运行期间断开,competition 已退出、bridge 已 idle,但前端 sessionStatus
   *  仍卡在断开前的 running,导致场景面板按钮"点不动"(Spec 600s 卡死根因)。 */
  private firstConnectionDone = false;

  constructor() {
    this.sceneManager = new SceneManager({ container: document.getElementById('canvas-container')! });
    this.navigationPath = new NavigationPath(this.projection);
    this.terrainRenderer = new TerrainRenderer(this.projection);
    this.commLinkRenderer = new CommLinkRenderer(this.projection);
    this.sceneManager.add(this.navigationPath.getLine());
    this.sceneManager.add(this.commLinkRenderer.getModel());
    this.entityInfoPanel = new EntityInfoPanel('entity-info-panel');
    this.entityListPanel = new EntityListPanel('entity-list-panel');
    // Spec 020 T7: build the controllers. Toggle readers let the
    // EntityManager inherit current checkbox state when spawning a renderer.
    this.entityManager = new EntityManager(
      this.sceneManager, this.projection, this.terrainRenderer, {
        trailVisible: () => this.toggleChecked('toggle-trails', true),
        gimbalFovVisible: () => this.toggleChecked('toggle-gimbal-fov', false),
      });
    // ZoneController must use the **same** WGS84 reference as the App's
    // projection (and the terrain / entity renderers); otherwise the
    // polygon overlay shifts by up to ~1500 m relative to the actual
    // WGS84 polygon that the backend uses for kill decisions, producing
    // the appearance of UAVs being killed outside the rendered bounding
    // box.
    this.zoneController = new ZoneController(
      this.sceneManager.getScene(),
      this.projection.getCenterLat(),
      this.projection.getCenterLon(),
    );
    this.selection = new SelectionController(
      this.sceneManager, this.stateManager, this.entityManager,
      this.entityInfoPanel, this.entityListPanel);
    this.stateManager.subscribe((s) => this.zoneController.update(s));
    this.stateManager.subscribe((s) => this.onStateUpdate(s));
    this.redisClient = new RedisClient(REDIS_CONFIG, this.stateManager);
    // Spec 018 接入: sim:events → EventManager → EventWall.render
    this.redisClient.onEvent((evt) => this.eventManager.push(evt));
    // competition 场景选择面板 + 仿真控制客户端。
    this.simControlClient = new SimControlClient({ baseUrl: CAM_BASE_URL });
    this.scenarioSelector = new ScenarioSelectorPanel('scenario-selector');
    this.scorePanel = new ScorePanel('score-panel');
    // 结果弹窗: 「再跑一次」用 lastStart 复刻启动; lastStart 在 onStart 里记录。
    this.resultModal = new ResultModal('result-modal', {
      onRerun: () => this.rerunLast(),
    });
    this.setupScenarioSelectorEvents();
    this.entityListPanel.onEntityClick((t, id) => this.selection.select(t, id));
    this.sceneManager.onEntityClick((t, id) => this.selection.select(t, id));
    this.setupUIHandlers();
    this.redisClient.onConnectionStateChanged((c) => this.updateConnectionStatus(c));
    this.cameraPip = new CameraPip({
      camWsUrl: CAM_WS_URL,
      maxWindows: CAM_MAX_WINDOWS,
      // × 关窗后清掉该 uid 的 selection —— 否则 syncCameraPip 下个 state tick
      // 又会 open(selUid) 把它开回来(尤其最后一个窗,selection 仍指向它 → 关不掉)。
      onClose: (uid) => {
        if (this.selection.selectedUid === uid) {
          this.selection.selectedUid = null;
          this.selection.selectedEntity = null;
          this.sceneManager.unfollow();
        }
      },
    });
    this.cameraConsistency = new CameraConsistency();
    this.setupHudPanels();
    // Spec 018: 初始化 EventWall UI(DOM 必须在 hud-panel class 装配后再挂)。
    try {
      new EventWall(this.eventManager);
    } catch (err) {
      console.warn('EventWall init skipped:', err);
    }
  }

  async start(): Promise<void> {
    this.sceneManager.start();
    try {
      await this.terrainRenderer.load('/heightmap.json');
      const mesh = this.terrainRenderer.getMesh();
      if (mesh) { this.sceneManager.add(mesh); this.sceneManager.setGridVisible(false); }
      const contour = this.terrainRenderer.getContourGroup();
      if (contour) this.sceneManager.add(contour);
    } catch (err) { console.error('Failed to load terrain:', err); }
    this.sceneManager.onPerformanceReport((r) => {
      this.fpsDisplay.textContent = ` | ${r.fps} FPS`;
      this.fpsDisplay.style.color = r.fps < 30 ? '#f44336' : r.fps < 60 ? '#ff9800' : '#4caf50';
    });
    // Spec 024: 接加载进度 + 会话状态回调(订阅在 connect 时触发)。
    this.redisClient.onProgress((p) => this.scenarioSelector.updateProgress(p.pct, p.phase));
    // Spec 025: sim:score 实时评分 → ScorePanel.update。
    this.redisClient.onScore((snap: ScoreSnapshot) => {
      this.scorePanel.update(snap);
      // 仿真结束的 final 帧 → 弹出结果总结弹窗 + 镜像一条「评分已保存」事件到
      // 事件墙。注意:旧逻辑在随后的 session:idle 里会 scorePanel.reset() +
      // eventManager.clear(), 把这两条都冲掉(根因); 现已把 reset/clear 挪到
      // 「下一次开始仿真」时执行, 让最终分与保存路径在 idle 间隙保留可见。
      if (snap.final) {
        this.resultModal.show(snap);
        if (snap.evaluation_path) {
          const score = snap.total_score ?? 0;
          this.eventManager.push({
            event_type: 'score.final_saved',
            source: { kind: 'kernel', producer: 'judge' },
            entity_uid: snap.profile ?? 'system',
            sim_time: snap.sim_time ?? 0,
            payload: {
              evaluation_path: snap.evaluation_path,
              total_score: score,
              passed: snap.passed,
              message: `最终评分 ${score.toFixed(1)} 分，已保存至 ${snap.evaluation_path}`,
            },
          });
        }
      }
    });
    this.redisClient.onSession((s) => {
      this.sessionStatus = s.status;
      this.scenarioSelector.updateStatus(s.status, s.error ?? undefined);
      // 用户主动开启的新会话首帧到达 → 清掉上一轮的评分/事件/相机, 让位给新一轮。
      // 这是 scorePanel.reset()/eventManager.clear() 的唯一合法触发点(旧逻辑放在
      // idle 分支会把刚到的 final 帧冲掉)。用 pendingNewSession 标志(由 startSession
      // 置位)而非 status 跃迁判断, 以排除「刷新后 bridge 补推的进行中会话」—— 后者
      // 不应清掉运行态(实时事件/相机窗)。
      if (s.status !== 'idle' && s.scenario && this.pendingNewSession) {
        this.pendingNewSession = false;
        this.scorePanel.reset();
        this.eventManager.clear();
        this.cameraPip.closeAll();  // 关掉上一轮残留的相机窗
      }
      // Spec 024: 关闭仿真回 idle → 重置「实体/导航/通信」等过程态。
      // 注意: scorePanel/eventManager/cameraPip 不在此清 —— 见上文新会话分支,
      // 它们保留上一轮最终结果供用户在 idle 时查看。
      if (s.status === 'idle') {
        this.stateManager.reset();
        this.entityInfoPanel.clear();
        this.commLinkRenderer.clear();  // 通信线(update({})仅 fade,reset后无tickFade)
      }
    });
    try {
      await this.redisClient.connect();
      this.updateConnectionStatus(true);
      this.simControlClient.getScenarios()
        .then((list) => {
          // 传完整数据(含 algorithms), 让风琴页展示官方/参赛者算法清单。
          this.scenarioSelector.setScenarios(
            list.map((s) => ({
              id: s.id, name: s.name, label: s.label, description: s.description,
              available: s.available,
              algorithms: (s.algorithms ?? []).map((a) => ({
                name: a.name, agentSpec: a.agentSpec, source: a.source,
                scenarioId: a.scenarioId ?? s.id, docstring: a.docstring,
              })),
            })));
          // 刷新后恢复进行中的会话(否则用户无法暂停/关闭已运行的仿真)。
          return this.simControlClient.getStatus();
        })
        .then((s) => {
          if (s && s.status !== 'idle' && s.scenario) {
            this.sessionStatus = s.status;
            this.scenarioSelector.selectById(s.scenario);
            this.scenarioSelector.updateStatus(s.status, s.error ?? undefined);
          }
        })
        .catch((e) => console.error('getScenarios/getStatus failed:', e));
      console.log('Application started');
    } catch (error) { console.error('Failed to start application:', error); }

    // 新手引导: 每次页面加载都自动播放(用户可跳过)。置于核心 try/catch
    // 之外 — 引导为锦上添花, 其失败不应影响核心连线/场景流程。start() 由
    // DOMContentLoaded 单次调用, 故 help-btn 监听不会重复绑定。
    const helpBtn = document.getElementById('help-btn');
    helpBtn?.addEventListener('click', () => this.onboardingTour.start());
    // 延迟 600ms 让首帧 HUD 就绪; 即便目标面板尚未渲染, 引导也会降级居中。
    window.setTimeout(() => this.onboardingTour.start(), 600);
  }

  private onStateUpdate(state: SimulationState): void {
    if (!this.autoCentered) {
      const uav = this.zoneController.findAnyUavPosition(state);
      if (uav) {
        this.sceneManager.moveCameraTo(this.projection.toVector3(uav.latitude, uav.longitude, uav.altitude));
        this.autoCentered = true;
      }
    }
    this.simulationStatus.textContent = ` | 状态: ${STATUS_CN[state.status] ?? state.status}`;
    // Clamp navigation waypoints to terrain surface.
    this.navigationPath.update({
      waypoints: state.path.waypoints.map(wp => ({
        ...wp, altitude: Math.max(wp.altitude, this.terrainRenderer.getElevation(wp.latitude, wp.longitude)),
      })),
    });
    this.selection.refreshFollow();
    this.entityInfoPanel.update(state, this.selection.selectedUid);
    if (state.entities) {
      this.entityManager.update(state.entities);
      this.commLinkRenderer.update(state.entities);
      this.entityListPanel.updateFromEntities(state.entities);
      this.selection.reconcileWithState();
      this.cameraConsistency.update(state);
      this.syncCameraPip(state);
    }
  }

  // 022: 选中 UAV → 打开该飞机的相机画中画(多窗口:已开则忽略,达上限 warn)。
  // 选中非 UAV(target/gimbal)时**不关闭**已开相机窗 —— 多窗口场景下,查看
  // 目标信息不应打断正在观察的多路相机画面。关闭单窗由窗口 × 按钮触发,
  // 全部关闭随仿真结束(idle reset)在 onSession 里 closeAll()。
  private syncCameraPip(state: SimulationState): void {
    const selUid = this.selection.selectedUid;
    const selEnt = selUid && state.entities ? state.entities[selUid] : undefined;
    const isUav = !!selEnt && selEnt.kind === 'uav';
    if (isUav && selUid) {
      this.cameraPip.open(selUid);  // 追加语义:已开幂等,达上限 warn
    }
  }

  /** competition 场景选择面板事件接线(开始 / 暂停-恢复 / 关闭 / 天气 / 种子 / 刷新)。 */
  private setupScenarioSelectorEvents(): void {
    this.scenarioSelector.on('onStart', (id: string, agent?: string, routeSeed?: number) => {
      this.lastStart = { id, agent, routeSeed };
      this.startSession(id, agent, routeSeed);
    });
    this.scenarioSelector.on('onPauseResume', () => {
      if (this.sessionStatus === 'running') {
        this.simControlClient.pause().catch((e) => console.error('sim pause failed:', e));
      } else if (this.sessionStatus === 'paused') {
        this.simControlClient.resume().catch((e) => console.error('sim resume failed:', e));
      }
    });
    this.scenarioSelector.on('onClose', () => {
      this.simControlClient.stop().catch((e) => console.error('sim stop failed:', e));
    });
    // 刷新按钮: 重新拉取当前赛题的参赛者算法, 更新面板(保留仍存在的选中)。
    this.scenarioSelector.on('onRefresh', (scenarioId: string) => {
      this.simControlClient.getAlgorithms(scenarioId)
        .then((algos) => {
          this.scenarioSelector.refreshAlgos(scenarioId, algos.map((a) => ({
            name: a.name, agentSpec: a.agentSpec, source: a.source,
            scenarioId: a.scenarioId ?? scenarioId, docstring: a.docstring,
          })));
        })
        .catch((e) => console.error('refresh algorithms failed:', e));
    });
    // 天气 / 蓝方随机种子变更: 仅记录诊断日志(用于追踪用户调整; 实际生效以 onStart 时的 snapshot 为准)。
    this.scenarioSelector.on('onWeatherChange', (weather) => {
      console.log('[scenario-selector] weather changed:', weather);
    });
    this.scenarioSelector.on('onRouteSeedChange', (seed) => {
      console.log('[scenario-selector] route seed changed:', seed);
    });
  }

  /** 启动一次仿真(scenario / agent / 种子)。被 onStart 与结果弹窗的「再跑一次」共用,
   *  避免两处复制粘贴启动链路(setWeather → start + 乐观进度 + 错误降级)。 */
  private startSession(id: string, agent?: string, routeSeed?: number): void {
    // 标记「用户主动开启新会话」, 供 onSession 在首帧到达时清掉上一轮评分/事件。
    this.pendingNewSession = true;
    // 乐观更新: 点击即显示进度条, 不等 bridge 异步推送 starting/loading
    // (bridge 要走 setWeather HTTP → start HTTP → spawn competition 才推送状态,
    // 全程十多秒, 此前无任何反馈)。给 5% 初始可见进度让蓝色 fill 立即可见
    // (0% 时 fill 宽度为 0 视觉上像没反应); updateProgress 用 Math.max 高水位,
    // bridge 真实进度(sim:progress)到达后无缝接续, 不会回退。
    this.scenarioSelector.updateStatus('loading');
    this.scenarioSelector.updateProgress(0.05, '正在启动仿真…');
    // 启动前先把当前选中的天气写回赛题想定(就地改 scenario.json),
    // bridge 启动时会原样拷贝到 UE,UE 读 weather 字段渲染。写回失败降级(仅日志),不阻塞启动。
    const weather = this.scenarioSelector.getWeather();
    this.simControlClient.setWeather(id, weather)
      .catch((e) => console.warn('set weather failed (启动继续):', e))
      .finally(() => {
        // 车辆随机路线种子(可选): 正整数才透传给后端; 否则不传。
        // photoMode 默认 auto: 非 dry_run 时启动 PhotoCache, Redis 有相机帧则
        // 注入 obs.self.photo, 无帧安全降级为 None(不报错)。带 UE 的标准环境
        // 下 UE 经 bridge 往 Redis 推帧, 前端无需额外勾选即可让参赛算法拿到画面。
        this.simControlClient.start(id, agent, { photoMode: 'auto' }, routeSeed)
          .catch((e) => {
            console.error('sim start failed:', e);
            this.scenarioSelector.updateStatus('error', '仿真启动失败，请查看后端日志');
          });
      });
  }

  /** 结果弹窗「再跑一次」: 用上次会话参数重新启动。无上次参数则忽略。 */
  private rerunLast(): void {
    if (!this.lastStart) {
      console.warn('rerun: no previous start parameters recorded');
      return;
    }
    this.startSession(this.lastStart.id, this.lastStart.agent, this.lastStart.routeSeed);
  }

  private setupUIHandlers(): void {
    this.onChange('toggle-trails', (v) => this.entityManager.setTrailsVisible(v));
    this.onChange('toggle-gimbal-fov', (v) => this.entityManager.setGimbalFovVisible(v));
    this.onChange('toggle-navigation-path', (v) => this.navigationPath.setVisible(v));
    this.onChange('toggle-terrain', (v) => this.terrainRenderer.setVisible(v));
  }

  /** 023: make every [data-hud-panel] collapsible + draggable. All panels
   *  start expanded (user can collapse/drag any of them). */
  private setupHudPanels(): void {
    document.querySelectorAll<HTMLElement>('[data-hud-panel]').forEach((panel) => {
      initHudPanel(panel, { draggable: true });
    });
  }

  private toggleChecked(id: string, fallback: boolean): boolean {
    const el = document.getElementById(id) as HTMLInputElement | null;
    return el ? el.checked : fallback;
  }

  private onChange(id: string, fn: (checked: boolean) => void): void {
    const el = document.getElementById(id) as HTMLInputElement | null;
    el?.addEventListener('change', (e) => fn((e.target as HTMLInputElement).checked));
  }

  private updateConnectionStatus(connected: boolean): void {
    this.connectionIndicator.className = `connection-status ${connected ? 'connected' : 'disconnected'}`;
    this.connectionText.textContent = connected ? '已连接' : '未连接';
    this.simulationStatus.textContent = connected ? '' : ' | 等待连接';
    // 断线重连后重新拉 session 状态同步 —— WS 断开期间 competition 可能已退出
    // (bridge session 已 idle),但前端 sessionStatus 仍卡在旧值(running),
    // 导致场景面板按钮状态不刷新。首次连接的同步由 start() 末尾负责,此处只管重连。
    if (connected && this.firstConnectionDone) {
      this.syncSessionAfterReconnect();
    } else if (connected) {
      this.firstConnectionDone = true;
    }
  }

  /** 重连后拉 /api/sim/status 并同步到 scenario 面板(修正按钮状态)。 */
  private syncSessionAfterReconnect(): void {
    this.simControlClient.getStatus()
      .then((s) => {
        this.sessionStatus = s.status;
        this.scenarioSelector.updateStatus(s.status, s.error ?? undefined);
        // 若 bridge 已 idle(仿真已结束)但前端还停在 running,这里会把它修正回 idle,
        // 从而触发 updateButtonStates 恢复「开始仿真」按钮可用。
      })
      .catch((e) => console.error('reconnect status sync failed:', e));
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const app = new App();
  (window as unknown as { app: App }).app = app;
  app.start();
});
